(1236, 107, '2.4(a)-L01', 'Concept of arrays', '2026-07-17 12:34:52'),
(1237, 107, '2.4(a)-L02', 'Advantages of arrays over individual variables', '2026-07-17 12:34:52'),
(1238, 107, '2.4(a)-L03', 'Array terminology: index, element and size', '2026-07-17 12:34:52'),
(1239, 107, '2.4(a)-L04', 'Declaring a single dimensional array', '2026-07-17 12:34:52'),
(1240, 107, '2.4(a)-L05', 'Initializing an array at declaration', '2026-07-17 12:34:52'),
(1241, 107, '2.4(a)-L06', 'Assigning values to array elements', '2026-07-17 12:34:52'),
(1242, 107, '2.4(a)-L07', 'Reading array values from user input', '2026-07-17 12:34:52'),
(1243, 107, '2.4(a)-L08', 'Array size and bounds', '2026-07-17 12:34:52'),
(1244, 107, '2.4(a)-L09', 'Arrays of different data types', '2026-07-17 12:34:52'),
(1245, 107, '2.4(a)-L10', 'Memory representation of arrays', '2026-07-17 12:34:52'),
(1246, 107, '2.4(a)-L11', 'Common errors in array declaration', '2026-07-17 12:34:52'),
(1247, 107, '2.4(a)-L12', 'Using constants for array size', '2026-07-17 12:34:52'),
(1248, 107, '2.4(a)-L13', 'Copying arrays', '2026-07-17 12:34:52'),
(1249, 107, '2.4(a)-L14', 'Using loops to initialize arrays', '2026-07-17 12:34:52'),
(1250, 107, '2.4(a)-L15', 'Debugging array declaration problems', '2026-07-17 12:34:52'),
(1251, 107, '2.4(a)-L16', 'Integrated practice: array declaration and initialization exercise', '2026-07-17 12:34:52');
INSERT INTO `elements` (`id`, `unit_id`, `code`, `title`, `created_at`) VALUES
(1252, 107, '2.4(b)-L01', 'Accessing an array element by index', '2026-07-17 12:34:52'),
(1253, 107, '2.4(b)-L02', 'Modifying values of array elements', '2026-07-17 12:34:52'),
(1254, 107, '2.4(b)-L03', 'Printing all array elements using a loop', '2026-07-17 12:34:52'),
(1255, 107, '2.4(b)-L04', 'Printing array elements in reverse order', '2026-07-17 12:34:52'),
(1256, 107, '2.4(b)-L05', 'Computing the sum and average of array elements', '2026-07-17 12:34:52'),
(1257, 107, '2.4(b)-L06', 'Finding the maximum and minimum elements', '2026-07-17 12:34:52'),
(1258, 107, '2.4(b)-L07', 'Searching an element using linear search', '2026-07-17 12:34:52'),
(1259, 107, '2.4(b)-L08', 'Counting occurrences of a value in an array', '2026-07-17 12:34:52'),
(1260, 107, '2.4(b)-L09', 'Sorting array elements using bubble sort', '2026-07-17 12:34:52'),
(1261, 107, '2.4(b)-L10', 'Formatting array output', '2026-07-17 12:34:52'),
(1262, 107, '2.4(b)-L11', 'Out of bounds errors and their handling', '2026-07-17 12:34:52'),
(1263, 107, '2.4(b)-L12', 'Passing arrays to functions', '2026-07-17 12:34:52'),
(1264, 107, '2.4(b)-L13', 'Arrays in a menu-driven program', '2026-07-17 12:34:52'),
(1265, 107, '2.4(b)-L14', 'Real-world data storage using arrays', '2026-07-17 12:34:52'),
(1266, 107, '2.4(b)-L15', 'Debugging array access problems', '2026-07-17 12:34:52'),
(1267, 107, '2.4(b)-L16', 'Integrated practice: an array processing project', '2026-07-17 12:34:52');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(1, 1, 3, 'introduction', 5, 'Display a picture related to computers and daily life. Ask students: What is Computer Science? Where do we see it in our daily life?', 'Observe the picture and respond to questions about the concept of Computer Science.', 'Questions about the meaning and importance of Computer Science are answered correctly.'),
(2, 1, 2, 'development', 20, 'Provide handouts with content on Computer Science concepts. Guide students in groups to discuss the meaning, importance, and applications of Computer Science. Display examples of CS applications (medicine, agriculture, banking).', 'Read handouts, discuss in groups, and share findings on the meaning, importance, and applications of Computer Science.', 'The concept of Computer Science including its meaning, importance, and application is explained correctly.'),
(3, 1, 2, 'design', 10, 'Ask groups to identify one real-life application of Computer Science in their community and explain how it relates to the concepts learned.', 'In groups, name a real-life CS application and explain how Computer Science concepts apply to it.', 'A real-life application of Computer Science is correctly identified and explained.'),
(4, 1, 3, 'realisation', 5, 'Each student picks a card with a CS application and explains how it demonstrates the concept of Computer Science.', 'Pick a card and explain the Computer Science concept demonstrated in the given application.', 'The concept of Computer Science in a given application is correctly explained by each student.'),
(5, 2, 5, 'introduction', 5, 'Ask students to brainstorm: In how many ways do you use or see computers being used around you?', 'Brainstorm and share various uses of computers observed in their environment.', 'Various applications of Computer Science in daily life are mentioned.'),
(6, 2, 2, 'development', 20, 'Guide students in groups to discuss and list applications of Computer Science in fields such as education, health, banking, agriculture, and entertainment. Use projected images for each field.', 'Discuss in groups and list applications of Computer Science in different fields. Share findings with the class.', 'Applications of Computer Science in at least four fields are correctly identified and described.'),
(7, 2, 7, 'design', 10, 'Present a case study: a hospital using computer systems for patient records. Ask students to identify which Computer Science applications are in use.', 'Analyse the case study and identify the Computer Science applications being used in the hospital scenario.', 'Computer Science applications in a given real-world scenario are correctly identified.'),
(8, 2, 3, 'realisation', 5, 'Ask each student to name one application of Computer Science in a field of their choice and explain its importance.', 'Name and explain one application of Computer Science in a chosen field.', 'An application of Computer Science and its importance in a specific field is correctly explained.'),
(9, 3, 5, 'introduction', 5, 'Ask students: What careers or jobs do you think involve Computer Science? List responses on the board.', 'Brainstorm and suggest careers and fields that involve Computer Science.', 'Fields related to Computer Science are mentioned by students.'),
(10, 3, 2, 'development', 20, 'Provide handouts listing fields related to Computer Science (Software Engineering, Networking, AI, Cybersecurity, Data Science, etc.). Guide group discussion on each field and its role.', 'Read handouts and discuss in groups the different fields related to Computer Science and their roles.', 'Fields related to Computer Science are correctly identified and described.'),
(11, 3, 12, 'design', 10, 'Assign each group a field to research briefly using textbooks or handouts and present a summary to the class.', 'Research an assigned field and present a brief summary of what it involves.', 'A field related to Computer Science is correctly researched and presented.'),
(12, 3, 3, 'realisation', 5, 'Each student states one field related to Computer Science and describes what professionals in that field do.', 'State one field related to Computer Science and describe the work done in that field.', 'A field related to Computer Science and associated professional activities are correctly described.'),
(13, 4, 1, 'introduction', 5, 'Display a diagram of a computer system showing input, process, output, and storage. Ask: What do you see? What is the role of each part?', 'Observe the diagram and respond to questions about the parts and roles in a computer system.', 'Parts of a computer system are identified and their roles described.'),
(14, 4, 1, 'development', 20, 'Demonstrate a working computer system. Explain the components: hardware, software, data, and users. Use diagrams to show how components interact. Guide Q&A session.', 'Observe the demonstration, take notes, and participate in Q&A on the components and interaction of a computer system.', 'Components of a computer system and their interactions are correctly described.'),
(15, 4, 2, 'design', 10, 'In groups, ask students to draw a simple diagram of a computer system and label all components showing data flow.', 'Draw and label a diagram of a computer system showing input, processing, output, and storage components.', 'A correctly labelled diagram of a computer system showing data flow is produced.'),
(16, 4, 3, 'realisation', 5, 'Each student explains the role of one component of a computer system in their own words.', 'Explain the role of one assigned computer system component.', 'The role of a computer system component is correctly explained.'),
(17, 5, 3, 'introduction', 5, 'Show images of computers from different eras. Ask: How have computers changed over time? What differences do you notice?', 'Observe images and respond to questions on how computers have evolved over time.', 'Observable differences between old and modern computers are described.'),
(18, 5, 2, 'development', 20, 'Provide a chart comparing the five generations of computers (technology used, size, speed, cost, examples). Guide group discussion on characteristics of each generation.', 'Study the chart, discuss in groups, and identify characteristics of each generation of computers.', 'Characteristics of all five generations of computers are correctly identified and compared.'),
(19, 5, 6, 'design', 10, 'Ask groups to arrange generation cards in chronological order and match each generation with its key technology and example.', 'Arrange generation cards chronologically and match each with its technology and example.', 'Generations of computers are correctly arranged and matched with their technologies.'),
(20, 5, 3, 'realisation', 5, 'Each student describes one generation of computers including its technology and an example.', 'Describe one assigned generation of computers including its defining technology and an example.', 'A generation of computers with its technology and example is correctly described.'),
(21, 6, 5, 'introduction', 5, 'Show images of different types of computers (supercomputer, mainframe, PC, laptop, tablet, smartphone). Ask: Are these all the same type of computer?', 'Observe images and identify similarities and differences between the computers shown.', 'Differences between types of computers are observed and described.'),
(22, 6, 2, 'development', 20, 'Guide students in groups to classify computers by size (supercomputer, mainframe, minicomputer, microcomputer), by purpose (general/special purpose), and by type (analog, digital, hybrid). Use handouts with descriptions and examples.', 'Using handouts, classify computers by size, purpose, and type. Share classifications with the class.', 'Computers are correctly classified by size, purpose, and type with appropriate examples.'),
(23, 6, 7, 'design', 10, 'Present descriptions of three computers and ask groups to classify each by size, purpose, and type with justification.', 'Classify given computers by size, purpose, and type and justify the classifications.', 'Given computers are correctly classified with appropriate justifications.'),
(24, 6, 3, 'realisation', 5, 'Each student names one type of computer and correctly classifies it by size, purpose, and type.', 'Name one type of computer and classify it by size, purpose, and type.', 'A computer type is correctly named and classified.'),
(25, 7, 3, 'introduction', 5, 'Point to physical parts of a computer in the classroom. Ask: Which parts can you touch? What do we call these physical parts?', 'Point to and name physical computer parts in the classroom.', 'Physical parts of a computer (hardware) are identified.'),
(26, 7, 1, 'development', 20, 'Demonstrate by disassembling or displaying computer components. Explain the concept of hardware: all physical components of a computer. Categorise into input, output, processing, and storage hardware.', 'Observe the demonstration and take notes on the definition and categories of computer hardware.', 'The concept of computer hardware and its categories are correctly described.'),
(27, 7, 2, 'design', 10, 'Provide a set of hardware images. Ask groups to sort them into input, output, processing, and storage categories.', 'Sort provided hardware images into the correct categories: input, output, processing, and storage.', 'Computer hardware components are correctly sorted into their appropriate categories.'),
(28, 7, 3, 'realisation', 5, 'Each student picks a hardware image and states its name and category.', 'Pick a hardware image, state its name and the category it belongs to.', 'A hardware component is correctly named and categorised.'),
(29, 8, 3, 'introduction', 5, 'Hold up a keyboard and mouse. Ask: What are these? What do we use them for? Can you name other devices used to enter data into a computer?', 'Identify the displayed devices and suggest other devices used to enter data into a computer.', 'Common input devices are identified and their purpose stated.'),
(30, 8, 4, 'development', 20, 'Display various input devices (keyboard, mouse, scanner, microphone, webcam, joystick, touchscreen). Demonstrate each device and explain its function. Allow students to handle available devices.', 'Observe demonstrations and handle available input devices. Identify each device and describe its function.', 'Input devices are correctly identified and their functions accurately described.'),
(31, 8, 4, 'design', 10, 'Ask groups to match input devices to their uses from a set of scenario cards (e.g., typing a document, scanning a document, recording audio).', 'Match input devices to appropriate use scenarios and explain the matching.', 'Input devices are correctly matched to their appropriate use scenarios.'),
(32, 8, 3, 'realisation', 5, 'Each student picks an input device card and explains what it is used for.', 'Pick an input device card and explain the function of that device.', 'The function of a given input device is correctly explained.'),
(33, 9, 1, 'introduction', 5, 'Show an image of a CPU and ask: What is this? What does it do inside the computer? Why is it called the brain of the computer?', 'Observe the CPU image and respond to questions about its role in a computer.', 'The CPU is identified and its general role described.'),
(34, 9, 1, 'development', 20, 'Demonstrate or display CPU components (ALU, CU, registers, cache). Explain the function of each component. Use a diagram showing how data flows through the CPU.', 'Observe the demonstration, study the CPU diagram, and take notes on the components and functions of the CPU.', 'Components of the CPU and their functions are correctly identified and described.'),
(35, 9, 2, 'design', 10, 'In groups, ask students to draw and label a diagram of the CPU showing ALU, CU, and registers with arrows showing data flow.', 'Draw and label a CPU diagram showing ALU, Control Unit, and registers with data flow arrows.', 'A correctly labelled CPU diagram with data flow is produced.'),
(36, 9, 3, 'realisation', 5, 'Each student explains the function of one CPU component assigned to them.', 'Explain the function of the assigned CPU component.', 'The function of a CPU component is correctly explained.'),
(37, 10, 5, 'introduction', 5, 'Show a USB drive and hard disk. Ask: What are these? Where do we store our files? What other storage devices do you know?', 'Identify the displayed storage devices and name other storage devices they know.', 'Common storage devices are identified.'),
(38, 10, 4, 'development', 20, 'Display and demonstrate various storage devices (HDD, SSD, USB drive, CD/DVD, memory card, cloud storage). Classify as primary (RAM, ROM) and secondary storage. Explain capacity and speed differences.', 'Handle and observe storage devices. Classify them as primary or secondary storage and note their capacity and uses.', 'Storage devices are correctly classified as primary or secondary and their capacities and uses described.'),
(39, 10, 2, 'design', 10, 'Ask groups to arrange storage devices from smallest to largest capacity and from slowest to fastest access speed.', 'Arrange storage devices by capacity and speed and justify the order.', 'Storage devices are correctly arranged by capacity and speed with justification.'),
(40, 10, 3, 'realisation', 5, 'Each student picks a storage device card and states whether it is primary or secondary storage and gives one use.', 'Pick a storage device card, classify it as primary or secondary, and give one use.', 'A storage device is correctly classified and one use stated.'),
(41, 11, 3, 'introduction', 5, 'Point to the monitor and speakers in the classroom. Ask: What are these? What information do they give us? What do we call devices that give us results from the computer?', 'Identify the monitor and speakers and describe what information they provide.', 'Output devices are identified and their purpose described.'),
(42, 11, 1, 'development', 20, 'Display various output devices (monitor, printer, speakers, projector, headphones, plotter). Demonstrate each and explain its function. Classify as softcopy (monitor, speakers) and hardcopy (printer, plotter) output devices.', 'Observe demonstrations of output devices and classify them as softcopy or hardcopy output devices.', 'Output devices are correctly identified, demonstrated, and classified as softcopy or hardcopy.'),
(43, 11, 2, 'design', 10, 'Provide scenario cards (e.g., printing a report, watching a video, listening to music). Ask groups to select the appropriate output device for each scenario.', 'Match each scenario to the most appropriate output device and justify the choice.', 'Appropriate output devices are correctly matched to given scenarios with justification.'),
(44, 11, 3, 'realisation', 5, 'Each student names one output device, states its type (softcopy/hardcopy), and gives one use.', 'Name one output device, state its type, and give one use.', 'An output device is correctly named, typed, and one use given.'),
(45, 12, 3, 'introduction', 5, 'Ask students: Can you touch Microsoft Word? Can you touch Windows? What makes the computer do what we want it to do? Introduce the concept of software.', 'Respond to questions and discuss what software is and how it differs from hardware.', 'The difference between hardware and software is stated.'),
(46, 12, 2, 'development', 20, 'Guide students in groups to discuss: what software is, the two main categories (system software and application software), and examples of each. Use a comparison chart on the board.', 'Discuss in groups and complete a comparison chart of system software and application software with examples.', 'The concept of software, its categories, and examples of each are correctly described.'),
(47, 12, 6, 'design', 10, 'Provide software name cards. Ask groups to sort them into system software and application software categories.', 'Sort software name cards into system software and application software categories.', 'Software is correctly sorted into system or application software categories.'),
(48, 12, 3, 'realisation', 5, 'Each student names the two main categories of software and gives one example of each.', 'Name the two main categories of software and give one example of each.', 'Two software categories are correctly named with appropriate examples.'),
(49, 13, 1, 'introduction', 5, 'Start a computer and ask: What loaded first when we turned on this computer? What is controlling how the computer works right now? Introduce system software.', 'Observe the computer start-up and respond to questions about what controls the computer operations.', 'System software is identified as the software that controls computer operations.'),
(50, 13, 1, 'development', 20, 'Demonstrate system software on a computer: show the operating system (Windows/Linux), utility programs (disk cleanup, antivirus), and language translators. Explain the function of each type.', 'Observe demonstrations and take notes on types and functions of system software.', 'Types of system software and their functions are correctly identified and described.'),
(51, 13, 2, 'design', 10, 'Ask groups to list all system software visible on the lab computers and classify each as OS, utility, or language translator.', 'Identify and list system software on lab computers and classify each type.', 'System software on a computer is correctly identified and classified.'),
(52, 13, 3, 'realisation', 5, 'Each student names one type of system software and explains its function.', 'Name one type of system software and explain its function.', 'A type of system software and its function are correctly stated.'),
(53, 14, 5, 'introduction', 5, 'Ask: What programs do you use on a computer or phone to do specific tasks like writing, playing music, or browsing? These are application software.', 'Brainstorm and name programs they use for specific tasks.', 'Common application software used in daily life is mentioned.'),
(54, 14, 2, 'development', 20, 'Guide groups to identify and classify application software: word processors, spreadsheets, browsers, media players, educational software, accounting software. Discuss examples and uses.', 'Classify provided application software into categories and describe the use of each.', 'Application software is correctly classified into categories with appropriate examples and uses.'),
(55, 14, 4, 'design', 10, 'Allow students to open two application programs on the lab computers and identify their category and use.', 'Open two application programs, identify their category, and describe their use.', 'Application programs are correctly identified, categorised, and their uses described.'),
(56, 14, 3, 'realisation', 5, 'Each student names one application software, states its category, and gives its main use.', 'Name one application software, state its category, and give its main use.', 'Application software is correctly named, categorised, and its main use stated.'),
(57, 15, 3, 'introduction', 5, 'Ask: How do we get new programs onto our computers? What steps do you think are involved in installing software?', 'Suggest steps they think are involved in installing software on a computer.', 'General steps for installing software are suggested.'),
(58, 15, 1, 'development', 20, 'Demonstrate the software installation process step by step: downloading/inserting media, running the installer, accepting license, choosing installation path, completing installation. Show on projector.', 'Observe the demonstration and note each step of the software installation process.', 'The steps of the software installation process are correctly identified and described.'),
(59, 15, 9, 'design', 10, 'Guide students in pairs to install a simple free application on the lab computers following the demonstrated steps.', 'In pairs, install an assigned application on the lab computer following the correct installation steps.', 'Software is correctly installed on a computer following the proper procedure.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(60, 15, 3, 'realisation', 5, 'Each student lists the steps of software installation in the correct order.', 'List the steps of software installation in the correct order.', 'Steps of software installation are listed in the correct order.'),
(61, 16, 3, 'introduction', 5, 'Show an image of a damaged computer and a well-maintained one. Ask: What differences do you see? Why do you think one is damaged? How can we prevent this?', 'Observe images and discuss reasons for computer damage and how it can be prevented.', 'Reasons for computer damage and prevention measures are suggested.'),
(62, 16, 2, 'development', 20, 'Guide group discussion on the concept of computer handling and care: definition, importance, general principles (keep clean, avoid liquids, handle with care, proper shutdown, surge protection).', 'Discuss and list principles of computer handling and care and explain the importance of each.', 'The concept of computer handling and care and its importance are correctly described.'),
(63, 16, 7, 'design', 10, 'Present a case study of a school computer lab where computers break down frequently. Ask groups to identify poor handling practices and suggest improvements.', 'Analyse the case study, identify poor handling practices, and suggest correct handling procedures.', 'Poor handling practices are correctly identified and appropriate care procedures suggested.'),
(64, 16, 3, 'realisation', 5, 'Each student states one principle of computer handling and care and explains why it is important.', 'State one principle of computer handling and care and explain its importance.', 'A principle of computer handling and care and its importance are correctly stated.'),
(65, 17, 1, 'introduction', 5, 'Show cleaning tools (compressed air, soft cloth, brush). Ask: What are these used for? Do you think cleaning is part of caring for a computer?', 'Identify cleaning tools and suggest how they are used in computer care.', 'Hardware cleaning tools are identified and their use suggested.'),
(66, 17, 9, 'development', 20, 'Demonstrate hardware care procedures: cleaning the keyboard, monitor, mouse, and system unit. Show how to check and secure cable connections. Demonstrate proper shutdown procedure.', 'Observe demonstrations and practise hardware care procedures on available equipment.', 'Hardware care procedures are correctly demonstrated on computer components.'),
(67, 17, 9, 'design', 10, 'Guide students in groups to perform a hardware care routine on the lab computers under supervision.', 'Perform a hardware care routine on the lab computer including cleaning and checking connections.', 'A hardware care routine is correctly performed on a computer system.'),
(68, 17, 3, 'realisation', 5, 'Each student describes one hardware care procedure and explains how it protects the computer.', 'Describe one hardware care procedure and explain how it protects the computer.', 'A hardware care procedure and its protective function are correctly described.'),
(69, 18, 5, 'introduction', 5, 'Ask: Have you ever lost data because of a virus or accidental deletion? What can we do to protect our software and data?', 'Share experiences of software or data loss and suggest ways to protect software and data.', 'Software care needs are identified based on shared experiences.'),
(70, 18, 1, 'development', 20, 'Demonstrate software care procedures: running antivirus scan, updating software, creating backups, avoiding pirated software, proper file organisation. Show on a lab computer.', 'Observe demonstrations and take notes on software care procedures and their importance.', 'Software care procedures are correctly identified and their importance explained.'),
(71, 18, 9, 'design', 10, 'Guide students to perform software care tasks on lab computers: run a virus scan, check for updates, and back up a file.', 'Perform software care tasks including running a virus scan, checking updates, and backing up a file.', 'Software care tasks are correctly performed on a lab computer.'),
(72, 18, 3, 'realisation', 5, 'Each student names one software care procedure and explains why it is important.', 'Name one software care procedure and explain its importance.', 'A software care procedure and its importance are correctly stated.'),
(73, 19, 3, 'introduction', 5, 'Ask: Is it safe to use a computer in the rain? What about eating while using a computer? What safety rules should we follow?', 'Respond to questions and suggest safety rules for using computers.', 'Basic computer safety rules are suggested.'),
(74, 19, 2, 'development', 20, 'Guide group discussion on safe handling practices: ergonomic posture, safe distance from monitor, avoiding static electricity, not blocking ventilation, handling cables safely, electrical safety.', 'Discuss and list safe handling practices for computer use. Demonstrate correct sitting posture and monitor distance.', 'Safe handling practices for computer use are correctly listed and demonstrated.'),
(75, 19, 10, 'design', 10, 'Role play: some students demonstrate incorrect handling practices while others identify and correct them.', 'In pairs, role play incorrect handling practices and identify the correct safe practices.', 'Incorrect handling practices are identified and correct safe practices demonstrated.'),
(76, 19, 3, 'realisation', 5, 'Each student states one safe handling practice and explains the risk it prevents.', 'State one safe handling practice and explain the risk it prevents.', 'A safe handling practice and the risk it prevents are correctly stated.'),
(77, 20, 3, 'introduction', 5, 'Ask: Do cars need regular servicing? Do computers also need regular maintenance? What is the difference between maintenance and repair?', 'Respond to questions and discuss the concept of maintenance and how it applies to computers.', 'The concept of computer maintenance and its importance are described.'),
(78, 20, 2, 'development', 20, 'Guide group discussion on the concept of computer system maintenance: definition, importance, and types (preventive, corrective, routine). Use a chart to compare the three types.', 'Discuss, complete a comparison chart of the three types of maintenance, and explain the importance of each.', 'The concept of computer system maintenance, its types, and importance are correctly described.'),
(79, 20, 2, 'design', 10, 'Present maintenance scenario cards. Ask groups to classify each scenario as preventive, corrective, or routine maintenance.', 'Classify given maintenance scenarios as preventive, corrective, or routine maintenance.', 'Maintenance scenarios are correctly classified into the appropriate type of maintenance.'),
(80, 20, 3, 'realisation', 5, 'Each student defines computer system maintenance and names the three types.', 'Define computer system maintenance and name its three types.', 'Computer system maintenance is correctly defined and its three types named.'),
(81, 21, 1, 'introduction', 5, 'Ask: What tasks do you do regularly to prevent your phone from having problems? How can the same idea apply to a computer?', 'Suggest regular tasks done to prevent phone problems and relate these to computer preventive maintenance.', 'The concept of preventive maintenance is related to familiar experiences.'),
(82, 21, 9, 'development', 20, 'Demonstrate preventive maintenance tasks: disk cleanup, defragmentation, checking for updates, scanning for viruses, cleaning dust from vents and keyboard, inspecting cables.', 'Observe demonstrations and note preventive maintenance tasks for both hardware and software.', 'Preventive maintenance tasks for hardware and software are correctly identified.'),
(83, 21, 9, 'design', 10, 'Guide students to perform a preventive maintenance checklist on lab computers (disk cleanup, virus scan, cable inspection).', 'Perform preventive maintenance tasks on a lab computer following the provided checklist.', 'Preventive maintenance tasks are correctly performed on a computer system.'),
(84, 21, 3, 'realisation', 5, 'Each student names two preventive maintenance tasks and explains what problem each prevents.', 'Name two preventive maintenance tasks and explain what problem each prevents.', 'Two preventive maintenance tasks and the problems they prevent are correctly stated.'),
(85, 22, 7, 'introduction', 5, 'Present a scenario: a school computer crashes and loses all work. Ask: What went wrong? What should be done to fix it?', 'Analyse the scenario and suggest steps to fix the crashed computer.', 'The need for corrective maintenance is identified from a given scenario.'),
(86, 22, 1, 'development', 20, 'Demonstrate corrective maintenance procedures: identifying a fault, diagnosing the cause, replacing faulty hardware, reinstalling corrupted software, restoring backed up data.', 'Observe the demonstration and note the steps of corrective maintenance for both hardware and software faults.', 'Steps of corrective maintenance for hardware and software faults are correctly identified.'),
(87, 22, 9, 'design', 10, 'Present a computer with a simulated software fault. Guide students in groups to diagnose and perform corrective maintenance.', 'Diagnose the simulated fault and perform corrective maintenance to restore the computer to working order.', 'A simulated fault is correctly diagnosed and appropriate corrective maintenance performed.'),
(88, 22, 3, 'realisation', 5, 'Each student describes the steps of corrective maintenance for a given fault scenario.', 'Describe the corrective maintenance steps for an assigned fault scenario.', 'Corrective maintenance steps for a given fault are correctly described.'),
(89, 23, 5, 'introduction', 5, 'Ask: What regular tasks should be performed on a computer every day, every week, and every month? Why is a schedule important?', 'Suggest routine tasks to be performed daily, weekly, and monthly on a computer.', 'Routine maintenance tasks at different intervals are suggested.'),
(90, 23, 2, 'development', 20, 'Guide group discussion on routine maintenance: daily tasks (shut down properly, clean keyboard), weekly tasks (virus scan, backup), monthly tasks (disk cleanup, check updates, hardware inspection).', 'Discuss and compile a routine maintenance schedule with daily, weekly, and monthly tasks.', 'A routine maintenance schedule with appropriate daily, weekly, and monthly tasks is compiled.'),
(91, 23, 9, 'design', 10, 'Guide students to create a one-month maintenance schedule for their lab computers and perform one routine task.', 'Create a one-month maintenance schedule and perform one assigned routine maintenance task.', 'A routine maintenance schedule is created and one task correctly performed.'),
(92, 23, 3, 'realisation', 5, 'Each student states one daily, one weekly, and one monthly routine maintenance task.', 'State one daily, one weekly, and one monthly routine computer maintenance task.', 'Routine maintenance tasks at three different intervals are correctly stated.'),
(93, 24, 3, 'introduction', 5, 'Ask: Has your computer ever stopped working or behaved unexpectedly? What did you do? Introduce the concept of troubleshooting.', 'Share experiences of computer problems and describe what was done to resolve them.', 'The concept of troubleshooting is related to personal experiences.'),
(94, 24, 2, 'development', 20, 'Guide group discussion on the concept of troubleshooting: definition, importance, general troubleshooting steps (identify, research, test, solve, document). Discuss types of computer problems.', 'Discuss the concept and steps of troubleshooting and identify types of computer problems.', 'The concept of troubleshooting, its steps, and types of computer problems are correctly described.'),
(95, 24, 6, 'design', 10, 'Present problem scenario cards. Ask groups to apply the troubleshooting steps to identify the likely cause and suggest a solution.', 'Apply troubleshooting steps to assigned problem scenarios and suggest solutions.', 'Troubleshooting steps are correctly applied to given problem scenarios.'),
(96, 24, 3, 'realisation', 5, 'Each student defines troubleshooting and lists the general troubleshooting steps in order.', 'Define troubleshooting and list the general troubleshooting steps in correct order.', 'Troubleshooting is correctly defined and its steps listed in order.'),
(97, 25, 1, 'introduction', 5, 'Ask: What hardware problems have you seen or heard about? (Computer won\'t start, no display, keyboard not working). How would you begin to solve these?', 'Share hardware problems encountered and suggest how to begin solving them.', 'Common hardware problems are identified.'),
(98, 25, 7, 'development', 20, 'Use case studies of common hardware problems (no power, no display, keyboard failure, overheating). Demonstrate or describe how to diagnose and resolve each problem.', 'Study hardware problem case studies and identify the diagnosis and solution for each problem.', 'Common hardware problems are correctly diagnosed and appropriate solutions identified.'),
(99, 25, 9, 'design', 10, 'Present a computer with a simulated hardware problem. Guide groups to diagnose and resolve the problem using the troubleshooting steps.', 'Diagnose the simulated hardware problem and apply the appropriate troubleshooting solution.', 'A hardware problem is correctly diagnosed and resolved using the troubleshooting procedure.'),
(100, 25, 3, 'realisation', 5, 'Each student describes how to troubleshoot one assigned hardware problem.', 'Describe the troubleshooting steps for an assigned hardware problem.', 'Hardware troubleshooting steps for a given problem are correctly described.'),
(101, 26, 5, 'introduction', 5, 'Ask: What software problems have you experienced? (Program crashes, slow computer, virus, blue screen). How did you or others try to fix them?', 'Share software problems experienced and describe how they were handled.', 'Common software problems are identified from shared experiences.'),
(102, 26, 1, 'development', 20, 'Demonstrate solutions to common software problems: restarting an unresponsive program, running System Restore, scanning for malware, updating drivers, reinstalling software.', 'Observe demonstrations and note the troubleshooting steps for each software problem.', 'Common software problems are correctly identified and appropriate troubleshooting steps described.'),
(103, 26, 9, 'design', 10, 'Guide students to diagnose and resolve a simulated software problem (e.g., program not responding) on the lab computers.', 'Diagnose and apply the correct troubleshooting steps to resolve a simulated software problem.', 'A software problem is correctly diagnosed and resolved.'),
(104, 26, 3, 'realisation', 5, 'Each student describes the steps to troubleshoot one assigned software problem.', 'Describe the troubleshooting steps for an assigned software problem.', 'Software troubleshooting steps for a given problem are correctly described.'),
(105, 27, 3, 'introduction', 5, 'Ask: Have you ever used a very slow computer? What causes a computer to run slowly? What can be done to make it faster?', 'Suggest causes of slow computer performance and ways to improve it.', 'Causes of poor computer performance are suggested.'),
(106, 27, 2, 'development', 20, 'Guide group discussion on performance problems and solutions: too many startup programs, low RAM, fragmented disk, overheating, malware. Demonstrate Task Manager use to identify resource-heavy programs.', 'Discuss causes of performance problems and use Task Manager to identify programs consuming excessive resources.', 'Causes of performance problems are correctly identified and appropriate solutions described.'),
(107, 27, 9, 'design', 10, 'Guide students to check and optimise performance on a lab computer (disable startup programs, run disk cleanup, check Task Manager).', 'Perform performance optimisation tasks on a lab computer and observe the effect.', 'Performance optimisation tasks are correctly performed on a computer.'),
(108, 27, 3, 'realisation', 5, 'Each student names one cause of poor computer performance and describes how to resolve it.', 'Name one cause of poor computer performance and describe its solution.', 'A performance problem cause and its solution are correctly described.'),
(109, 28, 3, 'introduction', 5, 'Ask: What happens to a computer during a power surge? Have you seen a computer damaged by electricity? What electrical problems can affect computers?', 'Respond to questions and share experiences of electrical problems affecting computers.', 'Electrical problems that can affect computers are identified.'),
(110, 28, 2, 'development', 20, 'Guide group discussion on electrical troubleshooting: power surges, loose connections, UPS use, earthing/grounding, identifying burnt components. Emphasise safety: always unplug before working on internal components.', 'Discuss electrical problems and their solutions. Note safety rules for working with electrical components.', 'Electrical problems are correctly identified with appropriate solutions and safety measures stated.'),
(111, 28, 7, 'design', 10, 'Present case studies of electrical problems (power surge damage, computer not powering on due to loose cable). Ask groups to diagnose and suggest safe solutions.', 'Diagnose electrical problems in given case studies and suggest safe troubleshooting solutions.', 'Electrical problems are correctly diagnosed and safe solutions suggested.'),
(112, 28, 3, 'realisation', 5, 'Each student states one electrical problem that can affect a computer and describes a safe solution.', 'State one electrical problem and describe a safe solution.', 'An electrical problem and its safe solution are correctly stated.'),
(113, 29, 3, 'introduction', 5, 'Ask: What is a problem? Can you give an example of a problem you solved today? How did you decide what to do?', 'Give examples of problems solved in daily life and describe how they decided on a solution.', 'The concept of a problem and problem solving is related to daily life experiences.'),
(114, 29, 2, 'development', 20, 'Guide group discussion on the concept of problem solving: definition, types of problems (well-defined, ill-defined), importance of problem solving in computing.', 'Discuss and describe the concept of problem solving, types of problems, and its importance in computing.', 'The concept of problem solving, types of problems, and its importance in computing are correctly described.'),
(115, 29, 7, 'design', 10, 'Present two problems (one well-defined, one ill-defined). Ask groups to classify each and explain the classification.', 'Classify given problems as well-defined or ill-defined and justify the classification.', 'Problems are correctly classified as well-defined or ill-defined with justification.'),
(116, 29, 3, 'realisation', 5, 'Each student defines problem solving and gives one example of a well-defined problem in computing.', 'Define problem solving and give one example of a well-defined computing problem.', 'Problem solving is correctly defined and a well-defined computing problem example given.'),
(117, 30, 3, 'introduction', 5, 'Ask: If I ask you to find the sum of numbers 1 to 100, what would you do first? Walk through the thought process step by step.', 'Describe the steps they would take to solve the given problem.', 'A logical sequence of steps for solving a problem is described.'),
(118, 30, 2, 'development', 20, 'Guide group discussion on the steps of problem solving: (1) Understand the problem, (2) Plan the solution, (3) Implement the solution, (4) Test and evaluate. Use a worked example for each step.', 'Discuss each step of problem solving and apply them to a worked example.', 'The steps of problem solving are correctly identified and applied to a given example.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(119, 30, 2, 'design', 10, 'Give groups a simple problem. Ask them to apply the four steps of problem solving and document each step.', 'Apply the four steps of problem solving to an assigned problem and document each step.', 'The four steps of problem solving are correctly applied and documented for a given problem.'),
(120, 30, 3, 'realisation', 5, 'Each student lists the steps of problem solving in the correct order.', 'List the steps of problem solving in the correct order.', 'Steps of problem solving are listed in the correct order.'),
(121, 31, 3, 'introduction', 5, 'Ask: If I want to make tea, what steps would I follow? Write their answers on the board. Explain that this is an algorithm.', 'List the steps for making tea and understand that a step-by-step solution is called an algorithm.', 'The concept of an algorithm is related to a familiar daily activity.'),
(122, 31, 2, 'development', 20, 'Guide group discussion on algorithms: definition, properties (input, output, definiteness, finiteness, effectiveness), and examples from daily life and computing.', 'Discuss the definition and properties of algorithms and identify examples from daily life and computing.', 'The concept of an algorithm, its properties, and examples are correctly described.'),
(123, 31, 2, 'design', 10, 'Ask groups to write an algorithm for a simple daily task (e.g., logging into a computer, making a phone call) following the properties of a good algorithm.', 'Write an algorithm for an assigned daily task following the correct properties of a good algorithm.', 'An algorithm for a daily task is correctly written following the properties of a good algorithm.'),
(124, 31, 3, 'realisation', 5, 'Each student defines an algorithm and lists three properties of a good algorithm.', 'Define an algorithm and list three properties of a good algorithm.', 'An algorithm is correctly defined and three properties listed.'),
(125, 32, 1, 'introduction', 5, 'Show a written algorithm for adding two numbers. Ask: What do you notice about its structure? How is it different from a paragraph?', 'Observe the algorithm and describe its structure compared to a paragraph.', 'The structured nature of an algorithm compared to ordinary text is described.'),
(126, 32, 1, 'development', 20, 'Demonstrate construction of algorithms for simple problems: finding the largest of two numbers, calculating area of a rectangle. Show each step clearly with numbered instructions and decision points.', 'Observe demonstrations and copy the constructed algorithms. Ask questions on unclear steps.', 'Algorithms for simple problems are correctly constructed using numbered steps and decision points.'),
(127, 32, 9, 'design', 10, 'Give groups a simple problem. Ask them to construct a step-by-step algorithm with a clear start, numbered steps, decisions if needed, and a clear end.', 'Construct an algorithm for an assigned simple problem with clear start, numbered steps, and end.', 'An algorithm for a given problem is correctly constructed with all required components.'),
(128, 32, 3, 'realisation', 5, 'Each student constructs a simple algorithm for an assigned problem.', 'Construct an algorithm for the assigned simple problem.', 'An algorithm for a given problem is correctly constructed.'),
(129, 33, 1, 'introduction', 5, 'Show a simple flowchart on the board. Ask: What do you see? What do the different shapes mean? Have you seen something like this before?', 'Observe the flowchart and identify the different shapes and what they might represent.', 'Flowchart shapes are observed and their purpose guessed.'),
(130, 33, 1, 'development', 20, 'Demonstrate flowchart symbols: terminal (oval), process (rectangle), decision (diamond), input/output (parallelogram), flow arrows. Draw flowcharts for two simple algorithms on the board.', 'Copy flowchart symbols and their meanings. Draw a simple flowchart following the demonstrated steps.', 'Flowchart symbols are correctly identified and a simple flowchart is drawn.'),
(131, 33, 9, 'design', 10, 'Guide students to draw a flowchart for an assigned simple algorithm (e.g., check if a number is odd or even).', 'Draw a correctly labelled flowchart for the assigned algorithm using appropriate symbols.', 'A flowchart using correct symbols is drawn for a given algorithm.'),
(132, 33, 3, 'realisation', 5, 'Each student draws the correct flowchart symbol for an assigned process or action.', 'Draw the correct flowchart symbol for the assigned process or action.', 'Flowchart symbols are correctly drawn for given processes.'),
(133, 34, 3, 'introduction', 5, 'Ask: Is a flowchart easy to write when an algorithm has many steps? Introduce pseudocode as a simpler text-based way to represent algorithms.', 'Respond to questions and discuss the need for a simpler way to represent complex algorithms.', 'The need for pseudocode as an alternative to flowcharts is understood.'),
(134, 34, 1, 'development', 20, 'Demonstrate pseudocode for simple algorithms using keywords: START, END, INPUT, OUTPUT, IF...THEN...ELSE, WHILE...DO. Compare pseudocode with the equivalent flowchart.', 'Observe demonstrations and write pseudocode for simple algorithms following the demonstrated keywords and structure.', 'Pseudocode using correct keywords and structure is written for simple algorithms.'),
(135, 34, 9, 'design', 10, 'Guide students to write pseudocode for an assigned algorithm (e.g., find the largest of three numbers).', 'Write pseudocode for the assigned algorithm using correct keywords and structure.', 'Pseudocode for a given algorithm is correctly written.'),
(136, 34, 3, 'realisation', 5, 'Each student writes pseudocode for a simple assigned problem.', 'Write pseudocode for the assigned simple problem.', 'Pseudocode for a given problem is correctly written.'),
(137, 35, 3, 'introduction', 5, 'Ask: If I want a program to print \"Hello\" 10 times, do I draw the same step 10 times in a flowchart? Introduce iteration (loops) as a solution.', 'Respond to the question and discuss how repetition can be handled in flowcharts without repeating steps.', 'The need for iteration control structures in flowcharts is understood.'),
(138, 35, 1, 'development', 20, 'Demonstrate iteration control structures in flowcharts: count-controlled loop (FOR loop equivalent) and condition-controlled loop (WHILE loop equivalent). Draw flowcharts for each type.', 'Observe demonstrations and copy flowcharts for count-controlled and condition-controlled iteration.', 'Iteration control structures in flowcharts are correctly identified and drawn.'),
(139, 35, 9, 'design', 10, 'Guide students to draw a flowchart that uses an iteration structure to solve an assigned repetitive problem (e.g., print numbers 1 to 5).', 'Draw a flowchart using an iteration control structure for the assigned repetitive problem.', 'A flowchart with a correct iteration control structure is drawn for a given problem.'),
(140, 35, 3, 'realisation', 5, 'Each student draws an iteration control structure in a flowchart for an assigned simple repetitive task.', 'Draw a flowchart iteration control structure for the assigned repetitive task.', 'An iteration control structure in a flowchart is correctly drawn for a given task.'),
(141, 36, 3, 'introduction', 5, 'Show different parts of a computer. Ask: What is a computer? What parts can you see?', 'Observe computer parts and respond to introductory questions about what a computer is.', 'Basic knowledge of a computer and its parts is described.'),
(142, 36, 1, 'development', 20, 'Demonstrate computer hardware and software to students. Show students how to start and shut down a computer. Explain the functions of visible components.', 'Observe the demonstration, identify hardware and software components, and practise starting and shutting down the computer.', 'Computer hardware and software are correctly identified and their functions described.'),
(143, 36, 4, 'design', 10, 'Guide students to identify and name each part of the computer in the lab and explain its function.', 'Identify and name computer parts in the lab and explain the function of each part.', 'Computer parts are correctly identified and their functions explained.'),
(144, 36, 3, 'realisation', 5, 'Each student names one computer component and explains what it does.', 'Name one computer component and explain its function.', 'A computer component is correctly named and its function explained.'),
(145, 37, 5, 'introduction', 5, 'Ask students to brainstorm peripheral devices they know. List responses on the board.', 'Brainstorm and name peripheral devices they have seen or used.', 'Common peripheral devices are mentioned.'),
(146, 37, 1, 'development', 20, 'Demonstrate how to connect peripherals (keyboard, mouse, printer, projector, USB, HDMI, VGA) to a microcomputer. Explain the purpose of each connection.', 'Observe the demonstration and note the steps for connecting different peripherals to the computer.', 'Steps for connecting peripherals to a microcomputer are correctly identified.'),
(147, 37, 4, 'design', 10, 'Guide students to practise connecting and disconnecting peripherals to the lab computers.', 'Practise connecting and disconnecting assigned peripheral devices to the lab computer.', 'Peripheral devices are correctly connected and disconnected from a microcomputer.'),
(148, 37, 3, 'realisation', 5, 'Each student picks one peripheral device and explains how it is connected and what it is used for.', 'Pick a peripheral device, explain how it is connected to the computer and what it is used for.', 'A peripheral device is correctly connected and its purpose explained.'),
(149, 38, 6, 'introduction', 5, 'Guide students to think individually about what a network is, then pair and share with the class.', 'Think individually about networks, pair with a classmate, and share ideas with the class.', 'The concept of a network and internet connection is related to prior knowledge.'),
(150, 38, 2, 'development', 20, 'Guide students in groups to discuss the concept of the internet and its types of connections (wired and wireless). Demonstrate connecting a computer to the internet.', 'Discuss the concept of the internet in groups and observe how to connect a computer using wire or wireless.', 'The concept of the internet and the connection procedure are correctly described.'),
(151, 38, 4, 'design', 10, 'Guide students to connect computers to the internet and search for an assigned topic.', 'Connect the lab computer to the internet and search for an assigned topic.', 'A computer is successfully connected to the internet and used to search for information.'),
(152, 38, 3, 'realisation', 5, 'Each student describes the steps for connecting a computer to the internet.', 'Describe the steps followed to connect a computer to the internet.', 'Steps for connecting a computer to the internet are correctly described.'),
(153, 39, 2, 'introduction', 5, 'Ask: What is word processing? Where have you seen or used a word processor before?', 'Respond to questions and share experiences with word processors.', 'Prior knowledge of word processing is shared.'),
(154, 39, 2, 'development', 20, 'Guide students in groups to discuss the concept of word processing: definition, importance, examples of word processors, and common uses.', 'Discuss the concept, importance, and examples of word processing in groups.', 'The concept of word processing, its importance, and examples are correctly described.'),
(155, 39, 4, 'design', 10, 'Guide students to open a word processor on the lab computers and explore its interface: menus, toolbars, and the document area.', 'Open a word processor, identify and name the parts of its interface.', 'Parts of the word processor interface are correctly identified and named.'),
(156, 39, 3, 'realisation', 5, 'Each student defines word processing and names two examples of word processors.', 'Define word processing and name two examples of word processors.', 'Word processing is correctly defined and two examples named.'),
(157, 40, 1, 'introduction', 5, 'Open Microsoft Word on the projector and ask: What do you see? What can you do with this program?', 'Observe the MS Word interface and suggest what tasks can be done with it.', 'The MS Word interface is observed and basic uses suggested.'),
(158, 40, 1, 'development', 20, 'Demonstrate how to create, save, and format a document in MS Word: typing text, applying text attributes (bold, italic, underline), inserting page numbers, headers, footers, bullets, tables, and pictures.', 'Observe the demonstration and take notes on how to create, format, and save a document in MS Word.', 'Steps for creating and formatting a document in MS Word are correctly identified.'),
(159, 40, 9, 'design', 10, 'Guide students to create a word document, apply formatting (text attributes, bullets, page numbers, header, footer, table, picture) and save it.', 'Create a word document, apply assigned formatting elements, insert a table and picture, and save the document.', 'A formatted word document with text attributes, page numbers, table, and picture is correctly created and saved.'),
(160, 40, 3, 'realisation', 5, 'Each student describes how to insert and format one element in MS Word (e.g., table, header, or page number).', 'Describe the steps for inserting and formatting an assigned element in MS Word.', 'Steps for inserting and formatting an element in MS Word are correctly described.'),
(161, 41, 1, 'introduction', 5, 'Open MS Excel and ask: What do you see? What is a spreadsheet used for? How is it different from Word?', 'Observe the MS Excel interface and suggest how it differs from a word processor.', 'The spreadsheet interface is observed and its purpose compared to a word processor.'),
(162, 41, 1, 'development', 20, 'Demonstrate step by step how to create a spreadsheet, enter data, format cells, sort data, and filter data using MS Excel. Show how to add and format tables.', 'Observe the demonstration and practise data entry, sorting, and filtering in MS Excel.', 'A spreadsheet is correctly created with data entry, formatting, sorting, and filtering applied.'),
(163, 41, 4, 'design', 10, 'Provide a data set and guide students to enter it into Excel, format the cells, sort the data, and apply a filter.', 'Insert the given data set into Excel, format cells, sort the data, and apply a filter.', 'A spreadsheet is correctly created, formatted, sorted, and filtered with the given data.'),
(164, 41, 3, 'realisation', 5, 'Each student explains how to sort or filter data in a spreadsheet.', 'Explain the steps for sorting or filtering data in a spreadsheet.', 'Steps for sorting or filtering spreadsheet data are correctly explained.'),
(165, 42, 1, 'introduction', 5, 'Ask: How would you calculate the total marks for a class of 40 students using Excel? What formulas do you know?', 'Suggest ways of performing calculations in a spreadsheet and name any formulas they know.', 'The need for formulas in spreadsheets is discussed.'),
(166, 42, 1, 'development', 20, 'Demonstrate the correct use of arithmetic operators and functions: SUM, AVERAGE, and percentage formulas. Show how to write cell references in formulas.', 'Observe demonstrations and practise writing basic formulas using arithmetic operators and SUM, AVERAGE functions.', 'Basic calculations using arithmetic operators and functions are correctly performed in a spreadsheet.'),
(167, 42, 9, 'design', 10, 'Divide students into small groups. Assign each group a data set requiring SUM, AVERAGE, and percentage calculations.', 'Use the assigned data set to perform SUM, AVERAGE, and percentage calculations in Excel.', 'Basic calculations and formulas are correctly applied to a given data set.'),
(168, 42, 3, 'realisation', 5, 'Each student writes a formula to calculate the sum and average of a given range of values.', 'Write a SUM and AVERAGE formula for an assigned range of values.', 'SUM and AVERAGE formulas for a given range are correctly written.'),
(169, 43, 1, 'introduction', 5, 'Ask: What happens if someone enters text where a number is expected in a spreadsheet? How can we prevent errors in data entry?', 'Suggest ways to prevent incorrect data entry in a spreadsheet.', 'The need for data validation in spreadsheets is discussed.'),
(170, 43, 1, 'development', 20, 'Demonstrate data validation features (restricting data type and range) and conditional formatting (highlighting cells based on rules) in MS Excel.', 'Observe demonstrations and take notes on how to apply data validation and conditional formatting.', 'Data validation rules and conditional formatting are correctly applied in a spreadsheet.'),
(171, 43, 9, 'design', 10, 'Provide a data set and guide students to apply data validation and conditional formatting to it.', 'Apply data validation and conditional formatting to the provided data set in Excel.', 'Data validation and conditional formatting are correctly applied to a given data set.'),
(172, 43, 2, 'realisation', 5, 'Each student explains the purpose of data validation and describes one conditional formatting rule.', 'Explain the purpose of data validation and describe one conditional formatting rule.', 'The purpose of data validation and a conditional formatting rule are correctly explained.'),
(173, 44, 1, 'introduction', 5, 'Ask: Can Excel work with data from other programs? Have you seen a CSV file before? What is it?', 'Respond to questions about sharing data between programs and what a CSV file is.', 'The concept of data import and export between programs is introduced.'),
(174, 44, 1, 'development', 20, 'Demonstrate importing data from a CSV file into Excel and exporting data to CSV and other formats using a projector.', 'Observe the step-by-step process of importing and exporting data in Excel.', 'The process of importing and exporting data in a spreadsheet is correctly described.'),
(175, 44, 9, 'design', 10, 'Provide sample CSV files and guide students to import them into Excel and export a worksheet in CSV format.', 'Import an assigned CSV file into Excel and export a worksheet in CSV format.', 'Data is correctly imported from a CSV file and exported from a spreadsheet.'),
(176, 44, 3, 'realisation', 5, 'Each student describes the steps for importing data from a CSV file into a spreadsheet.', 'Describe the steps for importing a CSV file into a spreadsheet.', 'Steps for importing data into a spreadsheet are correctly described.'),
(177, 45, 1, 'introduction', 5, 'Ask: Before printing a spreadsheet, what settings should you check? Have you ever printed a document that did not fit on the page?', 'Suggest settings to check before printing a spreadsheet.', 'Common issues with printing spreadsheets are identified.'),
(178, 45, 1, 'development', 20, 'Demonstrate page layout setup in Excel: paper size, orientation, margins, print area, and print preview. Show the printing process.', 'Observe the demonstration and note the steps for setting up a page and printing in Excel.', 'Page setup options and the printing process in a spreadsheet are correctly described.'),
(179, 45, 9, 'design', 10, 'Provide spreadsheet samples with various formatting requirements. Guide students to adjust page setup and print or preview.', 'Adjust page setup settings for the provided spreadsheet and perform a print preview.', 'Page setup is correctly adjusted and a print preview or printout produced.'),
(180, 45, 3, 'realisation', 5, 'Each student names two page setup settings that must be checked before printing.', 'Name two page setup settings that must be checked before printing a spreadsheet.', 'Two page setup settings and their purpose are correctly stated.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(181, 46, 2, 'introduction', 5, 'Ask: What is a database? Can you give examples of places where large amounts of data are stored and managed? Introduce MS Access.', 'Respond to questions and suggest real-life examples of data storage and management.', 'The concept of a database and its real-life uses are discussed.'),
(182, 46, 2, 'development', 20, 'Guide students in groups to discuss the concept of database applications, common vendors (MS Access, MySQL), and their advantages. Demonstrate opening and navigating MS Access.', 'Discuss database concepts in groups and observe the MS Access interface.', 'The concept of a database application, its vendors, and features are correctly described.'),
(183, 46, 4, 'design', 10, 'Guide students to use the internet to watch a tutorial on creating a database in MS Access and identify its features.', 'Watch an online MS Access tutorial and identify the key features of the database software.', 'Key features of a database application are correctly identified from a tutorial.'),
(184, 46, 3, 'realisation', 5, 'Each student defines a database and names two examples of database applications.', 'Define a database and name two examples of database applications.', 'A database is correctly defined and two examples named.'),
(185, 47, 1, 'introduction', 5, 'Ask: What is a table in a database? How is it different from a spreadsheet table?', 'Respond to questions and compare a database table to a spreadsheet table.', 'The concept of a database table is related to a familiar structure.'),
(186, 47, 1, 'development', 20, 'Use a real-world scenario (e.g., school exam results) to demonstrate creating a table in MS Access, defining fields, data types, and entering records.', 'Observe the demonstration and note the steps for creating a table and entering data in MS Access.', 'A database table with appropriate fields and data types is correctly created.'),
(187, 47, 9, 'design', 10, 'Assign students a scenario and guide them to create a table and enter a set of data records in MS Access.', 'Create a table in MS Access for the assigned scenario and enter the provided data records.', 'A database table is correctly created with appropriate fields and data entered.'),
(188, 47, 3, 'realisation', 5, 'Each student describes the steps for creating a table and entering data in a database application.', 'Describe the steps for creating a table and entering data in a database application.', 'Steps for creating a database table and entering data are correctly described.'),
(189, 48, 1, 'introduction', 5, 'Ask: If a database has 500 records, how would you find only the records you need? Introduce queries.', 'Respond to questions and suggest how to find specific records in a large database.', 'The purpose of queries in a database is discussed.'),
(190, 48, 1, 'development', 20, 'Demonstrate how to create a simple select query in MS Access to retrieve specific records based on criteria.', 'Observe the demonstration and note the steps for creating a query in MS Access.', 'A query is correctly created to retrieve specific records from a database.'),
(191, 48, 9, 'design', 10, 'Assign students a database with data and guide them to create a query to retrieve specific records.', 'Create a query in MS Access to retrieve assigned records from the given database.', 'A query retrieving specified records is correctly created.'),
(192, 48, 3, 'realisation', 5, 'Each student describes the purpose of a query and the steps for creating one in a database.', 'Describe the purpose of a database query and the steps for creating one.', 'The purpose of a query and the steps for creating one are correctly described.'),
(193, 49, 1, 'introduction', 5, 'Ask: How do users enter data into a database system without seeing the underlying tables? Introduce database forms.', 'Respond to questions and suggest how a form makes data entry easier for users.', 'The purpose of forms in a database is discussed.'),
(194, 49, 1, 'development', 20, 'Use a guided video tutorial to demonstrate creating a form in MS Access for a given table. Show how forms simplify data entry.', 'Watch the video demonstration and observe how a form is created in MS Access.', 'A form for a database table is correctly created in MS Access.'),
(195, 49, 9, 'design', 10, 'Assign students a database table and guide them to create a form for data entry using MS Access.', 'Create a data entry form for the assigned database table in MS Access.', 'A data entry form is correctly created for an assigned database table.'),
(196, 49, 3, 'realisation', 5, 'Each student explains why forms are used in database systems.', 'Explain the purpose of forms in a database system.', 'The purpose of database forms is correctly explained.'),
(197, 50, 1, 'introduction', 5, 'Ask: How can we present database information in a printed, organised format? Introduce database reports.', 'Respond to questions and suggest how database reports differ from raw table data.', 'The purpose of reports in a database is discussed.'),
(198, 50, 1, 'development', 20, 'Use a guided video to demonstrate creating a report in MS Access from a given table or query. Show how to format and organise the report.', 'Watch the video and observe the steps for creating a report in MS Access.', 'A database report is correctly created and formatted in MS Access.'),
(199, 50, 9, 'design', 10, 'Assign students a database and guide them to create a formatted report from a given table or query.', 'Create a formatted report from the assigned database table or query in MS Access.', 'A formatted database report is correctly created.'),
(200, 50, 3, 'realisation', 5, 'Each student describes the steps for creating a report in a database application.', 'Describe the steps for creating a report in a database application.', 'Steps for creating a database report are correctly described.'),
(201, 51, 1, 'introduction', 5, 'Show a sample PowerPoint presentation. Ask: What is this? Where have you seen presentations used?', 'Observe the sample presentation and identify where presentations are used.', 'The purpose and use of presentations in real life are described.'),
(202, 51, 1, 'development', 20, 'Use a projector to demonstrate navigating PowerPoint: creating slides, adding text content, and applying formatting options such as themes, fonts, and layouts.', 'Observe the demonstration and take notes on how to create and format slides in PowerPoint.', 'Slides are correctly created with appropriate content and formatting in PowerPoint.'),
(203, 51, 9, 'design', 10, 'Organise hands-on workshops where students create a presentation on an assigned topic applying themes, fonts, and layouts.', 'Create a presentation on an assigned topic with appropriate theme, fonts, and organised slide layout.', 'A presentation with correct formatting and organised content is created.'),
(204, 51, 3, 'realisation', 5, 'Each student describes how to create a new slide and apply a theme in PowerPoint.', 'Describe the steps for creating a new slide and applying a theme in PowerPoint.', 'Steps for creating a slide and applying a theme are correctly described.'),
(205, 52, 1, 'introduction', 5, 'Ask: How can images and diagrams improve a presentation? Show a slide with and without visuals.', 'Compare slides with and without visuals and explain how visuals improve a presentation.', 'The importance of visual elements in presentations is discussed.'),
(206, 52, 1, 'development', 20, 'Demonstrate inserting and formatting images, graphics, and SmartArt in PowerPoint. Show how to resize, position, and format each visual element.', 'Observe the demonstration and note the steps for inserting and formatting images, graphics, and SmartArt.', 'Images, graphics, and SmartArt are correctly inserted and formatted in a presentation.'),
(207, 52, 4, 'design', 10, 'Provide opportunities for students to practise inserting and manipulating images and SmartArt in their presentations.', 'Insert and manipulate images, graphics, and SmartArt in an assigned presentation.', 'Visual elements are correctly inserted and formatted in a presentation slide.'),
(208, 52, 3, 'realisation', 5, 'Each student describes the steps for inserting an image and a SmartArt in PowerPoint.', 'Describe the steps for inserting an image and a SmartArt into a PowerPoint slide.', 'Steps for inserting images and SmartArt in PowerPoint are correctly described.'),
(209, 53, 1, 'introduction', 5, 'Ask: When is it better to use a chart rather than a table in a presentation? Show examples.', 'Compare examples of charts and tables and suggest when each is more appropriate.', 'The purpose of charts and tables in presentations is discussed.'),
(210, 53, 1, 'development', 20, 'Demonstrate how to create, insert, and format charts and tables in PowerPoint using real or sample data.', 'Observe the demonstration and note the steps for creating and formatting charts and tables in PowerPoint.', 'Charts and tables are correctly created and formatted in a PowerPoint presentation.'),
(211, 53, 9, 'design', 10, 'Guide students to create charts and tables in their presentations using real or sample data.', 'Create a chart and a table from given data and insert them into a presentation slide.', 'A chart and table from given data are correctly created and inserted into a presentation.'),
(212, 53, 3, 'realisation', 5, 'Each student explains the difference between using a chart and a table in a presentation.', 'Explain the difference between using a chart and a table in a presentation and give one use for each.', 'The difference between charts and tables in presentations is correctly explained.'),
(213, 54, 1, 'introduction', 5, 'Show a presentation with no transitions and one with transitions. Ask: What difference do you notice? What makes slides more engaging?', 'Compare presentations with and without transitions and identify what makes slides more engaging.', 'The purpose of transitions and animations in presentations is discussed.'),
(214, 54, 1, 'development', 20, 'Demonstrate how to create slide transitions, apply a Slide Master for uniform design, and add animations to individual objects in PowerPoint.', 'Observe demonstrations and note how to add transitions, apply a Slide Master, and add animations.', 'Slide transitions, Slide Master layouts, and animations are correctly applied in PowerPoint.'),
(215, 54, 9, 'design', 10, 'Guide students to customise pre-made templates using Slide Master and add transitions and animations to their presentations.', 'Apply a Slide Master, add slide transitions, and animate objects in an assigned presentation.', 'A Slide Master, transitions, and animations are correctly applied in a presentation.'),
(216, 54, 3, 'realisation', 5, 'Each student describes how to apply a transition between slides and one animation to an object.', 'Describe the steps for applying a slide transition and an object animation in PowerPoint.', 'Steps for applying transitions and animations in PowerPoint are correctly described.'),
(217, 55, 1, 'introduction', 5, 'Ask: How is presenting on Zoom or Google Meet different from presenting in a classroom? What challenges can arise?', 'Discuss the differences and challenges of remote presentations compared to in-person presentations.', 'Challenges of presenting remotely are identified.'),
(218, 55, 1, 'development', 20, 'Demonstrate how to create a presentation tailored for remote delivery, emphasising clarity, simplicity, and engaging design. Show screen sharing on remote meeting platforms.', 'Observe the demonstration and note guidelines for creating and sharing presentations in remote meetings.', 'A presentation suitable for remote delivery is correctly created with appropriate design.'),
(219, 55, 9, 'design', 10, 'Guide students through a hands-on activity using remote meeting platforms (Zoom, Google Meet, MS Teams) to share their presentations with screen sharing.', 'Share a presentation using screen sharing on an assigned remote meeting platform.', 'A presentation is correctly shared using screen sharing on a remote meeting platform.'),
(220, 55, 2, 'realisation', 5, 'In groups, students discuss best practices for remote presentations and share one key tip.', 'Discuss best practices for remote presentations in groups and share one key tip with the class.', 'Best practices for remote presentations are correctly identified and explained.'),
(221, 56, 1, 'introduction', 5, 'Show examples of a newsletter, brochure, and flyer. Ask: What is different about these compared to a Word document?', 'Observe examples of publications and identify how they differ from ordinary Word documents.', 'The differences between desktop publishing output and ordinary documents are described.'),
(222, 56, 1, 'development', 20, 'Demonstrate the basic features of MS Publisher: selecting templates, customising layouts, inserting images, and formatting text. Show how to create a simple document.', 'Observe the demonstration and take notes on how to create and format a document in MS Publisher.', 'A document is correctly created and formatted in MS Publisher.'),
(223, 56, 8, 'design', 10, 'Provide step-by-step instructions and guide students to create and format their own document in MS Publisher.', 'Create and format a document in MS Publisher following the provided instructions.', 'A formatted document is correctly created in MS Publisher.'),
(224, 56, 3, 'realisation', 5, 'Each student describes how to create a new document and apply a template in MS Publisher.', 'Describe the steps for creating a document and applying a template in MS Publisher.', 'Steps for creating and formatting a document in MS Publisher are correctly described.'),
(225, 57, 1, 'introduction', 5, 'Ask: How can images and graphic elements improve a publication like a brochure or newsletter?', 'Suggest how images and graphics improve publications.', 'The importance of images and graphics in desktop publishing is discussed.'),
(226, 57, 1, 'development', 20, 'Demonstrate inserting images and graphics into MS Publisher. Show how to use editing tools to resize, crop, and position images.', 'Observe the demonstration and note how to insert, resize, crop, and position images in MS Publisher.', 'Images and graphics are correctly inserted and edited in a desktop publishing document.'),
(227, 57, 9, 'design', 10, 'Facilitate hands-on practice sessions where students insert and format images and graphics in their MS Publisher document.', 'Insert, resize, crop, and position images and graphics in an MS Publisher document.', 'Images and graphics are correctly inserted and formatted in a publication.'),
(228, 57, 3, 'realisation', 5, 'Each student explains the steps for inserting and formatting an image in MS Publisher.', 'Explain the steps for inserting and formatting an image in MS Publisher.', 'Steps for inserting and formatting images in MS Publisher are correctly explained.'),
(229, 58, 1, 'introduction', 5, 'Show two publications: one with poor font choices and one with good typography. Ask: Which looks more professional? Why?', 'Compare the two publications and explain which looks more professional and why.', 'The importance of typography in publications is discussed.'),
(230, 58, 1, 'development', 20, 'Provide live demonstrations of accessing and managing fonts in MS Publisher. Explain font types, sizes, spacing, and hierarchy.', 'Observe demonstrations and note how to manage fonts and apply typography principles in MS Publisher.', 'Typography principles and font management in MS Publisher are correctly applied.'),
(231, 58, 8, 'design', 10, 'Engage students in a hands-on project where they apply typography principles to create or improve a document in MS Publisher.', 'Apply typography principles to create or improve a publication in MS Publisher.', 'Typography principles are correctly applied in a desktop publishing document.'),
(232, 58, 3, 'realisation', 5, 'Each student names two typography principles and explains their effect on a publication.', 'Name two typography principles and explain their effect on a publication.', 'Two typography principles and their effects are correctly described.'),
(233, 59, 1, 'introduction', 5, 'Show examples of a business card, brochure, and newsletter. Ask: What business documents can be created using desktop publishing software?', 'Identify business documents shown and suggest others that can be created using desktop publishing.', 'Types of business products that can be created with desktop publishing are identified.'),
(234, 59, 1, 'development', 20, 'Demonstrate how to create business cards and stationery in MS Publisher. Show the tools used for layout and design.', 'Observe the demonstration and note the steps for creating business products in MS Publisher.', 'Business products are correctly designed using MS Publisher tools.'),
(235, 59, 9, 'design', 10, 'Guide students to create one business product of their choice (brochure, flyer, newsletter, poster, or business card) in MS Publisher.', 'Create an assigned business product (brochure, flyer, newsletter, or business card) in MS Publisher.', 'A business product is correctly designed and formatted in MS Publisher.'),
(236, 59, 3, 'realisation', 5, 'Each student names three types of business products that can be created using desktop publishing software.', 'Name three types of business products that can be created using desktop publishing software.', 'Three business products creatable using desktop publishing are correctly named.'),
(237, 60, 5, 'introduction', 5, 'Ask: How do you find information on the internet? What search engines do you know?', 'Brainstorm search engines they know and how they search for information online.', 'Common internet search engines and search habits are identified.'),
(238, 60, 2, 'development', 20, 'Assign students to groups to discuss different web browsers, search engines, and their functionalities. Guide discussion on internet search techniques and evaluating credible sources.', 'Discuss search engines, search techniques, and how to identify credible and reliable sources of information.', 'Internet search techniques and criteria for credible sources are correctly described.'),
(239, 60, 9, 'design', 10, 'Guide students to use the internet to search for assigned topics and evaluate the credibility of sources found.', 'Search for an assigned topic on the internet and evaluate the credibility of sources found.', 'Internet search is correctly performed and sources are evaluated for credibility.'),
(240, 60, 3, 'realisation', 5, 'Each student describes one internet search technique and explains how to identify a credible source.', 'Describe one internet search technique and explain how to identify a credible online source.', 'An internet search technique and criteria for credible sources are correctly described.'),
(241, 61, 3, 'introduction', 5, 'Ask: What is email? Have you sent or received an email? What are the parts of an email?', 'Respond to questions and share experiences with sending and receiving emails.', 'Basic knowledge of email and its parts is described.'),
(242, 61, 9, 'development', 20, 'Guide students to set up an email account, configure settings (signature, automatic replies), compose and send an email, and use folders and labels to organise the inbox.', 'Set up an email account, configure settings, compose and send an email, and organise the inbox using folders.', 'An email account is correctly set up, configured, and used to compose, send, and organise emails.'),
(243, 61, 9, 'design', 10, 'Guide students to use email tools (filters, rules, priority markers) to manage an inbox and send a formatted professional email with an attachment.', 'Apply email filters and rules to manage the inbox and send a professional email with an attached file.', 'Email tools are correctly used and a professional email with attachment is sent.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(244, 61, 3, 'realisation', 5, 'Each student describes how to compose a professional email and attach a file.', 'Describe the steps for composing and sending a professional email with an attachment.', 'Steps for composing and sending a professional email with an attachment are correctly described.'),
(245, 62, 5, 'introduction', 5, 'Ask: What social media platforms do you know? How are they used for communication and business?', 'Brainstorm social media platforms they know and their uses for communication and business.', 'Common social media platforms and their uses are identified.'),
(246, 62, 7, 'development', 20, 'Use real-world scenarios to illustrate creating and posting content on different social media platforms, emphasising differences in tone and style. Demonstrate reading social media analytics.', 'Analyse real-world scenarios of social media content and observe how analytics are read and interpreted.', 'Social media content creation processes and analytics are correctly described.'),
(247, 62, 9, 'design', 10, 'Guide students to set up various social media accounts and practise using social media management tools to schedule posts and manage accounts.', 'Set up a social media account and use management tools to schedule and manage posts.', 'A social media account is correctly set up and management tools are used to schedule posts.'),
(248, 62, 3, 'realisation', 5, 'Each student names two social media platforms and describes one difference in how content is posted on each.', 'Name two social media platforms and describe one difference in how content is posted on each.', 'Two social media platforms are named and one difference in content posting described.'),
(249, 63, 1, 'introduction', 5, 'Ask: What is a webinar? How is it different from a regular video call? Where are webinars used?', 'Respond to questions and discuss the difference between webinars and regular video calls.', 'The concept and use of webinars and virtual meetings are discussed.'),
(250, 63, 1, 'development', 20, 'Demonstrate various virtual meeting platforms and guide students in setting up meetings or webinars, focusing on essential tools: screen sharing, breakout rooms, and polls.', 'Observe the demonstration and note the steps for setting up a virtual meeting or webinar.', 'A virtual meeting or webinar is correctly set up using an online platform.'),
(251, 63, 9, 'design', 10, 'Guide students to schedule a meeting, create an invitation, and use features like screen sharing and polls on a virtual meeting platform.', 'Schedule a virtual meeting, create an invitation, and use screen sharing and poll features.', 'A virtual meeting with invitations and features is correctly set up.'),
(252, 63, 2, 'realisation', 5, 'In groups, students describe different types of webinars or virtual meetings and their uses.', 'In groups, describe different types of webinars and virtual meetings and their uses.', 'Types of webinars and virtual meetings and their uses are correctly described.'),
(253, 64, 3, 'introduction', 5, 'Ask: Where have you filled in an online form? What types of questions do online forms usually have?', 'Share experiences of filling in online forms and describe the types of questions used.', 'Types of online forms and their uses are identified from experience.'),
(254, 64, 9, 'development', 20, 'Guide students through the process of selecting a platform and creating an online form using different question formats (multiple choice, short answer, rating).', 'Create an online form using an assigned platform, using multiple question formats.', 'An online form with appropriate question formats is correctly created.'),
(255, 64, 7, 'design', 10, 'Discuss real-world examples of online forms in business and education. Guide students to distribute a form and analyse the survey results.', 'Distribute an online form, collect responses, and analyse the survey results.', 'Survey results from an online form are correctly analysed and interpreted.'),
(256, 64, 3, 'realisation', 5, 'Each student names two platforms for creating online forms and describes one use of online surveys.', 'Name two platforms for creating online forms and describe one use of online surveys.', 'Two online form platforms and one use of surveys are correctly named and described.'),
(257, 65, 6, 'introduction', 5, 'Guide students to think individually about cloud storage and its benefits, then pair and share with the class.', 'Think individually about cloud storage, pair with a classmate, and share ideas with the class.', 'The concept of cloud storage and its benefits are discussed.'),
(258, 65, 9, 'development', 20, 'Guide students through creating and setting up cloud storage accounts on different platforms. Demonstrate how to upload, organise, and share files with various permission levels.', 'Create a cloud storage account, upload files, organise them into folders, and share a file with a classmate.', 'A cloud storage account is correctly created and used to upload, organise, and share files.'),
(259, 65, 9, 'design', 10, 'Guide students to practise using cloud services across multiple devices, ensuring files sync properly, and troubleshooting common issues.', 'Access a cloud storage account from two different devices and verify that files sync correctly.', 'Files are correctly accessed and synced across devices using a cloud storage service.'),
(260, 65, 3, 'realisation', 5, 'Each student names one cloud storage platform and describes one advantage of using cloud storage.', 'Name one cloud storage platform and describe one advantage of using cloud storage.', 'A cloud storage platform is correctly named and one advantage described.'),
(261, 66, 7, 'introduction', 5, 'Present a case study of a cyber-attack. Ask: What happened? Who was affected? How could it have been prevented?', 'Analyse the cyber-attack case study and suggest how it could have been prevented.', 'The concept and impact of internet threats are discussed.'),
(262, 66, 2, 'development', 20, 'Lead discussions on various types of internet threats (malware, phishing, hacking, identity theft) and their consequences. Use real-life examples of cyber-attacks.', 'Discuss types of internet threats, their consequences, and share personal experiences of online threats.', 'Types of internet threats and their consequences are correctly identified and described.'),
(263, 66, 7, 'design', 10, 'Present scenarios of different internet threats. Ask groups to identify the type of threat and suggest prevention measures.', 'Identify the type of internet threat in each scenario and suggest appropriate prevention measures.', 'Internet threats in given scenarios are correctly identified and prevention measures suggested.'),
(264, 66, 3, 'realisation', 5, 'Each student names one type of internet threat and describes how to prevent it.', 'Name one type of internet threat and describe one way to prevent it.', 'An internet threat and its prevention measure are correctly described.'),
(265, 67, 3, 'introduction', 5, 'Ask: What is a VPN? Have you heard of a proxy? Why would someone use them?', 'Respond to questions about VPNs and proxies and suggest why they might be used.', 'The concept of VPNs and proxies and their uses are discussed.'),
(266, 67, 3, 'development', 20, 'Explain the concepts of VPNs and proxies, their differences, and typical use cases. Demonstrate configuring VPN software on a device.', 'Observe the explanation and demonstration and note the concepts and differences between VPNs and proxies.', 'The concepts of VPN and proxy and their differences are correctly described.'),
(267, 67, 9, 'design', 10, 'Guide students to install, configure, and use VPN software on lab computers. Show how to select VPN servers and manage encryption settings.', 'Install, configure, and connect to a VPN on the lab computer and verify the connection.', 'VPN software is correctly installed, configured, and used on a computer.'),
(268, 67, 3, 'realisation', 5, 'Each student explains the difference between a VPN and a proxy and states one use of each.', 'Explain the difference between a VPN and a proxy and state one use of each.', 'The difference between a VPN and a proxy and one use of each are correctly explained.'),
(269, 68, 3, 'introduction', 5, 'Ask: What is email marketing? Have you ever received a promotional email from a company? What made it effective or not?', 'Respond to questions and share experiences of receiving marketing emails.', 'The concept of email marketing and its role in digital marketing are discussed.'),
(270, 68, 9, 'development', 20, 'Guide students to design email templates using email marketing platforms, focusing on design, messaging, and call-to-action buttons. Demonstrate setting up automated email campaigns.', 'Design an email marketing template on an assigned platform and identify key elements: design, message, call-to-action.', 'An email marketing template with appropriate elements is correctly designed.'),
(271, 68, 9, 'design', 10, 'Guide students through creating a segmented email list and setting up an automated welcome or promotional campaign.', 'Create a segmented email list and set up an automated email campaign on an assigned platform.', 'A segmented email list and automated campaign are correctly created.'),
(272, 68, 3, 'realisation', 5, 'Each student describes two elements of an effective marketing email.', 'Describe two elements of an effective marketing email.', 'Two elements of an effective marketing email are correctly described.'),
(273, 69, 5, 'introduction', 5, 'Ask: What types of digital content do businesses and influencers create? What makes content engaging?', 'Brainstorm types of digital content and suggest what makes them engaging.', 'Types of digital content used in marketing are identified.'),
(274, 69, 9, 'development', 20, 'Guide students to create various types of digital content (social media posts, blog articles, short video snippets) using relevant tools. Cover copyright laws and ethical considerations.', 'Create assigned types of digital content using provided tools and apply copyright and ethical guidelines.', 'Digital content of different types is correctly created following copyright and ethical guidelines.'),
(275, 69, 9, 'design', 10, 'Lead activities where students craft a content strategy for an assigned platform focusing on audience engagement, tone, and branding.', 'Develop a content strategy for an assigned platform with content plan, tone guide, and branding elements.', 'A content strategy for an assigned platform is correctly developed.'),
(276, 69, 3, 'realisation', 5, 'Each student names two types of digital content and explains one ethical consideration in content creation.', 'Name two types of digital content and explain one ethical consideration in content creation.', 'Two types of digital content and one ethical consideration are correctly described.'),
(277, 70, 3, 'introduction', 5, 'Ask: What is a blog? How is it different from a social media post? Have you ever read or written a blog?', 'Respond to questions and share experiences with reading or writing blogs.', 'The concept of a blog and its difference from social media content is discussed.'),
(278, 70, 9, 'development', 20, 'Introduce blog platforms and demonstrate setting up and customising a blog with different themes and designs. Show how to customise the appearance and structure.', 'Observe the demonstration and note the steps for setting up and customising a blog on an assigned platform.', 'A blog is correctly set up and customised on an assigned platform.'),
(279, 70, 9, 'design', 10, 'Guide students to customise their blog appearance and incorporate multimedia elements (images, videos) into blog posts.', 'Customise the blog appearance and publish a blog post incorporating images or videos.', 'A blog post with multimedia elements is correctly published on a customised blog.'),
(280, 70, 3, 'realisation', 5, 'Each student names two blog platforms and describes one way to customise a blog for a target audience.', 'Name two blog platforms and describe one way to customise a blog for a specific audience.', 'Two blog platforms and one customisation method are correctly described.'),
(281, 71, 3, 'introduction', 5, 'Ask: Where do you see advertisements online? What types of online ads do you know?', 'Identify places where online ads appear and name types of online advertisements.', 'Types of online advertisements and where they appear are identified.'),
(282, 71, 1, 'development', 20, 'Introduce types of online ads (search, display, social media, video). Demonstrate how to craft effective ad copy and visuals. Explain targeting options, budgets, and bidding strategies.', 'Observe the demonstration and note the types of online ads, targeting options, and budgeting strategies.', 'Types of online advertisements and advertising strategies are correctly described.'),
(283, 71, 9, 'design', 10, 'Guide students to analyse campaign data and practise adjusting targeting options and making real-time optimisations to improve campaign performance.', 'Analyse sample campaign data and adjust targeting options to improve performance metrics.', 'Campaign data is correctly analysed and targeting adjustments made to improve performance.'),
(284, 71, 3, 'realisation', 5, 'Each student names two types of online advertisements and explains one targeting strategy.', 'Name two types of online advertisements and explain one targeting strategy.', 'Two types of online ads and one targeting strategy are correctly described.'),
(285, 72, 3, 'introduction', 5, 'Ask: How do businesses know if their online marketing is working? What data do they look at?', 'Suggest how businesses measure the success of online marketing.', 'The importance of market analytics for decision-making is discussed.'),
(286, 72, 9, 'development', 20, 'Guide students to work with tools like Google Analytics or Excel to gather and interpret market data. Demonstrate how to track traffic, conversion rates, and user demographics.', 'Use an analytics tool to gather market data and identify key metrics such as traffic and conversion rates.', 'Key marketing metrics are correctly identified and interpreted using an analytics tool.'),
(287, 72, 1, 'design', 10, 'Demonstrate how to identify market trends and customer behaviour patterns. Guide group exercises on applying insights to improve marketing strategies.', 'Analyse market data, identify trends, and suggest marketing strategy improvements based on insights.', 'Market trends are correctly identified and data-driven marketing improvements suggested.'),
(288, 72, 3, 'realisation', 5, 'Each student names two key marketing metrics and explains what each metric measures.', 'Name two key marketing metrics and explain what each measures.', 'Two marketing metrics and their meanings are correctly described.'),
(289, 73, 3, 'introduction', 5, 'Ask: What is a CRM system? Why would a business need to manage customer relationships using software?', 'Respond to questions about CRM systems and suggest why businesses use them.', 'The concept and purpose of CRM systems are discussed.'),
(290, 73, 9, 'development', 20, 'Guide students to set up a CRM system, configure its features, and manage customer data. Demonstrate how to use CRM tools for tracking leads and customer interactions.', 'Set up a CRM system, configure features, and add sample customer data.', 'A CRM system is correctly set up, configured, and used to manage customer data.'),
(291, 73, 9, 'design', 10, 'Guide students to practise automating common tasks in the CRM (follow-up emails, updating records). Conduct group discussion on data privacy and GDPR compliance.', 'Automate a follow-up email task in the CRM and update customer records after interactions.', 'Common CRM tasks are correctly automated and customer records updated.'),
(292, 73, 2, 'realisation', 5, 'In groups, discuss data privacy best practices in CRM systems and share one key privacy rule.', 'In groups, discuss data privacy in CRM systems and share one key data protection rule.', 'Data privacy best practices in CRM systems are correctly identified and explained.'),
(293, 74, 5, 'introduction', 5, 'Ask: What is Artificial Intelligence? Can you name any AI tools you have used or heard of?', 'Brainstorm AI tools they know or have used and share with the class.', 'Common AI tools and their uses are identified from prior knowledge.'),
(294, 74, 2, 'development', 20, 'Arrange students into groups to explain different AI tools and their functionalities. Guide discussion on techniques for using AI tools effectively and identifying credible AI tools.', 'Discuss AI tools in groups, identify their functionalities, and describe techniques for using them effectively.', 'AI tools and their functionalities are correctly identified and techniques for using them described.'),
(295, 74, 9, 'design', 10, 'Assist students to use AI tools to search for information, analyse data, generate images, and solve subject-specific questions.', 'Use an AI tool to search for information, generate an image, and solve an assigned subject question.', 'AI tools are correctly used to search, analyse, generate images, and solve subject questions.'),
(296, 74, 3, 'realisation', 5, 'Each student names two AI tools and describes one task each tool can perform.', 'Name two AI tools and describe one task each can perform.', 'Two AI tools and one task for each are correctly named and described.'),
(297, 75, 3, 'introduction', 5, 'Display pictures showing various business activities (shop, farm, factory). Ask students: What is a business? Where do you see businesses in your daily life?', 'Observe the pictures and respond to questions about businesses they see in their community.', 'Students can identify examples of businesses from their surroundings.'),
(298, 75, 2, 'development', 20, 'Provide handouts and guide students in groups to explore a scenario showing production, distribution and consumption activities. Guide them to derive the meaning and scope of a business from the scenario.', 'Read the scenario and handouts, discuss in groups, and share findings on the meaning, characteristics and scope of a business.', 'The concept and scope of a business are clearly described with correct examples.'),
(299, 75, 2, 'design', 10, 'Guide groups to draw a simple diagram showing how a business connects producers, distributors and consumers in their community.', 'In groups, create a diagram linking production, distribution and consumption with a real local business example.', 'A diagram correctly showing the business cycle is produced and explained.'),
(300, 75, 3, 'realisation', 5, 'Each student states one definition of a business and one example from their community.', 'Individually write a one-sentence definition of a business and give one local example.', 'A correct definition of a business is given with an appropriate example.'),
(301, 76, 5, 'introduction', 5, 'Brainstorm: Ask students ├óÔé¼ÔÇØ What makes something a business? List responses on the board.', 'Call out characteristics they think define a business based on prior knowledge.', 'Students can suggest at least two characteristics of a business.'),
(302, 76, 2, 'development', 20, 'Guide students in groups using handouts to identify and describe key characteristics of a business: profit motive, regular dealings, risk, economic activity, exchange of goods/services.', 'Discuss in groups, compare characteristics, and prepare a summary to share with the class.', 'Key characteristics of a business are correctly identified and described.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(303, 76, 6, 'design', 10, 'Think-Pair-Share: Each student thinks of a business activity and identifies which characteristics apply, then shares with a partner and then the class.', 'Identify characteristics of a chosen business, pair up to compare findings, then share with class.', 'Characteristics of a business are applied correctly to a given example.'),
(304, 76, 3, 'realisation', 5, 'Ask each student to write 3 key characteristics of a business on a card.', 'Write 3 characteristics of a business independently.', 'Three correct characteristics of a business are stated by each student.'),
(305, 77, 5, 'introduction', 5, 'Ask students to name all types of businesses they know in their area. Record on board.', 'Name businesses they know and attempt to group them by type.', 'Students suggest at least two different types of businesses.'),
(306, 77, 2, 'development', 20, 'Guide students to classify businesses by type (manufacturing, trading, service), by size (small, medium, large) and by form of ownership. Provide examples of each.', 'In groups, classify a list of given businesses into the correct categories with justification.', 'Types of businesses are correctly classified with appropriate examples.'),
(307, 77, 4, 'design', 10, 'Provide each group with business cards (names of businesses). Groups sort them into categories and justify their classification.', 'Sort business cards into correct categories: manufacturing, trading or service. Justify each placement.', 'Businesses are correctly sorted into appropriate categories with reasons.'),
(308, 77, 3, 'realisation', 5, 'Ask students to draw a simple classification chart for types of businesses individually.', 'Draw a classification chart showing at least 3 types of businesses with one example each.', 'A classification chart with correct types and examples is produced.'),
(309, 78, 3, 'introduction', 5, 'Display a list of business terms on the board (profit, capital, revenue, demand, supply). Ask: Which of these terms do you already know?', 'Identify terms they recognise and share their understanding with the class.', 'Students show prior knowledge of at least 2 business terms.'),
(310, 78, 2, 'development', 20, 'Provide handouts with definitions of key business terminologies. Guide groups to match terms with definitions and use each in a business sentence.', 'Read definitions, match terms to meanings in groups, and construct sentences using each term correctly.', 'Key business terminologies are correctly defined and used in sentences.'),
(311, 78, 6, 'design', 10, 'Think-Pair-Share: Each student is given 3 terms; they write definitions, compare with a partner and correct each other.', 'Write definitions of assigned terms, compare with partner, and agree on correct definitions.', 'Business terminologies are accurately defined after peer review.'),
(312, 78, 3, 'realisation', 5, 'Quiz: Ask 5 quick-fire questions using business terms. Students answer individually.', 'Answer 5 questions using correct business terminologies.', 'At least 4 out of 5 business terminologies are used correctly in answers.'),
(313, 79, 3, 'introduction', 5, 'Ask students: What would happen if a buyer and seller used different meanings for the word \"profit\"? Why does language matter in business?', 'Discuss why using correct terms matters in business communication.', 'Students articulate at least one reason why terminology matters in business.'),
(314, 79, 2, 'development', 20, 'Guide class discussion on how correct terminologies help in business communication, record keeping, negotiation, legal compliance, and management decision-making.', 'Participate in discussion and take notes on the importance of terminologies in specific business situations.', 'The importance of business terminologies in practice is explained with relevant examples.'),
(315, 79, 10, 'design', 10, 'Role play: Assign pairs to simulate a buyer-seller negotiation using correct business terms. Observe and give feedback.', 'Role-play a business negotiation using at least 5 correct business terms.', 'Correct business terminologies are used appropriately in the role-play scenario.'),
(316, 79, 3, 'realisation', 5, 'Students write two sentences explaining why terminologies are important in running a business.', 'Write two sentences explaining the practical importance of business terminologies.', 'The importance of business terminologies is explained correctly in own words.'),
(317, 80, 5, 'introduction', 5, 'Show video clips or images of various business activities. Ask: What does Business Studies cover as a school subject?', 'Watch/observe and suggest what topics Business Studies might cover.', 'Students can suggest at least 2 areas covered by Business Studies.'),
(318, 80, 2, 'development', 20, 'Guide students through jigsaw to explore the scope of Business Studies: production, marketing, finance, human resources, entrepreneurship. Each group covers one area and teaches others.', 'In jigsaw groups, research one area of Business Studies and present findings to peers.', 'The scope of Business Studies is described accurately covering at least 4 areas.'),
(319, 80, 4, 'design', 10, 'Groups create a mind map on paper showing the scope of Business Studies and how the areas connect.', 'Create a mind map linking all major areas of Business Studies.', 'A mind map correctly showing the scope of Business Studies is produced.'),
(320, 80, 3, 'realisation', 5, 'Each student describes the scope of Business Studies in two sentences.', 'Write two sentences describing what Business Studies covers as a subject.', 'The scope and nature of Business Studies is described correctly.'),
(321, 81, 5, 'introduction', 5, 'Brainstorm: Ask students why they are studying Business Studies and what they hope to gain from it.', 'Share personal reasons for studying Business Studies and listen to classmates\' responses.', 'Students articulate personal relevance of Business Studies.'),
(322, 81, 2, 'development', 20, 'Guide discussion on the importance of Business Studies: career development, entrepreneurship, daily life applications (budgeting, managing money, consumer awareness).', 'Participate in group discussion and compile a list of 5 reasons why Business Studies is important.', 'The importance and relevance of Business Studies is explained with specific examples.'),
(323, 81, 11, 'design', 10, 'Invite a resourceful person (local business owner or accountant) to share how Business Studies knowledge helped them. Students ask questions.', 'Listen to guest speaker and ask at least one question. Note key points from the presentation.', 'Students can explain how Business Studies is relevant to real careers and daily life.'),
(324, 81, 3, 'realisation', 5, 'Each student writes 3 reasons why Business Studies is important to them personally.', 'Write 3 reasons why Business Studies is personally important and relevant.', 'Three valid reasons for the importance of Business Studies are given.'),
(325, 82, 5, 'introduction', 5, 'Ask: What jobs can you get by studying Business Studies? Record all suggestions on the board.', 'Suggest career paths they associate with Business Studies.', 'Students suggest at least 3 career options related to Business Studies.'),
(326, 82, 12, 'development', 20, 'Guide students in groups to research career opportunities in Business Studies: accountant, marketing officer, entrepreneur, banker, business consultant, supply chain manager, tax officer.', 'Research and compile a list of career opportunities in Business Studies with brief descriptions of each role.', 'At least 5 career opportunities related to Business Studies are correctly identified and described.'),
(327, 82, 2, 'design', 10, 'Groups present their career findings. Class discusses qualifications needed for each career.', 'Present career findings and discuss with class what qualifications each career requires.', 'Career opportunities related to Business Studies are presented with relevant qualifications.'),
(328, 82, 3, 'realisation', 5, 'Each student names 3 career opportunities in Business Studies and describes the role in one sentence each.', 'Write 3 career opportunities with a one-sentence description of each.', 'Three career opportunities in Business Studies are correctly described.'),
(329, 83, 5, 'introduction', 5, 'Brainstorm: Guide students to list different activities performed by people in their community and what it takes to do them successfully.', 'Name community activities and discuss what skills and qualities are needed to do them successfully.', 'Students connect community activities to the qualities of an entrepreneur.'),
(330, 83, 2, 'development', 20, 'Guide students through group discussion on the meaning, characteristics, skills and importance of entrepreneurship, using handouts and video clips of successful entrepreneurs.', 'Discuss in groups and compile notes on the meaning of entrepreneurship and characteristics of a successful entrepreneur.', 'The concept of entrepreneurship is clearly defined with correct characteristics and importance.'),
(331, 83, 11, 'design', 10, 'Field trip debrief or video analysis: Guide students to analyse a local entrepreneur\'s story, identifying which entrepreneurship qualities they demonstrated.', 'Analyse a real entrepreneur\'s story, identifying characteristics and skills that made them successful.', 'Entrepreneurial characteristics are correctly identified from a real-life example.'),
(332, 83, 3, 'realisation', 5, 'Each student writes a definition of entrepreneurship and names 3 characteristics of a successful entrepreneur.', 'Write a definition of entrepreneurship and list 3 characteristics of an entrepreneur.', 'Entrepreneurship is correctly defined and 3 characteristics are accurately stated.'),
(333, 84, 3, 'introduction', 5, 'Show pictures of successful Tanzanian entrepreneurs (e.g., business leaders). Ask: What makes these people successful?', 'Observe pictures and suggest qualities that make these individuals successful entrepreneurs.', 'Students can identify at least 2 characteristics of successful entrepreneurs from observation.'),
(334, 84, 2, 'development', 20, 'Guide groups to identify and discuss the key characteristics of a successful entrepreneur: risk-taking, innovation, creativity, leadership, persistence, decision-making, communication.', 'In groups, research and discuss characteristics of successful entrepreneurs and prepare a presentation.', 'Key characteristics of a successful entrepreneur are correctly identified and described.'),
(335, 84, 7, 'design', 10, 'Case study: Provide case studies of successful and unsuccessful entrepreneurs. Groups identify which characteristics were present or absent.', 'Analyse case studies and identify which entrepreneurial characteristics contributed to success or failure.', 'Entrepreneurial characteristics are correctly applied in case study analysis.'),
(336, 84, 3, 'realisation', 5, 'Ask students to rank the 3 most important characteristics of an entrepreneur and justify their ranking.', 'Rank 3 entrepreneurial characteristics in order of importance and justify the ranking.', 'Top 3 entrepreneurial characteristics are ranked with a valid justification.'),
(337, 85, 3, 'introduction', 5, 'Ask students: How do businesses help our community and country? What happens when many people start businesses?', 'Discuss how businesses they know contribute to the community.', 'Students identify at least 2 ways businesses benefit the community.'),
(338, 85, 2, 'development', 20, 'Guide discussion on the role of entrepreneurship in economic development: job creation, production of goods and services, generating government revenue, innovation, poverty reduction.', 'Participate in group discussion and compile a list of ways entrepreneurship contributes to economic development.', 'The importance of entrepreneurship in economic development is explained with specific examples.'),
(339, 85, 4, 'design', 10, 'Groups create a diagram showing how entrepreneurship contributes to Tanzania\'s economic development, linking entrepreneur ├óÔÇáÔÇÖ business ├óÔÇáÔÇÖ jobs ├óÔÇáÔÇÖ taxes ├óÔÇáÔÇÖ development.', 'Create a diagram showing the chain of how entrepreneurship drives economic development.', 'A diagram correctly showing entrepreneurship\'s contribution to economic development is produced.'),
(340, 85, 3, 'realisation', 5, 'Each student explains in writing two specific ways entrepreneurship contributes to Tanzania\'s economic development.', 'Write two specific ways entrepreneurship contributes to Tanzania\'s economy.', 'Two valid contributions of entrepreneurship to economic development are stated correctly.'),
(341, 86, 3, 'introduction', 5, 'Present names of the main entrepreneurship theories: Innovation Theory, Economic Theory, Sociological Theory, Opportunity-Based Theory. Ask what students think each theory says.', 'Predict what each theory might be about based on its name.', 'Students show curiosity and make logical predictions about entrepreneurship theories.'),
(342, 86, 10, 'development', 20, 'Guide groups to simulate/role-play scenarios representing different theories of entrepreneurship. Each group acts out one theory and explains it to the class.', 'Prepare and perform a role-play representing an assigned entrepreneurship theory. Explain the theory to classmates.', 'Major theories of entrepreneurship are correctly described through role play and explanation.'),
(343, 86, 2, 'design', 10, 'Groups compare the theories: What does each say drives entrepreneurship? Where do they agree or differ?', 'Compare assigned theories and identify key similarities and differences.', 'Similarities and differences between entrepreneurship theories are correctly identified.'),
(344, 86, 3, 'realisation', 5, 'Each student describes two theories of entrepreneurship in their own words.', 'Write brief descriptions of two entrepreneurship theories in own words.', 'Two theories of entrepreneurship are correctly described.'),
(345, 87, 7, 'introduction', 5, 'Present a brief case study of a Tanzanian entrepreneur. Ask: Which theory do you think best explains why this person became an entrepreneur?', 'Read the case study and suggest which entrepreneurship theory applies and why.', 'Students attempt to link a business case to an entrepreneurship theory.'),
(346, 87, 7, 'development', 20, 'Provide case studies of different Tanzanian businesses. Guide groups to analyse each using a specific entrepreneurship theory and present their analysis.', 'Analyse assigned case studies using entrepreneurship theories and prepare a group presentation.', 'Entrepreneurship theories are correctly applied to analyse given business situations.'),
(347, 87, 2, 'design', 10, 'Groups debate which entrepreneurship theory best explains the success of local businesses in Tanzania.', 'Participate in a structured debate on which theory best explains Tanzanian entrepreneurship.', 'Students demonstrate ability to evaluate and defend the application of entrepreneurship theories.'),
(348, 87, 3, 'realisation', 5, 'Each student writes a short analysis of a given business situation using one entrepreneurship theory.', 'Write a short paragraph analysing a business situation using one specific theory of entrepreneurship.', 'An entrepreneurship theory is correctly applied to analyse a given business situation.'),
(349, 88, 2, 'introduction', 5, 'Ask: Do theories developed in other countries fully apply to businesses in Tanzania? What might be different here?', 'Discuss the local business environment and how it might differ from where theories were developed.', 'Students identify at least one contextual difference that could affect theory relevance.'),
(350, 88, 2, 'development', 20, 'Guide critical group discussion on the relevance and limitations of each entrepreneurship theory in the Tanzanian context (cultural factors, economic conditions, regulatory environment).', 'Discuss in groups the applicability of entrepreneurship theories to the Tanzanian business environment.', 'The relevance of entrepreneurship theories to the Tanzanian context is critically evaluated.'),
(351, 88, 2, 'design', 10, 'Each group evaluates one theory\'s relevance to Tanzania and presents strengths and weaknesses.', 'Evaluate the relevance of an assigned theory in Tanzania and present findings.', 'Strengths and limitations of each entrepreneurship theory in the Tanzanian context are correctly identified.'),
(352, 88, 3, 'realisation', 5, 'Each student writes their evaluation of one theory\'s relevance to entrepreneurship in Tanzania.', 'Write an evaluation of one entrepreneurship theory\'s relevance in the Tanzanian context.', 'A balanced evaluation of an entrepreneurship theory\'s relevance to Tanzania is provided.'),
(353, 89, 5, 'introduction', 5, 'Brainstorm: Guide students to identify businesses in their community owned by one person. Ask why some businesses are owned by one person and others by more.', 'Name businesses owned by one person in their community and suggest why someone might run a business alone.', 'Students identify examples of sole proprietor businesses from their surroundings.'),
(354, 89, 2, 'development', 20, 'Guide group discussion on the concept, meaning and features of sole proprietorship. Supplement with a guest speaker (sole proprietor) sharing their experience.', 'Discuss the meaning and features of sole proprietorship, listen to guest speaker, and take notes.', 'The concept of sole proprietorship is clearly defined with correct features.'),
(355, 89, 2, 'design', 10, 'Groups draw a comparison chart between sole proprietorship and other forms of business ownership they know.', 'Create a comparison chart showing how sole proprietorship differs from other forms of business.', 'Sole proprietorship is correctly distinguished from other forms of business ownership.'),
(356, 89, 3, 'realisation', 5, 'Students write a definition of sole proprietorship and list 3 features.', 'Write a definition of sole proprietorship and list 3 key features.', 'Sole proprietorship is correctly defined with 3 accurate features.'),
(357, 90, 3, 'introduction', 5, 'Ask: What are the good things and bad things about running a business completely on your own?', 'Share perceived advantages and disadvantages of running a business alone.', 'Students can suggest at least 2 advantages and 2 disadvantages of operating alone.'),
(358, 90, 2, 'development', 20, 'Guide discussion on advantages (full control, all profits retained, quick decisions, simple to form, privacy) and disadvantages (unlimited liability, limited capital, no continuity, all risks) of sole proprietorship.', 'Discuss and compile a list of advantages and disadvantages of sole proprietorship.', 'Advantages and disadvantages of sole proprietorship are correctly identified and explained.'),
(359, 90, 7, 'design', 10, 'Case study: Students analyse a given sole proprietor business scenario and identify which advantages and disadvantages are evident.', 'Analyse a case study of a sole proprietor and identify advantages and disadvantages experienced.', 'Advantages and disadvantages of sole proprietorship are correctly applied to a case study.'),
(360, 90, 4, 'realisation', 5, 'Each student creates a T-chart listing 3 advantages and 3 disadvantages of sole proprietorship.', 'Create a T-chart with 3 advantages and 3 disadvantages of sole proprietorship.', 'A T-chart with 3 correct advantages and 3 correct disadvantages of sole proprietorship is produced.'),
(361, 91, 3, 'introduction', 5, 'Ask: What steps would you take to start your own business legally in Tanzania? What documents might you need?', 'Suggest steps they think are needed to start a legal business.', 'Students attempt to outline basic steps for starting a business.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(362, 91, 2, 'development', 20, 'Guide students to describe the steps for forming a sole proprietorship in Tanzania: develop business idea ├óÔÇáÔÇÖ source capital ├óÔÇáÔÇÖ choose business name ├óÔÇáÔÇÖ register with BRELA ├óÔÇáÔÇÖ obtain trading licence ├óÔÇáÔÇÖ open bank account.', 'Discuss and document the steps and legal requirements for forming a sole proprietorship using BRELA resources.', 'The steps and legal requirements for forming a sole proprietorship in Tanzania are correctly described.'),
(363, 91, 8, 'design', 10, 'Project activity: Groups write a simple report on how to register a sole proprietorship in Tanzania, including required documents and costs.', 'Write a group report outlining the registration process and legal requirements for a sole proprietorship.', 'A report correctly detailing the steps for forming a sole proprietorship is produced.'),
(364, 91, 3, 'realisation', 5, 'Each student outlines the 4 main steps for forming a sole proprietorship in the correct order.', 'List the 4 main steps for forming a sole proprietorship in the correct sequence.', 'The 4 main steps for forming a sole proprietorship are listed correctly and in order.'),
(365, 92, 5, 'introduction', 5, 'Ask: Where does the money come from to start a business? If you had no money, how would you start?', 'Suggest possible sources of money for starting a business.', 'Students identify at least 2 sources of start-up capital.'),
(366, 92, 2, 'development', 20, 'Guide students to identify and describe various sources of capital: personal savings, loans from family/friends, bank loans, microfinance institutions, SACCOS, government grants.', 'In groups, research and discuss sources of capital available to sole proprietors in Tanzania.', 'At least 4 sources of capital for a sole proprietor are correctly identified and described.'),
(367, 92, 2, 'design', 10, 'Groups evaluate the best sources of capital for a small business in their local area, considering accessibility, cost and risk.', 'Evaluate and rank sources of capital by suitability for a small sole proprietor business in the local area.', 'Sources of capital are evaluated with valid criteria and ranked appropriately.'),
(368, 92, 3, 'realisation', 5, 'Each student lists 4 sources of capital and explains one advantage of each source.', 'List 4 sources of capital with one advantage for each.', 'Four sources of capital are listed with a correct advantage stated for each.'),
(369, 93, 7, 'introduction', 5, 'Present a short case study of a struggling sole proprietor. Ask: What problems is this business facing?', 'Read the case study and identify problems facing the business.', 'Students identify at least 2 challenges from the case study.'),
(370, 93, 2, 'development', 20, 'Guide groups to identify and discuss common challenges: limited capital, unlimited liability, heavy workload, competition, lack of managerial skills, market access, government regulations.', 'In groups, identify and discuss challenges facing sole proprietorship businesses and prepare a summary.', 'Key challenges facing sole proprietorship businesses are correctly identified and explained.'),
(371, 93, 2, 'design', 10, 'Groups categorise the challenges into financial, managerial and market-related and present their categorisation.', 'Categorise identified challenges into financial, managerial and market-related groups.', 'Challenges are correctly categorised into appropriate groups with justification.'),
(372, 93, 3, 'realisation', 5, 'Each student identifies and briefly describes 3 challenges facing a sole proprietorship.', 'Write 3 challenges facing sole proprietorship businesses with a brief explanation of each.', 'Three challenges facing sole proprietorship are correctly identified and described.'),
(373, 94, 5, 'introduction', 5, 'Refer to the case study from the previous lesson. Ask: How can the sole proprietor solve the problems identified?', 'Suggest possible solutions to the challenges identified in the case study.', 'Students suggest at least 2 practical solutions to challenges facing a sole proprietor.'),
(374, 94, 2, 'development', 20, 'Guide students to brainstorm and discuss practical solutions: joining SACCO, seeking microfinance, employing staff, marketing strategies, business training, forming partnerships.', 'Brainstorm and discuss solutions to each challenge. Evaluate which solutions are most practical.', 'Practical solutions to challenges facing sole proprietors are proposed and justified.'),
(375, 94, 8, 'design', 10, 'Groups develop a simple action plan with specific solutions for each challenge, evaluating the effectiveness of each solution.', 'Create a group action plan proposing solutions to 3 challenges with evaluation of effectiveness.', 'An action plan with feasible solutions and evaluation is produced.'),
(376, 94, 3, 'realisation', 5, 'Each student writes a brief action plan proposing solutions to 3 challenges facing a sole proprietor.', 'Write an action plan with solutions to 3 challenges facing a sole proprietor.', 'An action plan with 3 valid solutions to sole proprietorship challenges is produced.'),
(377, 95, 5, 'introduction', 5, 'Bunguabongo: Ongoza wanafunzi kubungua bongo kwa kuuliza: \"Historia ni nini? Kwa nini tunajifunza Historia?\"', 'Toa mawazo yao juu ya maana ya Historia na kwa nini ni muhimu kujifunza.', 'Wanafunzi wanaweza kutoa maelezo ya awali ya Historia.'),
(378, 95, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kwa kutumia matini kuhusu maana ya Historia, tofauti kati ya Historia na hadithi za kimapokeo, na umuhimu wake katika maisha ya kila siku.', 'Jadili katika vikundi maana ya Historia na umuhimu wake. Wasilisha muhtasari darasani.', 'Maana ya Historia na umuhimu wake katika maisha ya kila siku vimeelezwa kwa usahihi.'),
(379, 95, 2, 'design', 10, 'Ongoza wanafunzi katika vikundi vyao waorodheshe matukio ya kihistoria yanayowagusa na umuhimu wa kuyajua.', 'Orodhesha matukio 3 ya kihistoria yanayogusa maisha yao na eleza umuhimu wa kuyajua.', 'Matukio ya kihistoria yanayohusiana na maisha ya sasa yametambuliwa kwa usahihi.'),
(380, 95, 3, 'realisation', 5, 'Kila mwanafunzi aeleze kwa sentensi mbili maana ya Historia na sababu moja ya kwa nini ni muhimu kusoma Historia.', 'Andika sentensi mbili: maana ya Historia na sababu moja ya umuhimu wake.', 'Maana ya Historia imeelezwa kwa usahihi na sababu ya umuhimu imebainishwa.'),
(381, 96, 3, 'introduction', 5, 'Simulia hadithi fupi ya kimapokeo kisha uliza: Je, hii ni Historia? Inafananaje na Historia? Inatofautianaje?', 'Sikiliza hadithi na jaribu kutofautisha kati ya hadithi ya kimapokeo na Historia.', 'Wanafunzi wanaweza kubainisha tofauti moja kati ya Historia na hadithi.'),
(382, 96, 2, 'development', 20, 'Ongoza majadiliano ya kikundi kulinganisha vipengele vya Historia (ukweli unaothibitishwa na vyanzo) na hadithi za kimapokeo (simulizi zilizopitishwa kwa mdomo).', 'Jadili na kuandika vipengele vya Historia na vya hadithi za kimapokeo katika jedwali la ulinganisho.', 'Tofauti kati ya Historia na hadithi za kimapokeo zimebainishwa kwa usahihi.'),
(383, 96, 6, 'design', 10, 'Fikiri-andika-jozisha-shirikisha: Kila mwanafunzi aandike tofauti tatu kati ya Historia na hadithi, kisha ajadili na mwenzake.', 'Andika tofauti 3, jozisha na mwenzako, kisha shirikishana na darasa.', 'Tofauti sahihi tatu kati ya Historia na hadithi za kimapokeo zimebainishwa.'),
(384, 96, 3, 'realisation', 5, 'Kila mwanafunzi aeleze kwa maneno yake tofauti kuu mbili kati ya Historia na hadithi za kimapokeo.', 'Andika tofauti mbili kuu kati ya Historia na hadithi za kimapokeo.', 'Tofauti mbili sahihi kati ya Historia na hadithi zimebainishwa.'),
(385, 97, 5, 'introduction', 5, 'Onyesha picha au vitu halisi (chombo cha zamani, ramani, kitabu cha zamani). Uliza: Vitu hivi vinaweza kutusaidia kujua nini kuhusu Historia?', 'Angalia vitu vilivyoonyeshwa na pendekeza jinsi vinavyoweza kutoa habari za kihistoria.', 'Wanafunzi wanaweza kubainisha angalau chanzo kimoja cha kihistoria.'),
(386, 97, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu vyanzo vya Historia: vyanzo vya maandishi (vitabu, nyaraka), vyanzo vya mdomo (masimulizi, nyimbo), vyanzo vya akiolojia (mabaki, sanamu), na vyanzo vya picha.', 'Jadili na uorodhesha vyanzo mbalimbali vya Historia na eleza mfano wa kila chanzo.', 'Vyanzo mbalimbali vya Historia vimetambuliwa na kuelezwa kwa usahihi.'),
(387, 97, 4, 'design', 10, 'Gawanya vyanzo mbalimbali kwa vikundi. Kila kikundi kiwasilishe chanzo chake na mfano wa jinsi kinavyotumika.', 'Wasilisha chanzo kilichopewa kwa darasa, ukitoa mfano halisi wa chanzo hicho.', 'Chanzo cha Historia kimebainishwa na kuelezwa vizuri kwa mfano sahihi.'),
(388, 97, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe vyanzo vine vya Historia na atoe mfano mmoja kwa kila chanzo.', 'Orodhesha vyanzo 4 vya Historia na toa mfano mmoja kwa kila chanzo.', 'Vyanzo vine vya Historia vimeorodheshwa na mifano sahihi imetolewa.'),
(389, 98, 7, 'introduction', 5, 'Onyesha nakala mbili zinazoelezea tukio moja lakini zinatoa habari tofauti. Uliza: Ni ipi inayostahili kuaminiwa zaidi?', 'Linganisha vyanzo viwili na pendekeza kipi ni cha kuaminika zaidi na kwa nini.', 'Wanafunzi wanaonyesha uwezo wa kutathmini chanzo kidogo cha kihistoria.'),
(390, 98, 2, 'development', 20, 'Ongoza majadiliano ya vikundi tathmini ubora (uhakika, uaminifu, uhalali) na mapungufu (upendeleo, kukosekana kwa sehemu, upotevu wa muda) ya vyanzo mbalimbali vya Historia.', 'Jadili na utathmini ubora na mapungufu ya chanzo kilichopewa kwa kutumia vigezo vya uhalisi na uaminifu.', 'Ubora na mapungufu ya vyanzo vya Historia vimetathminiwa kwa usahihi kwa kutumia vigezo sahihi.'),
(391, 98, 7, 'design', 10, 'Kisa mafunzo: Vikundi vitathmini vyanzo viwili tofauti vya tukio moja la kihistoria na viorodheshe nguvu na udhaifu wa kila chanzo.', 'Tathmini vyanzo viwili vya tukio moja la kihistoria na uandike nguvu na udhaifu wa kila kimoja.', 'Tathmini yenye mantiki ya vyanzo vya kihistoria imeandikwa kwa kutumia vigezo sahihi.'),
(392, 98, 3, 'realisation', 5, 'Kila mwanafunzi aeleze kwa sentensi mbili ubora mmoja na upungufu mmoja wa chanzo alichopewa.', 'Andika ubora mmoja na upungufu mmoja wa chanzo cha Historia kilichopewa.', 'Ubora na upungufu wa chanzo cha Historia vimebainishwa kwa usahihi.'),
(393, 99, 5, 'introduction', 5, 'Uliza: Kwa nini mashule yanafundisha Historia? Je, kujua Historia kunakusaidiaje wewe binafsi?', 'Shiriki mawazo kuhusu umuhimu wa Historia kwa mtu binafsi.', 'Wanafunzi wanatoa sababu za msingi za kusoma Historia.'),
(394, 99, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu umuhimu wa Historia: kutambua utambulisho, kujifunza makosa ya zamani, kuimarisha umoja wa taifa, kulinda urithi, kupanga mustakabali.', 'Jadili na uandike umuhimu wa Historia kwa mtu binafsi na kwa taifa kwa ujumla.', 'Umuhimu wa Historia kwa mtu binafsi na kwa taifa umeelezwa kwa kina na mifano sahihi.'),
(395, 99, 11, 'design', 10, 'Mwalike mtaalamu (mwalimu mkongwe au mtaalam wa historia) ashirikiane na wanafunzi kueleza jinsi Historia inavyoathiri maisha yetu ya sasa.', 'Sikiliza mtaalamu na uulize swali moja kuhusu umuhimu wa Historia kwa Tanzania ya sasa.', 'Wanafunzi wanabainisha angalau njia tatu za Historia kuathiri maisha ya sasa.'),
(396, 99, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe sababu tatu za umuhimu wa Historia ├óÔé¼ÔÇØ moja kwa binafsi, moja kwa jamii, moja kwa taifa.', 'Orodhesha sababu tatu: moja kwa mtu binafsi, moja kwa jamii, moja kwa taifa.', 'Sababu tatu sahihi za umuhimu wa Historia zimeorodheshwa.'),
(397, 100, 5, 'introduction', 5, 'Uliza: Ni somo gani jingine shuleni linaloelezea matukio ya zamani? Historia inaunganika vipi na Jiografia, Kiswahili au Uraia?', 'Pendekeza masomo mengine yanayounganika na Historia.', 'Wanafunzi wanabainisha masomo mengine yanayohusiana na Historia.'),
(398, 100, 2, 'development', 20, 'Ongoza vikundi kuchunguza uhusiano wa Historia na masomo mengine: Jiografia (maeneo ya matukio), Kiswahili (vyanzo vya mdomo), Uraia (sheria na serikali), Sayansi (teknolojia ya zamani).', 'Jadili na uandike mfano mmoja wa jinsi Historia inavyounganika na masomo manne mengine.', 'Uhusiano wa Historia na masomo mengine umebainishwa kwa mifano sahihi.'),
(399, 100, 4, 'design', 10, 'Vikundi viunde ramani ya akili inayoonyesha Historia katikati na masomo mengine yanayounganika nayo.', 'Unda ramani ya akili inayoonesha Historia ikiunganika na masomo mengine na eleza uhusiano huo.', 'Ramani ya akili inayoonesha uhusiano wa Historia na masomo mengine imeundwa kwa usahihi.'),
(400, 100, 3, 'realisation', 5, 'Kila mwanafunzi aeleze kwa mfano mmoja jinsi Historia inavyohusiana na somo jingine analonopenda.', 'Eleza kwa sentensi mbili jinsi Historia inavyohusiana na somo jingine unalolipenda.', 'Uhusiano wa Historia na somo jingine umebainishwa kwa mfano sahihi.'),
(401, 101, 3, 'introduction', 5, 'Onyesha picha za sokwe na binadamu. Uliza: Je, binadamu alitoka wapi? Kuna nadharia gani?', 'Angalia picha na toa mawazo ya awali kuhusu asili ya binadamu.', 'Wanafunzi wanaonyesha udadisi kuhusu asili ya binadamu.'),
(402, 101, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu nadharia za mageuzi ya binadamu: Nadharia ya Mageuzi ya Darwin, Nadharia ya Uumbaji, na nadharia nyingine. Toa matini za kusaidia.', 'Jadili nadharia mbalimbali za mageuzi ya binadamu katika vikundi na wasilisha muhtasari.', 'Nadharia mbalimbali za mageuzi ya binadamu zimeelezwa kwa usahihi.'),
(403, 101, 2, 'design', 10, 'Vikundi vilinganishe nadharia: Zinaungana vipi? Zinatofautiana vipi? Ni ipi inayoungwa mkono na ushahidi wa kisayansi zaidi?', 'Linganisha nadharia mbili za mageuzi na bainisha tofauti na mfanano wao.', 'Nadharia za mageuzi zimlinganishwa kwa usahihi.'),
(404, 101, 3, 'realisation', 5, 'Kila mwanafunzi aeleze kwa maneno yake nadharia moja ya mageuzi ya binadamu.', 'Eleza kwa sentensi tatu nadharia moja ya mageuzi ya binadamu.', 'Nadharia moja ya mageuzi ya binadamu imeelezwa kwa usahihi.'),
(405, 102, 1, 'introduction', 5, 'Onyesha mstari wa muda (timeline) wa hatua za mageuzi ya binadamu. Uliza wanafunzi kuupanga.', 'Angalia mstari wa muda na ujaribu kuupanga kwa mpangilio sahihi.', 'Wanafunzi wanajaribu kupanga hatua za mageuzi kwa mpangilio.'),
(406, 102, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu hatua za mageuzi: Australopithecus, Homo habilis, Homo erectus, Homo sapiens. Eleza sifa za kila hatua na jinsi ilivyobadilika.', 'Jadili hatua za mageuzi katika vikundi na uandike sifa za kila hatua kwenye jedwali.', 'Hatua za mageuzi ya binadamu kutoka sokwe hadi binadamu wa kisasa zimeelezwa kwa usahihi.'),
(407, 102, 4, 'design', 10, 'Vikundi viunde mstari wa muda unaoonyesha hatua za mageuzi ya binadamu na sifa za kila hatua.', 'Unda mstari wa muda unaoonesha hatua za mageuzi ya binadamu na sifa za kila hatua.', 'Mstari wa muda wenye hatua sahihi za mageuzi umeundwa.'),
(408, 102, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe hatua nne za mageuzi ya binadamu kwa mpangilio sahihi na sifa moja ya kila hatua.', 'Orodhesha hatua 4 za mageuzi kwa mpangilio na sifa moja ya kila hatua.', 'Hatua nne za mageuzi zimeorodheshwa kwa mpangilio sahihi na sifa sahihi.'),
(409, 103, 3, 'introduction', 5, 'Uliza: Watu wa zamani kabla ya kugunduliwa moto waliishi vipi? Walilaa nini? Waliishi wapi?', 'Pendekeza jinsi watu wa zamani wanavyofikiriwa walivyoishi.', 'Wanafunzi wanabainisha mambo mawili kuhusu maisha ya zamani.'),
(410, 103, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu maisha ya binadamu katika Zama za Mawe za Kale: uwindaji na ukusanyaji, maisha ya kuhamahama, kukaa mapangoni, matumizi ya zana za mawe.', 'Jadili na uandike vipengele vya maisha ya binadamu katika Zama za Mawe za Kale.', 'Maisha ya binadamu katika Zama za Mawe za Kale yameelezwa kwa usahihi.'),
(411, 103, 4, 'design', 10, 'Vikundi viandike na kuchora picha inayoonyesha siku ya kawaida ya binadamu wa Zama za Mawe za Kale.', 'Chora na ueleze picha inayoonesha maisha ya kawaida ya binadamu wa Zama za Mawe za Kale.', 'Picha sahihi inayoonesha maisha ya Zama za Mawe imechorwa na kuelezwa.'),
(412, 103, 3, 'realisation', 5, 'Kila mwanafunzi aeleze vipengele vitatu vya maisha ya binadamu katika Zama za Mawe za Kale.', 'Eleza vipengele vitatu vya maisha ya binadamu katika Zama za Mawe za Kale.', 'Vipengele vitatu sahihi vya maisha ya Zama za Mawe vimebainishwa.'),
(413, 104, 3, 'introduction', 5, 'Onyesha mstari wa muda wa Zama za Mawe. Uliza: Zama hizi zinatofautiana vipi?', 'Angalia mstari wa muda na jaribu kubainisha tofauti kati ya Zama za Mawe.', 'Wanafunzi wanajaribu kutofautisha Zama za Mawe.'),
(414, 104, 2, 'development', 20, 'Ongoza vikundi kulinganisha Zama za Mawe za Kale (uwindaji, mawe makubwa), Kati (zana ndogo-ndogo, mazingira mapya) na za Karibuni (kilimo cha mwanzo, mifugo).', 'Jaza jedwali la ulinganisho la Zama za Mawe tatu kwa kutumia matini uliyopewa.', 'Tofauti kati ya Zama za Mawe za Kale, Kati na za Karibuni zimebainishwa kwa usahihi.'),
(415, 104, 6, 'design', 10, 'Fikiri-andika-jozisha-shirikisha: Kila mwanafunzi aandike tofauti mbili, ajozishe na mwenzake, wasilishane.', 'Andika tofauti mbili kati ya Zama za Mawe, jozisha na mwenzako na shirikisha darasa.', 'Tofauti sahihi kati ya Zama za Mawe zimebainishwa.'),
(416, 104, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe tofauti mbili kati ya Zama za Mawe za Kale na za Karibuni.', 'Orodhesha tofauti mbili kati ya Zama za Mawe za Kale na za Karibuni.', 'Tofauti sahihi mbili kati ya Zama za Mawe zimebainishwa.'),
(417, 105, 1, 'introduction', 5, 'Onyesha picha za zana za mawe za zamani. Uliza: Zana hizi zilifanywa na nini? Zilitumika kwa nini?', 'Angalia picha na toa mawazo kuhusu matumizi ya zana za mawe.', 'Wanafunzi wanabainisha zana na matumizi yake ya awali.'),
(418, 105, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu zana za mawe (visu, nguruwe, mikuki) na zana za baadaye (shoka, sindano za mfupa). Eleza jinsi zilivyotengenezwa na kutumika.', 'Jadili zana za kila Zama za Mawe, jinsi zilivyotengenezwa na matumizi yake. Andika muhtasari.', 'Zana za binadamu wa zamani zimebainishwa na kuelezwa jinsi zilivyotengenezwa na kutumika.'),
(419, 105, 4, 'design', 10, 'Vikundi vichoree na vibandike jina na matumizi ya zana tano za zamani kwenye karatasi kubwa.', 'Chora zana tano za zamani, zipe majina na ueleze matumizi ya kila zana.', 'Zana tano za binadamu wa zamani zimechorwa na kuelezwa matumizi yake kwa usahihi.'),
(420, 105, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe zana tatu za binadamu wa zamani na matumizi ya kila zana.', 'Orodhesha zana tatu za binadamu wa zamani na matumizi ya kila moja.', 'Zana tatu za binadamu wa zamani zimeorodheshwa na matumizi yake yameelezwa.'),
(421, 106, 1, 'introduction', 5, 'Onyesha ramani ya Tanzania ukionyesha Bonde la Olduvai, Laetoli na maeneo mengine. Uliza: Kwa nini maeneo haya ni maarufu?', 'Angalia ramani na taja maeneo unayoyajua ambayo ni maarufu kihistoria.', 'Wanafunzi wanabainisha angalau eneo moja la kiakiolojia Tanzania.'),
(422, 106, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu maeneo ya kiakiolojia Tanzania: Bonde la Olduvai (Arusha), Laetoli (alama za miguu ya zamani), Kondoa Irangi (michoro ya mapangoni), Engaruka.', 'Jadili maeneo ya kiakiolojia Tanzania, jinsi yalivyogunduliwa na umuhimu wake.', 'Maeneo ya kiakiolojia Tanzania yamebainishwa na kuelezwa kwa usahihi.'),
(423, 106, 12, 'design', 10, 'Vikundi vitafiti moja ya maeneo ya kiakiolojia Tanzania kwa kina na viwasilishe matokeo.', 'Tafiti eneo moja la kiakiolojia Tanzania na uwasilishe ukweli muhimu watano kuhusu eneo hilo.', 'Eneo la kiakiolojia Tanzania limetafitishwa na kuwasilishwa kwa usahihi.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(424, 106, 3, 'realisation', 5, 'Kila mwanafunzi ataje maeneo matatu ya kiakiolojia Tanzania na mabaki yaliyopatikana kila eneo.', 'Taja maeneo matatu ya kiakiolojia Tanzania na mabaki yaliyopatikana kila eneo.', 'Maeneo matatu ya kiakiolojia Tanzania yametajwa na mabaki yake yamebainishwa.'),
(425, 107, 7, 'introduction', 5, 'Simulia ugunduzi wa Louis Leakey huko Olduvai. Uliza: Kwa nini ugunduzi huu ni muhimu kwa historia ya binadamu?', 'Sikiliza hadithi ya ugunduzi na eleza kwa nini unafikiria ni muhimu.', 'Wanafunzi wanabainisha umuhimu wa ugunduzi wa Olduvai.'),
(426, 107, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu umuhimu wa maeneo ya kiakiolojia: kuthibitisha nadharia za mageuzi, kuelewa maisha ya zamani, kuvutia utalii, kulinda urithi wa Taifa.', 'Jadili umuhimu wa maeneo ya kiakiolojia Tanzania na uandike hoja tano za umuhimu huu.', 'Umuhimu wa maeneo ya kiakiolojia Tanzania umebainishwa kwa usahihi.'),
(427, 107, 2, 'design', 10, 'Vikundi viunde hoja kwa nini Tanzania inapaswa kulinda na kutangaza maeneo yake ya kiakiolojia.', 'Unda hoja tatu za kwa nini Tanzania inapaswa kulinda maeneo yake ya kiakiolojia.', 'Hoja sahihi za kulinda maeneo ya kiakiolojia Tanzania zimeundwa.'),
(428, 107, 3, 'realisation', 5, 'Kila mwanafunzi aeleze umuhimu wa Bonde la Olduvai kwa Tanzania na kwa historia ya binadamu.', 'Eleza umuhimu wa Bonde la Olduvai katika sentensi mbili.', 'Umuhimu wa Bonde la Olduvai umebainishwa kwa usahihi.'),
(429, 108, 5, 'introduction', 5, 'Uliza: Watu wa zamani Africa Mashariki walijipatia chakula vipi? Waliishi vipi? Andika majibu ubaoni.', 'Pendekeza njia wanazofikiria watu wa zamani walijipatia chakula.', 'Wanafunzi wanabainisha njia za msingi za kujipatia chakula.'),
(430, 108, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kutambua makundi makuu ya watu wa mapema: wawindaji-wakusanyaji (hunters-gatherers), wafugaji (pastoralists), na wakulima wa mapema (early farmers). Eleza sifa za kila kundi.', 'Jadili makundi ya watu wa mapema Afrika Mashariki na uziorodheshe sifa za kila kundi.', 'Makundi ya wawindaji, wafugaji na wakulima wa mapema yamebainishwa kwa usahihi.'),
(431, 108, 6, 'design', 10, 'Fikiri-andika-jozisha-shirikisha: Kila mwanafunzi achague kundi moja na aeleze sifa zake, kisha ajadili na mwenzake.', 'Chagua kundi moja, andika sifa zake, jozisha na mwenzako na shirikisha darasa.', 'Sifa za kundi lililochaguliwa zimebainishwa kwa usahihi.'),
(432, 108, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe makundi matatu ya watu wa mapema na sifa moja ya kila kundi.', 'Orodhesha makundi matatu na sifa moja ya kila kundi.', 'Makundi matatu ya watu wa mapema yameorodheshwa na sifa sahihi zimebainishwa.'),
(433, 109, 2, 'introduction', 5, 'Gawanya darasa katika makundi matatu yanayowakilisha wawindaji, wafugaji na wakulima. Kila kundi likae pamoja na lijadili wanachojua kuhusu kundi lake.', 'Jadili katika kundi lako unachojua kuhusu mfumo wa maisha ya kundi lako.', 'Wanafunzi wanaonyesha maarifa ya awali kuhusu mfumo wa maisha ya kundi lao.'),
(434, 109, 2, 'development', 20, 'Ongoza kila kundi kuchunguza kwa kina mfumo wa maisha ya kundi lake: chakula, makazi, zana, mfumo wa kijamii, mahusiano na mazingira. Vikundi viwasilishe kwa darasa zima.', 'Chunguza mfumo wa maisha ya kundi lako na uwasilishe: chakula, makazi, zana na mfumo wa kijamii.', 'Mfumo wa maisha wa kila kundi la watu wa mapema umebainishwa kwa usahihi.'),
(435, 109, 10, 'design', 10, 'Kila kundi liigize siku ya kawaida ya kundi lake mbele ya darasa ├óÔé¼ÔÇØ wawindaji wakienda kuwinda, wafugaji wakihama na mifugo, wakulima wakifanya kazi shambani.', 'Igiza siku ya kawaida ya kundi lako mbele ya darasa ukionyesha shughuli za kila siku.', 'Mfumo wa maisha wa kundi umebainishwa kupitia mchezo wa kuigiza.'),
(436, 109, 3, 'realisation', 5, 'Kila mwanafunzi aeleze tofauti mbili za mfumo wa maisha kati ya wawindaji na wakulima wa mapema.', 'Eleza tofauti mbili za mfumo wa maisha kati ya wawindaji-wakusanyaji na wakulima wa mapema.', 'Tofauti mbili sahihi za mfumo wa maisha kati ya makundi zimebainishwa.'),
(437, 110, 5, 'introduction', 5, 'Uliza: Kwa nini watu wanaacha makwao na kwenda sehemu nyingine? Nini kinaweza kusababisha uhamaji?', 'Toa sababu wanazofikiria zinaweza kusababisha watu kuhamia mahali pengine.', 'Wanafunzi wanabainisha sababu mbili za msingi za uhamaji.'),
(438, 110, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu sababu za uhamaji wa makabila Afrika Mashariki: ukame, ukosefu wa ardhi, vita, magonjwa, kutafuta malisho, biashara.', 'Jadili na uorodheshe sababu za uhamaji wa makabila, ukizingatia mazingira ya Afrika Mashariki.', 'Sababu za uhamaji wa makabila Afrika Mashariki zimebainishwa kwa usahihi.'),
(439, 110, 1, 'design', 10, 'Onyesha ramani ya Afrika Mashariki ukionyesha njia za uhamaji wa makabila makubwa. Vikundi vibainishe sababu za kila uhamaji ulioonyeshwa.', 'Angalia ramani ya uhamaji wa makabila na bainisha sababu za uhamaji ulioonyeshwa.', 'Sababu za uhamaji wa makabila kwenye ramani zimebainishwa kwa usahihi.'),
(440, 110, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe sababu nne za uhamaji wa makabila Afrika Mashariki.', 'Orodhesha sababu nne za uhamaji wa makabila Afrika Mashariki.', 'Sababu nne sahihi za uhamaji wa makabila zimeorodheshwa.'),
(441, 111, 7, 'introduction', 5, 'Uliza: Unafikiri uhamaji wa makabila uliathiri vipi watu waliohama na wale waliokutana nao?', 'Pendekeza athari chanya na hasi za uhamaji wa makabila.', 'Wanafunzi wanabainisha athari moja chanya na moja hasi ya uhamaji.'),
(442, 111, 2, 'development', 20, 'Ongoza vikundi kuchunguza athari za uhamaji: athari chanya (biashara, kubadilishana utamaduni, teknolojia mpya, makazi mapya) na athari hasi (migogoro ya ardhi, vita, magonjwa).', 'Jadili na uorodheshe athari chanya na hasi za uhamaji wa makabila kwa Tanzania.', 'Athari za uhamaji kwa makabila yaliyohamia na yaliyokaribishwa zimebainishwa kwa usahihi.'),
(443, 111, 2, 'design', 10, 'Vikundi viunde jedwali linalolinganisha athari chanya na hasi za uhamaji wa makabila Afrika Mashariki.', 'Unda jedwali la athari chanya na hasi za uhamaji wa makabila.', 'Jedwali sahihi la athari za uhamaji limeundwa.'),
(444, 111, 3, 'realisation', 5, 'Kila mwanafunzi aeleze athari mbili za uhamaji ├óÔé¼ÔÇØ moja chanya na moja hasi.', 'Eleza athari mbili za uhamaji wa makabila ├óÔé¼ÔÇØ moja chanya na moja hasi.', 'Athari mbili sahihi za uhamaji ├óÔé¼ÔÇØ chanya na hasi ├óÔé¼ÔÇØ zimebainishwa.'),
(445, 112, 5, 'introduction', 5, 'Uliza: Makabila yalipokutana, yalishirikiana vipi? Ni nini kinachofanya makabila yaishi pamoja kwa amani?', 'Pendekeza njia ambazo makabila yangeweza kushirikiana.', 'Wanafunzi wanabainisha njia moja ya mwingiliano wa makabila.'),
(446, 112, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu njia za mwingiliano wa makabila: biashara ya kubadilishana, ndoa za mchanganyiko, ushirikiano wa kilimo, kubadilishana lugha na utamaduni.', 'Jadili na uorodheshe njia za mwingiliano wa makabila kibiashara, kijamii na kiutamaduni.', 'Njia za mwingiliano wa makabila zimebainishwa kwa usahihi.'),
(447, 112, 2, 'design', 10, 'Vikundi viunde picha ya makabila mawili yanayoshirikiana ├óÔé¼ÔÇØ vikiorodhesha kila aina ya mwingiliano.', 'Unda picha au mchoro unaoonyesha njia za mwingiliano wa makabila mawili.', 'Njia za mwingiliano wa makabila zinaonyeshwa kwa usahihi katika kazi ya kikundi.'),
(448, 112, 3, 'realisation', 5, 'Kila mwanafunzi aeleze njia tatu za mwingiliano wa makabila na mfano mmoja wa kila njia.', 'Eleza njia tatu za mwingiliano wa makabila na toa mfano mmoja kwa kila njia.', 'Njia tatu za mwingiliano wa makabila zimebainishwa na mifano sahihi imetolewa.'),
(449, 113, 7, 'introduction', 5, 'Uliza: Je, makabila kuishi pamoja na kushirikiana kulifaidisha Tanzania? Ilitoa changamoto gani?', 'Pendekeza faida na changamoto za makabila kuishi pamoja.', 'Wanafunzi wanabainisha faida na changamoto moja ya mwingiliano wa makabila.'),
(450, 113, 2, 'development', 20, 'Ongoza majadiliano tathmini ya athari za mwingiliano wa makabila kwa maendeleo ya Tanzania: kubadilishana maarifa ya kilimo, teknolojia, lugha (Kiswahili), biashara, na migogoro ya ardhi.', 'Jadili na utathmini athari za mwingiliano wa makabila kwa maendeleo ya Tanzania.', 'Athari za mwingiliano wa makabila kwa maendeleo ya Tanzania zimetathminiwa kwa hoja sahihi.'),
(451, 113, 2, 'design', 10, 'Vikundi viunde hoja: Je, mwingiliano wa makabila ulisaidia au kudhuru maendeleo ya Tanzania zaidi?', 'Unda hoja tatu zinazosaidia au kupinga kuwa mwingiliano wa makabila ulichangia maendeleo ya Tanzania.', 'Hoja zenye mantiki kuhusu athari za mwingiliano wa makabila zimeundwa.'),
(452, 113, 3, 'realisation', 5, 'Kila mwanafunzi aeleze athari mbili za mwingiliano wa makabila kwa maendeleo ya Tanzania.', 'Eleza athari mbili za mwingiliano wa makabila kwa maendeleo ya Tanzania.', 'Athari mbili za mwingiliano wa makabila kwa Tanzania zimebainishwa kwa usahihi.'),
(453, 114, 5, 'introduction', 5, 'Uliza: Je, Tanzania iliwahi kuwa na uhusiano na nchi nyingine kabla ya ukoloni? Nchi zipi?', 'Taja nchi au mataifa ambayo Watanzania wanaweza kuwa walikuwa na uhusiano nazo.', 'Wanafunzi wanabainisha mataifa mengi yaliyoweza kuwa na uhusiano na Tanzania.'),
(454, 114, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu asili ya uhusiano wa Tanzania na mataifa mengine: biashara ya pwani na Uarabuni, India, China; uhusiano na makabila ya jirani.', 'Jadili asili na historia ya uhusiano wa Watanzania na mataifa mengine na uandike muhtasari.', 'Asili na historia ya uhusiano wa Watanzania na mataifa mengine imebainishwa kwa usahihi.'),
(455, 114, 1, 'design', 10, 'Onyesha ramani ya biashara ya Bahari ya Hindi ukionyesha njia za biashara. Vikundi vibainishe mataifa yaliyoshiriki.', 'Angalia ramani ya njia za biashara na ubainishe mataifa yaliyoshirikiana na Tanzania kibiashara.', 'Mataifa yaliyoshirikiana na Tanzania kibiashara yamebainishwa kwenye ramani.'),
(456, 114, 3, 'realisation', 5, 'Kila mwanafunzi abainishe njia tatu za uhusiano wa Tanzania na mataifa mengine.', 'Bainisha njia tatu ambazo Tanzania iliungana na mataifa mengine kabla ya ukoloni.', 'Njia tatu sahihi za uhusiano wa Tanzania na mataifa mengine zimebainishwa.'),
(457, 115, 2, 'introduction', 5, 'Uliza: Biashara, ndoa na vita ├óÔé¼ÔÇØ jinsi gani hizi zote ni aina za uhusiano kati ya watu au mataifa?', 'Eleza jinsi biashara, ndoa na vita vinavyoweza kuunganisha au kugawanya watu.', 'Wanafunzi wanabainisha njia tatu za msingi za uhusiano.'),
(458, 115, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kubainisha na kueleza njia za uhusiano: biashara (mali na bidhaa), ndoa za mchanganyiko (uhusiano wa kimwili na kijamii), vita na mapatano ya amani.', 'Jadili na ubainishe mifano ya kila njia ya uhusiano kutoka historia ya Tanzania.', 'Njia mbalimbali za uhusiano wa Kitanzania na mataifa mengine zimebainishwa kwa mifano.'),
(459, 115, 10, 'design', 10, 'Mchezo wa kuigiza: Kikundi kimoja kiigize mazungumzo ya biashara kati ya mfanyabiashara wa Tanzania na wa Uarabuni wa karne ya kumi na mbili.', 'Igiza mazungumzo ya biashara ya zamani kati ya Tanzania na mataifa mengine.', 'Uhusiano wa kibiashara unaigizwa kwa usahihi ukionyesha aina za bidhaa na namna ya kufanya biashara.'),
(460, 115, 3, 'realisation', 5, 'Kila mwanafunzi aorodheshe njia tatu za uhusiano wa Tanzania na mataifa na atoe mfano mmoja wa kila njia.', 'Orodhesha njia tatu na toa mfano mmoja wa kila njia ya uhusiano.', 'Njia tatu na mifano sahihi ya uhusiano wa Tanzania na mataifa imebainishwa.'),
(461, 116, 3, 'introduction', 5, 'Uliza: Wazungu walikuja Tanzania wakati gani wa kwanza? Waliingiaje nchini?', 'Toa mawazo yao kuhusu ujio wa kwanza wa Wazungu Tanzania.', 'Wanafunzi wanabainisha kipindi cha awali cha Wazungu Tanzania.'),
(462, 116, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu uhusiano wa awali wa Watanzania na Wazungu: biashara ya pwani, utafiti wa kijiografia, misheni ya kidini, kabla ya ukoloni rasmi.', 'Jadili uhusiano wa awali wa Watanzania na Wazungu na andika muhtasari.', 'Uhusiano wa awali wa Watanzania na Wazungu kabla ya ukoloni umebainishwa kwa usahihi.'),
(463, 116, 1, 'design', 10, 'Onyesha ramani ya njia za wasafiri wa Ulaya Afrika Mashariki. Vikundi vibainishe maeneo waliyofika.', 'Angalia ramani na ubainishe maeneo ya Tanzania yaliyofikiwa na wasafiri wa Ulaya.', 'Njia za wasafiri wa Ulaya Afrika Mashariki zimebainishwa kwa usahihi.'),
(464, 116, 3, 'realisation', 5, 'Eleza kwa sentensi mbili asili ya uhusiano wa kwanza wa Watanzania na Wazungu.', 'Andika sentensi mbili kuhusu asili ya uhusiano wa kwanza wa Watanzania na Wazungu.', 'Uhusiano wa awali wa Watanzania na Wazungu umebainishwa kwa usahihi.'),
(465, 117, 2, 'introduction', 5, 'Uliza: Uhusiano na Wazungu ulifaidisha Tanzania? Ulidhuru Tanzania? Jinsi gani?', 'Pendekeza faida na hasara za uhusiano wa Watanzania na Wazungu.', 'Wanafunzi wanabainisha faida na hasara moja ya uhusiano.'),
(466, 117, 2, 'development', 20, 'Ongoza majadiliano tathmini ya athari za kiuchumi (biashara, rasilimali) na kijamii (dini, elimu) za uhusiano na Wazungu.', 'Jadili na utathmini athari za kiuchumi na kijamii za uhusiano wa Watanzania na Wazungu.', 'Athari za kiuchumi na kijamii za uhusiano na Wazungu zimetathminiwa kwa usahihi.'),
(467, 117, 2, 'design', 10, 'Vikundi viunde jedwali la athari chanya na hasi za uhusiano na Wazungu kiuchumi na kijamii.', 'Unda jedwali la athari chanya na hasi za uhusiano na Wazungu.', 'Jedwali sahihi la athari za uhusiano na Wazungu limeundwa.'),
(468, 117, 3, 'realisation', 5, 'Eleza athari mbili za kiuchumi na athari mbili za kijamii za uhusiano na Wazungu.', 'Eleza athari mbili za kiuchumi na mbili za kijamii za uhusiano wa Tanzania na Wazungu.', 'Athari za kiuchumi na kijamii za uhusiano na Wazungu zimebainishwa kwa usahihi.'),
(469, 118, 5, 'introduction', 5, 'Uliza: Waarabu waliingia Tanzania lini? Walitoka wapi? Walikuwa wanafanya nini?', 'Toa mawazo ya awali kuhusu ujio wa Waarabu Tanzania.', 'Wanafunzi wanabainisha maarifa yao ya awali kuhusu Waarabu Tanzania.'),
(470, 118, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu biashara ya pwani ya Waarabu: bidhaa za biashara (ivory, dhahabu, nguo, viungo), miji ya pwani (Kilwa, Mombasa, Zanzibar), na mfumo wa biashara.', 'Jadili biashara ya pwani ya Waarabu na Tanzania na uandike bidhaa zilizobinafsishwa na miji iliyohusika.', 'Uhusiano wa biashara kati ya Tanzania na Waarabu umebainishwa kwa usahihi.'),
(471, 118, 1, 'design', 10, 'Onyesha ramani ya njia za biashara za Waarabu pwani ya Afrika Mashariki. Vikundi vibainishe bandari na mji zilizohusika.', 'Angalia ramani na ubainishe bandari na miji ya biashara ya Waarabu pwani ya Tanzania.', 'Njia za biashara za Waarabu pwani ya Afrika Mashariki zimebainishwa kwa usahihi.'),
(472, 118, 3, 'realisation', 5, 'Eleza kwa sentensi mbili bidhaa kuu mbili zilizobinafsishwa na Waarabu Tanzania.', 'Eleza bidhaa kuu mbili zilizobinafsishwa na Waarabu Tanzania.', 'Bidhaa kuu za biashara ya Waarabu Tanzania zimebainishwa kwa usahihi.'),
(473, 119, 7, 'introduction', 5, 'Onyesha picha au elezea biashara ya watumwa. Uliza: Biashara hii iliathiri vipi Watanzania?', 'Eleza hisia zao kuhusu biashara ya watumwa na athari zake.', 'Wanafunzi wanaonyesha ufahamu wa msingi wa athari za biashara ya watumwa.'),
(474, 119, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu athari za biashara ya watumwa na ya ivory: idadi ya watu ilipungua, familia zilifarakana, mifumo ya kijamii ilibomolewa, uchumi uliathirika.', 'Jadili athari za biashara ya watumwa na bidhaa nyingine kwa Tanzania.', 'Athari za biashara ya watumwa na bidhaa kwa Tanzania zimebainishwa kwa usahihi.'),
(475, 119, 2, 'design', 10, 'Vikundi viunde hoja mbili kwa na mbili dhidi ya: \"Biashara ya Waarabu ilinufaisha Tanzania zaidi kuliko kuidhuru\".', 'Unda hoja kwa na dhidi ya biashara ya Waarabu Tanzania.', 'Hoja zenye mantiki kwa na dhidi ya biashara ya Waarabu Tanzania zimeundwa.'),
(476, 119, 3, 'realisation', 5, 'Eleza athari mbili za biashara ya watumwa kwa Tanzania.', 'Eleza athari mbili za biashara ya watumwa kwa jamii za Kitanzania.', 'Athari mbili sahihi za biashara ya watumwa zimebainishwa.'),
(477, 120, 5, 'introduction', 5, 'Uliza: Watu wengi wa Tanzania wanaomba Mungu leo. Hii ilianza lini? Kutoka wapi?', 'Toa mawazo yao kuhusu asili ya dini Tanzania.', 'Wanafunzi wanabainisha asili ya dini kuu Tanzania.'),
(478, 120, 2, 'development', 20, 'Ongoza majadiliano kuhusu athari za kidini za uhusiano na Waarabu (uenezi wa Uislamu, misikiti, madrasas) na athari za kiutamaduni (lugha ├óÔé¼ÔÇØ Kiswahili ilikopwa maneno ya Kiarabu, mavazi, sanaa).', 'Jadili athari za kidini na kiutamaduni za uhusiano na Waarabu kwa Tanzania.', 'Athari za kidini na kiutamaduni za uhusiano na Waarabu zimebainishwa kwa usahihi.'),
(479, 120, 2, 'design', 10, 'Vikundi vibainishe maneno ya Kiarabu yanayotumiwa katika Kiswahili na bidhaa za utamaduni wa Kiarabu zinazoonekana Tanzania.', 'Orodhesha maneno 5 ya Kiarabu katika Kiswahili na bidhaa 3 za utamaduni wa Kiarabu Tanzania.', 'Maneno ya Kiarabu katika Kiswahili na athari za utamaduni wa Kiarabu zimebainishwa.'),
(480, 120, 3, 'realisation', 5, 'Eleza athari mbili za kidini na athari mbili za kiutamaduni za uhusiano na Waarabu.', 'Eleza athari mbili za kidini na mbili za kiutamaduni za uhusiano na Waarabu Tanzania.', 'Athari za kidini na kiutamaduni za uhusiano na Waarabu zimebainishwa.'),
(481, 121, 2, 'introduction', 5, 'Uliza: Uhusiano wa Tanzania na mataifa mengine kabla ya ukoloni ulifaidisha Tanzania kwa njia gani?', 'Toa faida wanazofikiria zilizotokana na uhusiano wa Tanzania na mataifa.', 'Wanafunzi wanabainisha faida moja ya uhusiano wa nje.'),
(482, 121, 2, 'development', 20, 'Ongoza majadiliano kuhusu athari chanya: biashara iliongeza utajiri, uenezi wa teknolojia mpya, maendeleo ya miji ya pwani, kubadilishana utamaduni na lugha, uenezi wa elimu.', 'Jadili na uorodheshe athari chanya za uhusiano wa Tanzania na mataifa kabla ya ukoloni.', 'Athari chanya za uhusiano wa Tanzania na mataifa mengine zimebainishwa kwa usahihi.'),
(483, 121, 2, 'design', 10, 'Vikundi viunde mchoro unaoonyesha jinsi biashara na uhusiano na mataifa mengine ulifaidisha Tanzania.', 'Unda mchoro unaoonesha athari chanya za uhusiano wa Tanzania na mataifa mengine.', 'Mchoro sahihi wa athari chanya za uhusiano wa Tanzania na nje umeundwa.'),
(484, 121, 3, 'realisation', 5, 'Orodhesha athari chanya tatu za uhusiano wa Tanzania na mataifa mengine.', 'Orodhesha athari chanya tatu za uhusiano wa Tanzania na mataifa mengine kabla ya ukoloni.', 'Athari chanya tatu sahihi za uhusiano wa Tanzania na nje zimeorodheshwa.'),
(485, 122, 7, 'introduction', 5, 'Uliza: Uhusiano na mataifa mengine pia ulileta matatizo kwa Tanzania. Matatizo gani?', 'Toa matatizo wanayofikiria yalitokana na uhusiano na mataifa mengine.', 'Wanafunzi wanabainisha tatizo moja la uhusiano na mataifa mengine.'),
(486, 122, 2, 'development', 20, 'Ongoza majadiliano kuhusu athari hasi: biashara ya watumwa (kupoteza watu), unyonyaji wa rasilimali, kupotea kwa uhuru, utegemezi wa kiuchumi, vita vilivyosababishwa na ushindani wa biashara.', 'Jadili na uorodheshe athari hasi za uhusiano wa Tanzania na mataifa mengine kabla ya ukoloni.', 'Athari hasi za uhusiano wa Tanzania na mataifa mengine zimebainishwa kwa usahihi.'),
(487, 122, 2, 'design', 10, 'Vikundi vitathmini: Athari chanya au hasi za uhusiano na mataifa mengine zilikuwa kubwa zaidi kwa Tanzania?', 'Jadili na uamue kwa hoja kama athari chanya au hasi zilikuwa kubwa zaidi.', 'Tathmini yenye hoja za uhusiano wa Tanzania na mataifa mengine imewasilishwa.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(488, 122, 3, 'realisation', 5, 'Eleza athari hasi mbili za uhusiano wa Tanzania na mataifa mengine kabla ya ukoloni.', 'Eleza athari hasi mbili za uhusiano wa Tanzania na mataifa kabla ya ukoloni.', 'Athari hasi mbili sahihi za uhusiano wa Tanzania na mataifa zimebainishwa.'),
(489, 123, 5, 'introduction', 5, 'Uliza: Kwa nini Wazungu walikuja Afrika kwa wingi katika karne ya 19? Ni nini kiliwavutia?', 'Toa mawazo yao kuhusu sababu za Wazungu kuja Afrika.', 'Wanafunzi wanabainisha angalau sababu moja ya kiuchumi ya Wazungu kuja Afrika.'),
(490, 123, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu sababu za kiuchumi za ujio wa ukoloni: kutafuta masoko mapya, rasilimali ghafi, ardhi kwa ukulima na biashara, mapinduzi ya viwanda yaliyohitaji malighafi.', 'Jadili na uorodheshe sababu za kiuchumi zilizopelekea Wazungu kuja Afrika.', 'Sababu za kiuchumi za ujio wa Wazungu Afrika zimebainishwa kwa usahihi.'),
(491, 123, 1, 'design', 10, 'Onyesha ramani ya Afrika ikionyesha mgawanyo wa Ulaya (Mkutano wa Berlin 1884-85). Vikundi vitathmini sababu za kiuchumi za mgawanyo huo.', 'Angalia ramani ya mgawanyo wa Afrika na ubainishe sababu za kiuchumi za mgawanyo huo.', 'Sababu za kiuchumi za mgawanyo wa Afrika zimebainishwa kwa usahihi kutoka kwa ramani.'),
(492, 123, 3, 'realisation', 5, 'Orodhesha sababu tatu za kiuchumi zilizopelekea Wazungu kuja Afrika.', 'Orodhesha sababu tatu za kiuchumi za Wazungu kuja Afrika.', 'Sababu tatu sahihi za kiuchumi za ujio wa Wazungu Afrika zimeorodheshwa.'),
(493, 124, 2, 'introduction', 5, 'Uliza: Sababu za kisiasa, kidini na kijamii pia ziliwasukuma Wazungu Afrika. Ni zipi?', 'Pendekeza sababu za kisiasa, kidini na kijamii za ujio wa Wazungu Afrika.', 'Wanafunzi wanabainisha sababu moja isiyo ya kiuchumi.'),
(494, 124, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu sababu za kisiasa (kushindana kwa nguvu za Ulaya), kidini (kueneza Ukristo) na kijamii (kuhamasika kwa utamaduni wa Ulaya, kubeba \"mzigo wa mzungu\").', 'Jadili na uorodheshe sababu za kisiasa, kidini na kijamii za ujio wa wakoloni Afrika.', 'Sababu za kisiasa, kidini na kijamii za ujio wa wakoloni zimebainishwa kwa usahihi.'),
(495, 124, 2, 'design', 10, 'Vikundi viainishe sababu za ujio wa wakoloni katika makundi matatu: kiuchumi, kisiasa, na kijamii/kidini.', 'Ainisha sababu za ujio wa wakoloni katika makundi ya kiuchumi, kisiasa, na kijamii/kidini.', 'Sababu za ujio wa wakoloni zimeainishwa kwa usahihi katika makundi sahihi.'),
(496, 124, 3, 'realisation', 5, 'Eleza sababu mbili zisizo za kiuchumi za Wazungu kuja Afrika.', 'Eleza sababu mbili zisizo za kiuchumi zilizopelekea Wazungu kuja Afrika.', 'Sababu mbili sahihi zisizo za kiuchumi za ujio wa wakoloni zimebainishwa.'),
(497, 125, 2, 'introduction', 5, 'Uliza: Watu wa Tanzania walikaa kimya tu wakati Wazungu walikuja? Au walipigana dhidi yao?', 'Toa mawazo kuhusu jinsi Watanzania wangeweza kupinga ukoloni.', 'Wanafunzi wanabainisha njia moja ya upinzani dhidi ya ukoloni.'),
(498, 125, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu njia za upinzani: silaha (vita vya Majimaji, vita vya Hehe), diplomasia (mazungumzo, mapatano), upinzani wa amani (wagomaji, vikundi vya kisiasa).', 'Jadili na uorodheshe njia mbalimbali za upinzani dhidi ya wakoloni Tanzania.', 'Njia mbalimbali za upinzani dhidi ya wakoloni zimebainishwa kwa usahihi.'),
(499, 125, 2, 'design', 10, 'Vikundi vilinganishe mbinu za upinzani kwa silaha na kwa diplomasia ├óÔé¼ÔÇØ ipi ilikuwa na mafanikio zaidi?', 'Linganisha upinzani wa silaha na wa kidiplomasia ├óÔé¼ÔÇØ ipi ilifanikiwa zaidi na kwa nini?', 'Njia za upinzani zimlinganishwa kwa hoja sahihi.'),
(500, 125, 3, 'realisation', 5, 'Eleza njia tatu za upinzani dhidi ya ukoloni Tanzania.', 'Eleza njia tatu za upinzani wa Watanzania dhidi ya ukoloni.', 'Njia tatu sahihi za upinzani dhidi ya ukoloni zimebainishwa.'),
(501, 126, 7, 'introduction', 5, 'Uliza: Upinzani dhidi ya ukoloni Tanzania ulifanikiwa? Ulikuwa na mapungufu gani?', 'Toa mawazo yao kuhusu mafanikio na mapungufu ya upinzani dhidi ya ukoloni.', 'Wanafunzi wanaeleza mafanikio moja na upungufu mmoja wa upinzani.'),
(502, 126, 2, 'development', 20, 'Ongoza majadiliano tathmini ya mafanikio (kujenga umoja wa kitaifa, kuonyesha nguvu, kuchangia uhuru wa baadaye) na mapungufu (kutofanya kazi pamoja, silaha duni, kushindwa kijeshi).', 'Jadili na utathmini mafanikio na mapungufu ya upinzani wa Watanzania dhidi ya ukoloni.', 'Mafanikio na mapungufu ya upinzani dhidi ya ukoloni vimetathminiwa kwa usahihi.'),
(503, 126, 2, 'design', 10, 'Vikundi viundee hoja mbili kwa upande: \"Upinzani dhidi ya ukoloni Tanzania ulifanikiwa\" na mbili dhidi yake.', 'Unda hoja kwa upande na dhidi ya mafanikio ya upinzani dhidi ya ukoloni Tanzania.', 'Hoja zenye mantiki kuhusu mafanikio ya upinzani zimeundwa.'),
(504, 126, 3, 'realisation', 5, 'Eleza mafanikio mawili na mapungufu mawili ya upinzani dhidi ya ukoloni Tanzania.', 'Eleza mafanikio mawili na mapungufu mawili ya upinzani dhidi ya ukoloni Tanzania.', 'Mafanikio mawili na mapungufu mawili ya upinzani yamebainishwa kwa usahihi.'),
(505, 127, 7, 'introduction', 5, 'Uliza: Mnasikia nini kuhusu Vita vya Majimaji? Vilianza lini? Vilisababishwa na nini?', 'Toa maarifa yao ya awali kuhusu Vita vya Majimaji.', 'Wanafunzi wanaonyesha maarifa yao ya awali kuhusu Vita vya Majimaji.'),
(506, 127, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu Vita vya Majimaji 1905-1907: sababu (kulazimishwa kufanya kazi, ushuru wa bidhaa, imani ya maji ya kinga), mwenendo wa vita, matokeo (kushindwa kwa Wajerumani kidogo, kupotea kwa watu wengi, ukame).', 'Jadili sababu, mwenendo na matokeo ya Vita vya Majimaji na uandike muhtasari.', 'Sababu, mwenendo na matokeo ya Vita vya Majimaji yamebainishwa kwa usahihi.'),
(507, 127, 1, 'design', 10, 'Onyesha ramani ya Tanzania ukionyesha maeneo ya Vita vya Majimaji. Vikundi vibainishe maeneo na matukio makuu.', 'Angalia ramani na ubainishe maeneo ya Tanzania yaliyohusika na Vita vya Majimaji.', 'Maeneo ya Vita vya Majimaji yamebainishwa kwa usahihi kwenye ramani.'),
(508, 127, 3, 'realisation', 5, 'Eleza sababu mbili na matokeo mawili ya Vita vya Majimaji.', 'Eleza sababu mbili na matokeo mawili ya Vita vya Majimaji 1905-1907.', 'Sababu mbili na matokeo mawili ya Vita vya Majimaji yamebainishwa kwa usahihi.'),
(509, 128, 2, 'introduction', 5, 'Uliza: Vita vya Majimaji viliishia kushindwa. Bado vina umuhimu gani katika historia ya Tanzania?', 'Pendekeza kwa nini Vita vya Majimaji vinazingatiwa muhimu licha ya kushindwa.', 'Wanafunzi wanabainisha umuhimu wa awali wa Vita vya Majimaji.'),
(510, 128, 2, 'development', 20, 'Ongoza majadiliano kuhusu umuhimu wa Vita vya Majimaji: mfano wa umoja wa kikabila, kichocheo cha harakati za uhuru, kuonyesha ujasiri wa Watanzania, somo la historia kwa vizazi.', 'Jadili na uorodheshe umuhimu wa Vita vya Majimaji katika historia ya Tanzania.', 'Umuhimu wa Vita vya Majimaji katika historia ya Tanzania umebainishwa kwa usahihi.'),
(511, 128, 2, 'design', 10, 'Vikundi viandike hotuba fupi kutoka mtazamo wa kiongozi wa Vita vya Majimaji, wakieleza kwa nini wanajitoa kupigana.', 'Andika hotuba fupi kutoka mtazamo wa kiongozi wa Vita vya Majimaji.', 'Hotuba inayoonyesha ufahamu wa umuhimu wa Vita vya Majimaji imeandikwa.'),
(512, 128, 3, 'realisation', 5, 'Eleza umuhimu wa Vita vya Majimaji katika historia ya Tanzania kwa sentensi tatu.', 'Eleza umuhimu wa Vita vya Majimaji katika sentensi tatu.', 'Umuhimu wa Vita vya Majimaji umebainishwa kwa usahihi.'),
(513, 129, 5, 'introduction', 5, 'Uliza: Wajerumani walianzishaje utawala Tanzania? Je, walikuwa rafiki au wakali?', 'Toa mawazo ya awali kuhusu jinsi Wajerumani walianzisha utawala Tanzania.', 'Wanafunzi wanabainisha maarifa yao ya awali kuhusu utawala wa Kijerumani.'),
(514, 129, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu jinsi Wajerumani walianzisha utawala Tanzania: kutumia nguvu, mfumo wa Akida na Jumbe, sera za ushuru, kulazimisha kazi.', 'Jadili jinsi Wajerumani walianzisha na kusimamia utawala Tanzania na uandike muhtasari.', 'Jinsi Wajerumani walivyoanzisha utawala Tanzania imebainishwa kwa usahihi.'),
(515, 129, 1, 'design', 10, 'Onyesha picha za vituo vya Kijerumani Tanzania na mfumo wa utawala. Vikundi vibainishe sifa za utawala wa Kijerumani.', 'Angalia picha za vituo vya Kijerumani na ubainishe sifa za utawala wao Tanzania.', 'Sifa za utawala wa Kijerumani Tanzania zimebainishwa kwa usahihi.'),
(516, 129, 3, 'realisation', 5, 'Eleza jinsi Wajerumani walivyoanzisha utawala Tanzania kwa hatua tatu.', 'Eleza jinsi Wajerumani walianzisha utawala Tanzania kwa hatua tatu.', 'Jinsi Wajerumani walianzisha utawala Tanzania imebainishwa kwa hatua sahihi.'),
(517, 130, 2, 'introduction', 5, 'Uliza: Ukoloni wa Kijerumani uliathiri vipi uchumi na jamii ya Tanzania?', 'Pendekeza mabadiliko ya kiuchumi na kijamii yaliyotokea chini ya Wajerumani.', 'Wanafunzi wanabainisha mabadiliko mawili ya kiuchumi au kijamii.'),
(518, 130, 2, 'development', 20, 'Ongoza majadiliano kuhusu mabadiliko ya kiuchumi (kilimo cha biashara ├óÔé¼ÔÇØ kahawa, pamba, sisal; reli, miundombinu) na kijamii (mfumo wa elimu, dini, utawala wa matendo).', 'Jadili mabadiliko ya kiuchumi na kijamii chini ya utawala wa Kijerumani Tanzania.', 'Mabadiliko ya kiuchumi na kijamii chini ya Wajerumani yamebainishwa kwa usahihi.'),
(519, 130, 2, 'design', 10, 'Vikundi viunde jedwali la mabadiliko ya kiuchumi na kijamii chini ya Wajerumani ├óÔé¼ÔÇØ chanya na hasi.', 'Unda jedwali la mabadiliko ya kiuchumi na kijamii chini ya Wajerumani ├óÔé¼ÔÇØ chanya na hasi.', 'Jedwali sahihi la mabadiliko chini ya Wajerumani limeundwa.'),
(520, 130, 3, 'realisation', 5, 'Eleza mabadiliko mawili ya kiuchumi na mawili ya kijamii yaliyotokea chini ya Wajerumani Tanzania.', 'Eleza mabadiliko mawili ya kiuchumi na mawili ya kijamii chini ya utawala wa Kijerumani.', 'Mabadiliko manne sahihi chini ya Wajerumani yamebainishwa.'),
(521, 131, 3, 'introduction', 5, 'Uliza: Waingereza walichukua Tanzania lini na vipi? Baada ya tukio gani?', 'Toa maarifa yao kuhusu jinsi Waingereza walivyochukua Tanzania.', 'Wanafunzi wanabainisha tukio lililofanya Waingereza wachukue Tanzania.'),
(522, 131, 2, 'development', 20, 'Ongoza majadiliano kuhusu jinsi Waingereza walichukua Tanzania baada ya Vita Kuu ya Kwanza (1919) kupitia Amri ya Ligi ya Mataifa: Mandate territory, later Trusteeship.', 'Jadili jinsi Waingereza walichukua Tanzania na msingi wa kisheria wa utawala wao.', 'Jinsi Waingereza walichukua Tanzania baada ya Vita Kuu ya Kwanza imebainishwa kwa usahihi.'),
(523, 131, 2, 'design', 10, 'Vikundi vilinganishe njia Waingereza waliingia Tanzania na njia Wajerumani waliingia ├óÔé¼ÔÇØ tofauti na mfanano.', 'Linganisha njia Waingereza na Wajerumani waliingia Tanzania.', 'Tofauti na mfanano wa jinsi Waingereza na Wajerumani waliingia Tanzania zimebainishwa.'),
(524, 131, 3, 'realisation', 5, 'Eleza jinsi Waingereza walivyochukua utawala wa Tanzania baada ya Vita Kuu ya Kwanza.', 'Eleza jinsi Waingereza walivyochukua utawala wa Tanzania kwa hatua mbili.', 'Jinsi Waingereza walichukua Tanzania imebainishwa kwa usahihi.'),
(525, 132, 2, 'introduction', 5, 'Uliza: Waingereza walisimamia Tanzania tofauti na Wajerumani? Walitumia sera gani?', 'Pendekeza tofauti za sera kati ya Waingereza na Wajerumani Tanzania.', 'Wanafunzi wanabainisha tofauti moja ya sera kati ya Waingereza na Wajerumani.'),
(526, 132, 2, 'development', 20, 'Ongoza majadiliano kuhusu sera za Waingereza: Utawala wa Wasimamizi wa Kiasili (Indirect Rule), ushuru wa kura, kilimo cha biashara, elimu ya msingi kwa Waafrika.', 'Jadili sera za kiuchumi na kisiasa za Waingereza Tanzania na athari zake.', 'Sera za kiuchumi na kisiasa za Waingereza Tanzania zimebainishwa kwa usahihi.'),
(527, 132, 2, 'design', 10, 'Vikundi viunde jedwali linalolinganisha sera za Wajerumani na Waingereza Tanzania.', 'Unda jedwali linalolinganisha sera za Wajerumani na Waingereza Tanzania.', 'Jedwali sahihi linalolinganisha sera za mamlaka mbili za kikoloni limeundwa.'),
(528, 132, 3, 'realisation', 5, 'Eleza sera mbili za kiuchumi na mbili za kisiasa za Waingereza Tanzania.', 'Eleza sera mbili za kiuchumi na mbili za kisiasa za Waingereza Tanzania.', 'Sera nne sahihi za Waingereza Tanzania zimebainishwa.'),
(529, 133, 2, 'introduction', 5, 'Uliza: Utawala wa Waingereza uliathiri vipi maisha ya Watanzania wa kawaida?', 'Pendekeza athari za utawala wa Waingereza kwa Watanzania.', 'Wanafunzi wanabainisha athari moja ya utawala wa Waingereza.'),
(530, 133, 2, 'development', 20, 'Ongoza majadiliano tathmini ya athari za Waingereza: athari chanya (elimu, afya, miundombinu) na hasi (ubaguzi wa rangi, ulipuaji ardhi, kuharibu utamaduni, ushuru mkubwa).', 'Jadili na utathmini athari za utawala wa Kiingereza kwa Watanzania.', 'Athari za utawala wa Kiingereza kwa Watanzania zimetathminiwa kwa usahihi.'),
(531, 133, 2, 'design', 10, 'Vikundi vitathmini: Utawala wa Kiingereza ulisaidia au kudhuru Tanzania zaidi?', 'Tathmini kwa hoja kama utawala wa Kiingereza ulisaidia au kudhuru Tanzania zaidi.', 'Tathmini yenye hoja ya utawala wa Kiingereza kwa Tanzania imewasilishwa.'),
(532, 133, 3, 'realisation', 5, 'Eleza athari mbili chanya na mbili hasi za utawala wa Kiingereza kwa Watanzania.', 'Eleza athari mbili chanya na mbili hasi za utawala wa Kiingereza Tanzania.', 'Athari nne sahihi za utawala wa Kiingereza zimebainishwa.'),
(533, 134, 5, 'introduction', 5, 'Uliza: Mnajua chama cha TANU? Kilianzishwa lini? Na nani? Kwa kusudi gani?', 'Toa maarifa yao ya awali kuhusu TANU na lengo lake.', 'Wanafunzi wanabainisha maarifa ya awali kuhusu TANU.'),
(534, 134, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu historia ya TANU (Tanganyika African National Union): kuanzishwa 1954 na Julius Nyerere, malengo ya kupigania uhuru, mikakati yake ya amani.', 'Jadili historia ya TANU na jukumu lake katika kupigania uhuru wa Tanzania.', 'Historia ya TANU na jukumu lake katika harakati za uhuru zimebainishwa kwa usahihi.'),
(535, 134, 1, 'design', 10, 'Onyesha picha za mikutano ya TANU na kiongozi wake. Vikundi vibainishe mkakati wa TANU wa kupata uhuru.', 'Angalia picha za TANU na ubainishe mikakati ya TANU ya kupata uhuru.', 'Mikakati ya TANU ya kupigania uhuru imebainishwa kwa usahihi.'),
(536, 134, 3, 'realisation', 5, 'Eleza historia ya TANU na jukumu lake kuu katika kupigania uhuru wa Tanzania.', 'Eleza historia ya TANU na jukumu lake kuu moja katika kupigania uhuru.', 'Historia ya TANU na jukumu lake katika kupigania uhuru zimebainishwa kwa usahihi.'),
(537, 135, 1, 'introduction', 5, 'Onyesha picha ya Julius Nyerere. Uliza: Mnajua mtu huyu? Alitoa mchango gani kwa Tanzania?', 'Toa maarifa yao kuhusu Julius Nyerere na mchango wake.', 'Wanafunzi wanabainisha maarifa ya awali kuhusu Julius Nyerere.'),
(538, 135, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu jukumu la Julius Nyerere: kuanzisha TANU, kuzungumza Umoja wa Mataifa, kueneza elimu ya kisiasa, kutumia mbinu za amani, kupata uhuru 1961.', 'Jadili jukumu la Julius Nyerere katika harakati za uhuru Tanzania.', 'Jukumu la Julius Nyerere katika harakati za uhuru Tanzania limebainishwa kwa usahihi.'),
(539, 135, 2, 'design', 10, 'Vikundi viandike wasifu mfupi wa Julius Nyerere ukionyesha michango yake kwa Tanzania.', 'Andika wasifu mfupi wa Julius Nyerere ukionyesha michango yake mitatu katika kupigania uhuru.', 'Wasifu wenye michango sahihi ya Julius Nyerere umeandikwa.'),
(540, 135, 3, 'realisation', 5, 'Eleza michango mitatu ya Julius Nyerere katika kupigania uhuru wa Tanzania.', 'Eleza michango mitatu ya Julius Nyerere katika harakati za uhuru wa Tanzania.', 'Michango mitatu sahihi ya Julius Nyerere katika harakati za uhuru imebainishwa.'),
(541, 136, 5, 'introduction', 5, 'Uliza: Sayamsi na teknolojia ni nini? Je, watu wa Africa ya zamani walikuwa na teknolojia?', 'Toa mawazo yao kuhusu maana ya sayamsi na teknolojia na mifano kutoka Afrika.', 'Wanafunzi wanabainisha maarifa ya awali kuhusu sayamsi na teknolojia.'),
(542, 136, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu maana ya sayamsi (utafiti wa ulimwengu kwa mbinu za utaratibu) na teknolojia (matumizi ya maarifa ya kisayansi kutengeneza zana na kutatua matatizo) katika muktadha wa historia.', 'Jadili maana ya sayamsi na teknolojia katika muktadha wa historia na toa mifano ya Afrika.', 'Maana ya sayamsi na teknolojia katika muktadha wa historia imebainishwa kwa usahihi.'),
(543, 136, 2, 'design', 10, 'Vikundi vibainishe mifano ya sayamsi na teknolojia ya Afrika iliyokuwepo kabla ya ukoloni.', 'Bainisha mifano mitatu ya sayamsi na teknolojia ya Afrika kabla ya ukoloni.', 'Mifano sahihi ya sayamsi na teknolojia ya Afrika kabla ya ukoloni imebainishwa.'),
(544, 136, 3, 'realisation', 5, 'Eleza maana ya sayamsi na teknolojia kwa maneno yako mwenyewe.', 'Eleza maana ya sayamsi na teknolojia kwa sentensi mbili.', 'Maana ya sayamsi na teknolojia imebainishwa kwa usahihi.'),
(545, 137, 2, 'introduction', 5, 'Uliza: Sayamsi na teknolojia zinahusiana vipi na maendeleo ya jamii? Bila teknolojia ungekuwa ukiishi vipi?', 'Jadili jinsi teknolojia inavyoathiri maisha ya kila siku.', 'Wanafunzi wanabainisha uhusiano wa msingi kati ya teknolojia na maisha.'),
(546, 137, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu uhusiano kati ya sayamsi, teknolojia na maendeleo ya jamii: sayamsi hufanya uvumbuzi ├óÔÇáÔÇÖ teknolojia huitumia ├óÔÇáÔÇÖ jamii inafaidika.', 'Jadili uhusiano kati ya sayamsi, teknolojia na maendeleo ya jamii na toa mifano kutoka historia.', 'Uhusiano kati ya sayamsi, teknolojia na maendeleo ya jamii umebainishwa kwa usahihi.'),
(547, 137, 4, 'design', 10, 'Vikundi viunde mchoro unaoonesha uhusiano wa sayamsi ├óÔÇáÔÇÖ teknolojia ├óÔÇáÔÇÖ maendeleo ya jamii na wape mifano halisi.', 'Unda mchoro unaoonesha uhusiano wa sayamsi, teknolojia na maendeleo ya jamii.', 'Mchoro sahihi wa uhusiano wa sayamsi, teknolojia na maendeleo umeundwa.'),
(548, 137, 3, 'realisation', 5, 'Eleza kwa mfano mmoja jinsi sayamsi na teknolojia vilivyosaidia maendeleo ya jamii za Afrika za zamani.', 'Eleza kwa mfano mmoja jinsi sayamsi na teknolojia vilisaidia jamii za Afrika za zamani.', 'Mfano sahihi wa uhusiano wa sayamsi, teknolojia na maendeleo ya jamii umebainishwa.'),
(549, 138, 1, 'introduction', 5, 'Onyesha picha za zana za mawe za Zama za Mawe za Kale. Uliza: Hizi zilitengenezwaje na zilitumika kwa nini?', 'Angalia picha na pendekeza jinsi zana hizo zilivyotengenezwa na kutumika.', 'Wanafunzi wanabainisha zana za mawe na matumizi yake ya msingi.'),
(550, 138, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu aina za zana za Zama za Mawe za Kale: vijembe vya mawe (hand axes), visu, nguruwe za mawe ├óÔé¼ÔÇØ jinsi zilivyotengenezwa kwa kupigapiga mawe.', 'Jadili aina za zana za Zama za Mawe, jinsi zilivyotengenezwa na kila zana ilitumika kwa nini.', 'Aina za zana za Zama za Mawe za Kale zimebainishwa na kuelezwa jinsi zilivyotengenezwa.'),
(551, 138, 4, 'design', 10, 'Vikundi vichoree zana tatu za Zama za Mawe za Kale na vieleze jinsi zilivyotengenezwa na kutumika.', 'Chora zana tatu za Zama za Mawe za Kale na eleza jinsi zilivyotengenezwa na kutumika.', 'Zana tatu za Zama za Mawe zimechorwa na kuelezwa kwa usahihi.'),
(552, 138, 3, 'realisation', 5, 'Orodhesha zana tatu za Zama za Mawe za Kale na eleza matumizi ya kila moja.', 'Orodhesha zana tatu za Zama za Mawe za Kale na eleza matumizi ya kila zana.', 'Zana tatu za Zama za Mawe na matumizi yake zimebainishwa kwa usahihi.'),
(553, 139, 3, 'introduction', 5, 'Uliza: Binadamu wa Zama za Mawe alilaa nini? Aliishi wapi? Alikuwa akilima ardhi?', 'Pendekeza jinsi binadamu wa Zama za Mawe alivyojipatia chakula na makazi.', 'Wanafunzi wanabainisha maarifa ya awali kuhusu maisha ya Zama za Mawe.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(554, 139, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu njia za binadamu wa Zama za Mawe za Kale kujipatia chakula (uwindaji na ukusanyaji) na makazi (mapango, miti).', 'Jadili njia za binadamu wa Zama za Mawe kujipatia chakula na makazi na uandike muhtasari.', 'Njia za binadamu wa Zama za Mawe kujipatia chakula na makazi zimebainishwa kwa usahihi.'),
(555, 139, 4, 'design', 10, 'Vikundi vichoree na vieleze siku ya kawaida ya binadamu wa Zama za Mawe ├óÔé¼ÔÇØ asubuhi, mchana, jioni.', 'Chora na ueleze siku ya kawaida ya binadamu wa Zama za Mawe za Kale.', 'Siku ya kawaida ya binadamu wa Zama za Mawe imechorwa na kuelezwa kwa usahihi.'),
(556, 139, 3, 'realisation', 5, 'Eleza njia mbili za binadamu wa Zama za Mawe kujipatia chakula na njia moja ya kupata makazi.', 'Eleza njia mbili za binadamu wa Zama za Mawe kujipatia chakula na njia moja ya kupata makazi.', 'Njia za binadamu wa Zama za Mawe kujipatia chakula na makazi zimebainishwa.'),
(557, 140, 1, 'introduction', 5, 'Onyesha kipande cha chuma na mawe. Uliza: Tofauti kati ya zana za chuma na mawe ni nini? Ni ipi bora zaidi?', 'Linganisha chuma na mawe na eleza kwa nini moja inaweza kuwa bora kuliko nyingine.', 'Wanafunzi wanabainisha tofauti za msingi kati ya chuma na mawe.'),
(558, 140, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu uvumbuzi wa chuma: jinsi chuma kilivyogunduliwa, kuyeyushwa na kutumika kutengeneza zana bora. Eleza athari za uvumbuzi huu kwa teknolojia.', 'Jadili uvumbuzi wa chuma na athari zake kwa maendeleo ya teknolojia ya binadamu.', 'Uvumbuzi wa chuma na athari zake kwa teknolojia zimebainishwa kwa usahihi.'),
(559, 140, 1, 'design', 10, 'Onyesha mchakato wa kuyeyusha chuma (kwa picha). Vikundi vibainishe hatua za kuyeyusha chuma na kufanya zana.', 'Angalia picha za mchakato wa kuyeyusha chuma na ubainishe hatua za kutengeneza zana za chuma.', 'Mchakato wa kutengeneza zana za chuma umebainishwa kwa usahihi.'),
(560, 140, 3, 'realisation', 5, 'Eleza uvumbuzi wa chuma na athari yake moja kuu kwa maendeleo ya teknolojia.', 'Eleza uvumbuzi wa chuma na athari yake moja kuu kwa teknolojia ya binadamu.', 'Uvumbuzi wa chuma na athari yake kwa teknolojia imebainishwa kwa usahihi.'),
(561, 141, 2, 'introduction', 5, 'Uliza: Chuma kilitumiwa kutengeneza nini? Zana hizi zinaweza kutengenezwa na mawe pia?', 'Pendekeza zana na silaha zinazoweza kutengenezwa kwa chuma.', 'Wanafunzi wanabainisha zana na silaha za msingi za chuma.'),
(562, 141, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu zana za chuma: majembe, miunzi, visu, shoka, mikuki, panga ├óÔé¼ÔÇØ na jinsi zinavyotofautiana na zana za mawe kwa ubora na ufanisi.', 'Jadili zana na silaha zilizotengenezwa kutoka chuma na uziorodheshe kwa mifano.', 'Zana na silaha za chuma zimebainishwa na kuelezwa jinsi zinavyotofautiana na za mawe.'),
(563, 141, 4, 'design', 10, 'Vikundi vichoree zana na silaha tano za chuma na vieleze matumizi ya kila moja.', 'Chora zana na silaha tano za chuma na eleza matumizi ya kila moja.', 'Zana na silaha tano za chuma zimechorwa na matumizi yake yameelezwa.'),
(564, 141, 3, 'realisation', 5, 'Orodhesha zana tatu na silaha mbili zilizotengenezwa kutoka chuma na eleza matumizi ya kila moja.', 'Orodhesha zana tatu na silaha mbili za chuma na eleza matumizi ya kila moja.', 'Zana tatu na silaha mbili za chuma zimeorodheshwa na matumizi yake yamebainishwa.'),
(565, 142, 6, 'introduction', 5, 'Uliza: Jinsi gani teknolojia ya Zama za Chuma ilikuwa tofauti na ile ya Zama za Mawe? Bora zaidi vipi?', 'Pendekeza tofauti tatu kati ya teknolojia ya Zama za Mawe na Zama za Chuma.', 'Wanafunzi wanabainisha tofauti za msingi kati ya Zama za Mawe na Chuma.'),
(566, 142, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kulinganisha teknolojia ya Zama za Mawe (zana ghafi, ngumu kufanya, haziachi ukali) na Zama za Chuma (zana nyepesi, zenye ukali, zinaweza kufanywa upya).', 'Jadili na uandike jedwali la ulinganisho wa teknolojia ya Zama za Mawe na Zama za Chuma.', 'Teknolojia ya Zama za Mawe na Zama za Chuma imelinganishwa kwa usahihi.'),
(567, 142, 6, 'design', 10, 'Fikiri-andika-jozisha-shirikisha: Kila mwanafunzi abainishe tofauti mbili, ajozishe na mwenzake, wasilishane.', 'Andika tofauti mbili kati ya Zama za Mawe na Zama za Chuma, jozisha na shirikisha.', 'Tofauti sahihi mbili kati ya Zama za Mawe na Zama za Chuma zimebainishwa.'),
(568, 142, 3, 'realisation', 5, 'Eleza tofauti tatu kati ya teknolojia ya Zama za Mawe na Zama za Chuma.', 'Eleza tofauti tatu kati ya teknolojia ya Zama za Mawe na Zama za Chuma.', 'Tofauti tatu sahihi kati ya teknolojia ya Zama hizo zimebainishwa.'),
(569, 143, 3, 'introduction', 5, 'Uliza: Teknolojia ya chuma ilibadilisha maisha ya binadamu vipi? Watu walianza kufanya nini ambacho hawakuweza kufanya kabla?', 'Pendekeza jinsi teknolojia ya chuma ilibadilisha maisha ya watu.', 'Wanafunzi wanabainisha mabadiliko mawili yaliyotokea kutokana na uvumbuzi wa chuma.'),
(570, 143, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu jinsi teknolojia ya chuma ilivyobadilisha maisha: kilimo bora (majembe ya chuma), vita vya mara nyingi zaidi (silaha bora), biashara ya zana, makazi ya kudumu.', 'Jadili jinsi teknolojia ya chuma ilivyobadilisha maisha ya binadamu na uandike mifano.', 'Jinsi teknolojia ya chuma ilivyobadilisha maisha ya binadamu imebainishwa kwa usahihi.'),
(571, 143, 2, 'design', 10, 'Vikundi viunde mstari wa muda unaoonyesha mabadiliko makuu yaliyotokea wakati wa Zama za Chuma.', 'Unda mstari wa muda unaoonyesha mabadiliko makuu ya Zama za Chuma.', 'Mstari wa muda wenye mabadiliko sahihi ya Zama za Chuma umeundwa.'),
(572, 143, 3, 'realisation', 5, 'Eleza jinsi teknolojia ya chuma ilivyobadilisha maisha ya binadamu kwa mifano miwili.', 'Eleza jinsi teknolojia ya chuma ilivyobadilisha maisha ya binadamu kwa mifano miwili.', 'Mifano miwili sahihi ya mabadiliko ya teknolojia ya chuma imebainishwa.'),
(573, 144, 5, 'introduction', 5, 'Uliza: Je, Afrika ilikuwa na uvumbuzi wake wa sayamsi na teknolojia kabla ya ukoloni? Uvumbuzi gani?', 'Toa mifano ya uvumbuzi wowote wa Afrika wanaoufahamu.', 'Wanafunzi wanabainisha maarifa ya awali kuhusu uvumbuzi wa Afrika.'),
(574, 144, 2, 'development', 20, 'Ongoza majadiliano ya vikundi kuhusu vichangio vya jamii za Kiafrika: ufumbuzi wa madini, usanifu wa majengo (Zimbabwe), kilimo, dawa za asili, hisabati (hifadhi ya Ishango), usafiri wa baharini.', 'Jadili mchango wa jamii za Kiafrika katika sayamsi na teknolojia kabla ya ukoloni.', 'Mchango wa jamii za Kiafrika katika sayamsi na teknolojia umebainishwa kwa usahihi.'),
(575, 144, 12, 'design', 10, 'Vikundi vitafiti uvumbuzi mmoja wa Afrika na viwasilishe matokeo kwa darasa.', 'Tafiti uvumbuzi mmoja wa kisayamsi au kiteknolojia kutoka Afrika na uwasilishe matokeo.', 'Uvumbuzi wa Afrika wa kisayamsi au kiteknolojia umetafitishwa na kuwasilishwa kwa usahihi.'),
(576, 144, 3, 'realisation', 5, 'Eleza mchango wa Afrika katika sayamsi na teknolojia kwa mifano miwili.', 'Eleza mchango wa jamii za Kiafrika katika sayamsi na teknolojia kwa mifano miwili.', 'Mchango wa Afrika katika sayamsi na teknolojia umebainishwa kwa mifano miwili sahihi.'),
(577, 145, 2, 'introduction', 5, 'Uliza: Uvumbuzi wa sayamsi na teknolojia wa Afrika wa zamani una umuhimu gani kwa Tanzania ya leo?', 'Pendekeza umuhimu wa kujua kuhusu teknolojia ya Afrika ya zamani.', 'Wanafunzi wanabainisha umuhimu wa awali wa teknolojia ya kabla ya ukoloni.'),
(578, 145, 2, 'development', 20, 'Ongoza majadiliano tathmini ya umuhimu wa vichangio vya teknolojia ya kabla ya ukoloni: kuimarisha utambulisho wa Afrika, kuonyesha uwezo wa Waafrika wa kujitegemea, kutumika kama msingi wa teknolojia ya kisasa.', 'Jadili na utathmini umuhimu wa vichangio vya teknolojia ya kabla ya ukoloni kwa Tanzania ya leo.', 'Umuhimu wa vichangio vya teknolojia ya kabla ya ukoloni kwa Tanzania umetathminiwa kwa usahihi.'),
(579, 145, 2, 'design', 10, 'Vikundi viunde hoja: \"Kujifunza kuhusu teknolojia ya kabla ya ukoloni ni muhimu kwa Tanzania ya sasa.\" Wasilisha na jadiliana.', 'Unda hoja tatu za kwa nini kujifunza teknolojia ya kabla ya ukoloni ni muhimu kwa Tanzania ya sasa.', 'Hoja zenye mantiki za umuhimu wa teknolojia ya kabla ya ukoloni zimeundwa.'),
(580, 145, 3, 'realisation', 5, 'Tathmini umuhimu wa vichangio vya teknolojia ya kabla ya ukoloni kwa Tanzania kwa sentensi tatu.', 'Tathmini umuhimu wa vichangio vya teknolojia ya kabla ya ukoloni kwa Tanzania kwa sentensi tatu.', 'Tathmini sahihi ya umuhimu wa teknolojia ya kabla ya ukoloni imeandikwa.'),
(581, 146, 5, 'introduction', 5, 'Brainstorm: Ask students \"What is Mathematics?\" and \"Where do you use Mathematics in everyday life?\" Record responses on the board.', 'Share ideas about what Mathematics means and where they encounter it daily (shopping, cooking, time, etc.).', 'Students can give at least two examples of Mathematics in everyday life.'),
(582, 146, 2, 'development', 20, 'Guide a group discussion using handouts showing real-life scenarios involving Mathematics: a market receipt, a recipe, a timetable. Ask students to identify the mathematical operations involved.', 'Discuss in groups the mathematical operations found in each real-life scenario and identify the role Mathematics plays.', 'The role of Mathematics in everyday life is clearly explained with relevant examples from the scenarios.'),
(583, 146, 2, 'design', 10, 'Each group creates a poster or list showing at least five real-life situations where Mathematics is used, with the specific mathematical concepts involved.', 'Create a list of five real-life situations and the Mathematics involved in each situation.', 'At least five real-life situations using Mathematics are identified with correct mathematical concepts.'),
(584, 146, 3, 'realisation', 5, 'Each student writes a definition of Mathematics in their own words and states two ways Mathematics is used in everyday life.', 'Write a definition of Mathematics and two ways it is used in everyday life.', 'Mathematics is correctly defined and two relevant everyday uses are stated.'),
(585, 147, 12, 'introduction', 5, 'Ask: \"Who invented Mathematics? Where and when was Mathematics first used?\" Allow students to speculate.', 'Share their ideas about the origins of Mathematics.', 'Students show curiosity about the history of Mathematics.'),
(586, 147, 2, 'development', 20, 'Guide a group discussion using handouts about the history of Mathematics: ancient Egypt (geometry for land measurement), Mesopotamia (arithmetic), Greece (formal proofs), Arabia (algebra), and modern developments.', 'Read the handout and discuss the key stages in the development of Mathematics across different civilizations.', 'Key stages in the history and development of Mathematics are correctly identified.'),
(587, 147, 12, 'design', 10, 'Groups research one ancient civilization that contributed to Mathematics and create a timeline entry with their contribution.', 'Research one ancient civilization\'s contribution to Mathematics and prepare a brief presentation.', 'The mathematical contribution of an ancient civilization is correctly researched and presented.'),
(588, 147, 3, 'realisation', 5, 'Each student lists three civilizations that contributed to the development of Mathematics and one contribution from each.', 'List three civilizations and one mathematical contribution from each.', 'Three civilizations and their mathematical contributions are correctly listed.'),
(589, 148, 5, 'introduction', 5, 'Ask: \"What types of Mathematics have you heard of? Arithmetic? Algebra? Geometry? Statistics?\" Record responses.', 'Brainstorm the different types of Mathematics they have heard of.', 'Students can name at least two branches of Mathematics.'),
(590, 148, 2, 'development', 20, 'Guide groups to explore the main branches of Mathematics (Arithmetic, Algebra, Geometry, Statistics, Calculus) and discuss real-life applications of each branch.', 'Discuss each branch of Mathematics, its definition, and two real-life applications. Fill in the provided table.', 'The main branches of Mathematics and their applications are correctly identified.'),
(591, 148, 6, 'design', 10, 'Think-pair-share: Each student chooses a branch they find most interesting and explains why to their partner, then shares with the class.', 'Choose a branch of Mathematics, explain why you find it interesting, pair with a partner and share with the class.', 'A branch of Mathematics is correctly identified and its relevance is explained.'),
(592, 148, 3, 'realisation', 5, 'Each student names four branches of Mathematics and one application of each.', 'Name four branches of Mathematics and one application of each branch.', 'Four branches of Mathematics and one application each are correctly stated.'),
(593, 149, 5, 'introduction', 5, 'Ask: \"Which other school subjects use Mathematics? How?\" Allow students to think and share.', 'Share ideas about which subjects use Mathematics and how.', 'Students can name two subjects that use Mathematics.'),
(594, 149, 2, 'development', 20, 'Guide a jigsaw activity: divide the class into expert groups, each assigned a subject (Physics, Chemistry, Biology, Geography, Business). Groups discuss and then regroup to share how Mathematics is used in their subject.', 'In expert groups discuss how Mathematics is used in your assigned subject. Regroup and share findings.', 'The relationship between Mathematics and at least three other subjects is correctly explained.'),
(595, 149, 2, 'design', 10, 'Groups create a mind map showing Mathematics at the centre and connected subjects around it with specific examples of how Mathematics is used.', 'Create a mind map showing how Mathematics connects to at least four other school subjects with specific examples.', 'A mind map correctly showing the relationship between Mathematics and other subjects is created.'),
(596, 149, 3, 'realisation', 5, 'Each student explains in two sentences how Mathematics is used in one subject of their choice.', 'Explain in two sentences how Mathematics is used in one other school subject.', 'The correct use of Mathematics in another school subject is explained.'),
(597, 150, 1, 'introduction', 5, 'Demonstrate rounding off on the board: round 3.746 to 2 decimal places and to 2 significant figures. Show the steps clearly.', 'Watch the demonstration and attempt to identify the rule for rounding off.', 'Students can identify the basic rule for rounding off (5 and above, round up).'),
(598, 150, 2, 'development', 20, 'Guide groups using a worksheet with numbers to round off to various significant figures and decimal places. Circulate and provide guidance. Groups compare answers.', 'Work in groups to round off the given numbers to the required significant figures and decimal places.', 'Numbers are correctly rounded off to the required significant figures and decimal places.'),
(599, 150, 9, 'design', 10, 'Students work individually on a set of problems: round off measurements (lengths, masses, prices) to given significant figures and decimal places.', 'Round off the given measurements to the required number of significant figures and decimal places.', 'Measurements are correctly rounded off to the required precision.'),
(600, 150, 3, 'realisation', 5, 'Pose two questions: round 4.8756 to 2 decimal places and to 3 significant figures. Students answer individually.', 'Round 4.8756 to 2 decimal places and to 3 significant figures.', '4.8756 is correctly rounded to 2 decimal places (4.88) and to 3 significant figures (4.88).'),
(601, 151, 5, 'introduction', 5, 'Brainstorm: \"When do we estimate rather than calculate exactly? Give examples from real life.\" Record student responses.', 'Share situations where estimation is used (estimating cost, time, distance).', 'Students give at least two real-life situations where estimation is used.'),
(602, 151, 2, 'development', 20, 'Guide group discussion using scenarios: estimate the cost of items in a market, estimate the number of students in a school photograph, estimate the length of a room using strides. Discuss estimation strategies.', 'Discuss estimation strategies for each scenario and record estimated values with reasoning.', 'Appropriate estimation strategies are applied and reasonable estimated values are obtained.'),
(603, 151, 9, 'design', 10, 'Students estimate answers to real-life problems (e.g., how many tiles needed to cover a floor, approximate cost of school supplies) using front-end estimation or rounding.', 'Use approximation to estimate answers to the given real-life problems without a calculator.', 'Reasonable estimates are obtained using correct approximation techniques.'),
(604, 151, 3, 'realisation', 5, 'Pose a problem: Estimate the cost of 4 items priced at Tsh 1,950, Tsh 3,100, Tsh 780, and Tsh 2,450. Students estimate the total.', 'Estimate the total cost of four items by rounding each price to the nearest thousand.', 'A reasonable estimate of the total cost is correctly obtained through approximation.'),
(605, 152, 1, 'introduction', 5, 'Demonstrate: the actual length of a pencil is 15.2 cm, you estimated 15 cm. Show how to find the error and percentage error.', 'Watch the demonstration and try to identify the formula for percentage error.', 'Students can state the formula for percentage error: (error/actual value) ├âÔÇö 100%.'),
(606, 152, 2, 'development', 20, 'Guide groups through examples of calculating absolute error and percentage error in different contexts (measurement of length, mass, temperature). Use worksheet.', 'Calculate absolute error and percentage error for the measurements given in the worksheet.', 'Absolute error and percentage error are correctly calculated for each measurement.'),
(607, 152, 9, 'design', 10, 'Students solve problems: given approximate and actual values, calculate the percentage error and determine if the approximation is acceptable.', 'Calculate the percentage error for each approximation and state if it is acceptable (< 5%).', 'Percentage errors are correctly calculated and correctly assessed as acceptable or not.'),
(608, 152, 3, 'realisation', 5, 'Pose: actual mass = 2.48 kg, estimated = 2.5 kg. Find the percentage error.', 'Calculate the percentage error when actual mass = 2.48 kg and estimated mass = 2.5 kg.', 'Percentage error is correctly calculated as approximately 0.81%.'),
(609, 153, 7, 'introduction', 5, 'Present a case: A contractor estimates the cost of building materials to be Tsh 500,000. The actual cost is Tsh 485,000. Ask: Was the estimate good? How would you decide?', 'Analyse the case and explain whether the estimate was acceptable and how you know.', 'Students can use the concept of percentage error to evaluate the estimate.'),
(610, 153, 2, 'development', 20, 'Guide groups to solve real-life approximation problems: budgeting for a school event, estimating travel time, approximating ingredient quantities for cooking. Apply rounding and percentage error.', 'Solve the real-life approximation problems in your group, showing your estimation method and percentage error where appropriate.', 'Real-life approximation problems are correctly solved using appropriate estimation techniques.'),
(611, 153, 9, 'design', 10, 'Each group creates a real-life problem involving approximation and exchanges it with another group to solve.', 'Create a real-life problem involving approximation and solve the problem given by another group.', 'Real-life approximation problems are correctly created and solved.'),
(612, 153, 3, 'realisation', 5, 'Pose: estimate how many 250 ml cups can be filled from a 3-litre bottle. State your answer and percentage error if actual answer is given.', 'Estimate how many 250 ml cups fill a 3-litre bottle and calculate the percentage error.', 'Correct estimate (12 cups) is obtained and percentage error is correctly calculated.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(613, 154, 1, 'introduction', 5, 'Demonstrate: A car travels 120 km in 2 hours. Ask: How fast is it going? Show the calculation of speed = distance/time.', 'Watch the demonstration and try to state the formula for rate (speed).', 'Students can state that rate = quantity per unit of time or per unit.'),
(614, 154, 2, 'development', 20, 'Guide groups to calculate different types of rates from real-life scenarios: speed (km/h), water flow (litres/minute), unit price (Tsh/kg), fuel consumption (km/litre).', 'Calculate the rate for each real-life scenario in your group and state the unit of the rate.', 'Different types of rates are correctly calculated with correct units stated.'),
(615, 154, 9, 'design', 10, 'Students solve individual problems: calculate speed, unit price, and flow rate from given data.', 'Calculate speed, unit price, and flow rate from the given data, stating units clearly.', 'Speed, unit price, and flow rate are correctly calculated with correct units.'),
(616, 154, 3, 'realisation', 5, 'Pose: A pump fills a 1,000-litre tank in 25 minutes. What is the flow rate in litres per minute?', 'Calculate the flow rate of the pump.', 'Flow rate is correctly calculated as 40 litres per minute.'),
(617, 155, 5, 'introduction', 5, 'Brainstorm: \"Where do we use ratios in real life?\" ├óÔé¼ÔÇØ mixing cement (3:1), sharing items, map scales, recipes.', 'Share examples of where ratios are used in everyday life.', 'Students can give two examples of ratios from everyday life.'),
(618, 155, 2, 'development', 20, 'Guide groups through ratio problems: simplifying ratios, dividing quantities in given ratios, and comparing ratios. Use concrete examples (sharing money, mixing paint colours, cement and sand).', 'Solve ratio problems in groups: simplify the given ratios and divide the given quantity in the stated ratios.', 'Ratios are correctly simplified and quantities are correctly divided in given ratios.'),
(619, 155, 9, 'design', 10, 'Students solve practical problems: a recipe for 4 people requires 200g flour ├óÔé¼ÔÇØ how much for 6 people? A map scale is 1:50,000 ├óÔé¼ÔÇØ find the actual distance for a 4 cm map distance.', 'Solve the practical ratio problems involving recipes, map scales, and sharing.', 'Practical ratio problems are correctly solved with clear working shown.'),
(620, 155, 3, 'realisation', 5, 'Pose: Share Tsh 6,000 between Ali and Bea in the ratio 2:3. How much does each get?', 'Divide Tsh 6,000 between Ali and Bea in the ratio 2:3.', 'Ali gets Tsh 2,400 and Bea gets Tsh 3,600. Calculation is correctly shown.'),
(621, 156, 1, 'introduction', 5, 'Demonstrate with a table: as the number of items increases, the total cost increases (direct) vs. as the number of workers increases, time to complete a task decreases (inverse). Show the patterns.', 'Observe the two tables and try to identify the difference between the two proportions.', 'Students can identify the basic difference between direct and inverse proportion.'),
(622, 156, 2, 'development', 20, 'Guide group discussion: classify given scenarios as direct or inverse proportion, and explain why. Scenarios: more petrol ├óÔÇáÔÇÖ more distance; more workers ├óÔÇáÔÇÖ less time; more items ├óÔÇáÔÇÖ more cost; more speed ├óÔÇáÔÇÖ less time.', 'Classify each scenario as direct or inverse proportion and explain the reasoning.', 'Scenarios are correctly classified as direct or inverse proportion with correct reasoning.'),
(623, 156, 6, 'design', 10, 'Think-pair-share: Each student creates one example of direct proportion and one of inverse proportion from real life, then shares with partner and class.', 'Create one real-life example each of direct and inverse proportion, share with partner, then with class.', 'Correct and relevant examples of both direct and inverse proportion are created.'),
(624, 156, 3, 'realisation', 5, 'Pose two scenarios and ask students to classify each as direct or inverse: (a) cost of fuel vs. litres purchased; (b) time to paint a house vs. number of painters.', 'Classify each scenario as direct or inverse proportion and explain why.', 'Both scenarios are correctly classified: (a) direct, (b) inverse, with correct explanations.'),
(625, 157, 1, 'introduction', 5, 'Demonstrate solving a direct proportion problem: 5 kg of rice costs Tsh 10,000. What does 8 kg cost? Show the unitary method and ratio method.', 'Watch the demonstration and identify the two methods for solving direct proportion problems.', 'Students can use the unitary method to solve a simple direct proportion problem.'),
(626, 157, 2, 'development', 20, 'Guide groups to solve direct and inverse proportion problems using the unitary method. Problems include: cooking ingredients, travel time, workers and time, purchasing different quantities.', 'Solve the direct and inverse proportion problems using the unitary method. Show all working.', 'Direct and inverse proportion problems are correctly solved using the unitary method.'),
(627, 157, 9, 'design', 10, 'Students solve a set of mixed direct and inverse proportion problems independently, showing all working.', 'Solve the mixed proportion problems independently, showing all working clearly.', 'Mixed proportion problems are correctly solved with full working shown.'),
(628, 157, 3, 'realisation', 5, 'Pose: 4 workers take 6 days to build a wall. How long would 3 workers take (inverse proportion)?', 'Calculate how long 3 workers take to build the same wall.', '3 workers correctly calculated to take 8 days. Full working is shown.'),
(629, 158, 7, 'introduction', 5, 'Case study: A household uses 80 litres of water per day at a rate of Tsh 500 per 20 litres. Calculate the monthly water bill. What if they reduce usage by 25%?', 'Analyse the case study and calculate the monthly water bill and the saving from reduced usage.', 'Students correctly apply rate and proportion concepts to calculate water bills.'),
(630, 158, 2, 'development', 20, 'Guide groups to solve comprehensive real-life problems involving both rates and proportions: foreign exchange, mixing medicines, construction materials, comparing unit prices at shops.', 'Solve the real-life problems involving rates and proportions and present solutions to the class.', 'Real-life problems involving rates and proportions are correctly solved with clear reasoning.'),
(631, 158, 9, 'design', 10, 'Groups create and solve their own real-life rate-and-proportion problem related to their community (farming, small business, cooking, transport).', 'Create and solve a real-life problem using rates or proportions from your community context.', 'A relevant real-life problem is correctly created and solved using rates or proportions.'),
(632, 158, 3, 'realisation', 5, 'Pose: A car travels 360 km on 40 litres of petrol. At Tsh 2,500 per litre, how much does a 270 km journey cost?', 'Calculate the cost of the 270 km journey using rates and proportions.', 'Journey cost is correctly calculated as Tsh 18,750. Full working is shown.'),
(633, 159, 1, 'introduction', 5, 'Demonstrate conversions on the board: 3/4 = 0.75 = 75%. Show the steps for each conversion direction.', 'Watch the conversions and try to identify the rule for each conversion direction.', 'Students can convert a simple fraction to a decimal and to a percentage.'),
(634, 159, 2, 'development', 20, 'Guide groups to practice conversions using a table worksheet: given fraction, find decimal and percentage; given decimal, find fraction and percentage; given percentage, find fraction and decimal.', 'Complete the conversion table for the given fractions, decimals and percentages.', 'Conversions between fractions, decimals and percentages are correctly performed.'),
(635, 159, 9, 'design', 10, 'Students complete individual conversion problems including fractions with denominators that are not powers of 10 (e.g., 1/3, 2/7).', 'Convert the given fractions, decimals and percentages, including recurring decimals.', 'Conversions including fractions producing recurring decimals are correctly performed.'),
(636, 159, 3, 'realisation', 5, 'Convert: (a) 3/8 to decimal and percentage; (b) 0.35 to fraction and percentage; (c) 45% to fraction and decimal.', 'Convert the given values between fraction, decimal and percentage form.', 'All three conversions are correctly performed: (a) 0.375 / 37.5%; (b) 7/20 / 35%; (c) 9/20 / 0.45.'),
(637, 160, 1, 'introduction', 5, 'Demonstrate using fraction bars/strips: 1/2 + 1/3. Show how to find the LCM and add the fractions. Explain using visual models.', 'Use fraction strips to model 1/2 + 1/3 and observe the demonstration.', 'Students can add simple fractions using the LCM method.'),
(638, 160, 4, 'development', 20, 'Guide groups using fraction strips and calculation to add and subtract fractions with unlike denominators and mixed numbers. Work through increasingly complex examples.', 'Use fraction strips and calculation to add and subtract fractions and mixed numbers in the worksheet.', 'Fractions and mixed numbers are correctly added and subtracted, with LCM correctly found.'),
(639, 160, 9, 'design', 10, 'Students solve individual problems involving addition and subtraction of fractions and mixed numbers, including real-life contexts (recipes, distances).', 'Solve the fraction addition and subtraction problems, showing all working including LCM steps.', 'Fraction addition and subtraction problems are correctly solved with all steps shown.'),
(640, 160, 3, 'realisation', 5, 'Calculate: 2├é┬¥ + 1├óÔÇªÔÇØ ├ó╦åÔÇÖ ├é┬¢.', 'Calculate 2├é┬¥ + 1├óÔÇªÔÇØ ├ó╦åÔÇÖ ├é┬¢, showing all working.', 'Answer 3 11/12 is correctly obtained with all working clearly shown.'),
(641, 161, 1, 'introduction', 5, 'Demonstrate: 2/3 ├âÔÇö 3/4 = 6/12 = 1/2. Then show division: 2/3 ├â┬À 3/4 = 2/3 ├âÔÇö 4/3 = 8/9. Explain the \"flip and multiply\" rule for division.', 'Watch the demonstrations and state in your own words the rule for dividing fractions.', 'Students can state the rule for dividing fractions (multiply by the reciprocal).'),
(642, 161, 2, 'development', 20, 'Guide groups to multiply and divide fractions and mixed numbers, using simplification before multiplying. Work through problems with increasing complexity.', 'Multiply and divide the fractions and mixed numbers in the worksheet, simplifying where possible.', 'Fractions and mixed numbers are correctly multiplied and divided with simplification shown.'),
(643, 161, 9, 'design', 10, 'Students solve real-life problems involving multiplication and division of fractions: dividing ingredients, cutting material, sharing portions.', 'Solve the real-life fraction multiplication and division problems, showing all working.', 'Real-life fraction problems are correctly solved with full working shown.'),
(644, 161, 3, 'realisation', 5, 'Calculate: 1├óÔÇªÔÇØ ├âÔÇö 2├é┬╝ ├â┬À ├é┬¢.', 'Calculate 1├óÔÇªÔÇØ ├âÔÇö 2├é┬╝ ├â┬À ├é┬¢, showing all working.', 'Answer 7├é┬¢ is correctly obtained with all working clearly shown.'),
(645, 162, 5, 'introduction', 5, 'Brainstorm: \"Where do we see percentages in real life?\" ├óÔé¼ÔÇØ bank interest, discounts, exam marks, VAT, profit margins.', 'Share real-life examples where percentages are used.', 'Students give at least three real-life examples of percentages.'),
(646, 162, 2, 'development', 20, 'Guide group discussion and problem solving: calculate percentage increase/decrease (prices, population), profit and loss percentage, simple interest.', 'Solve problems on percentage increase, decrease, profit, loss, and simple interest in your group.', 'Percentage increase, decrease, profit, loss, and simple interest are correctly calculated.'),
(647, 162, 9, 'design', 10, 'Students solve individual percentage problems in context: a shopkeeper buys goods at Tsh 8,000 and sells at Tsh 10,000 ├óÔé¼ÔÇØ find profit % and selling price with 15% VAT.', 'Solve the percentage problems in context, showing all working.', 'Percentage problems in context are correctly solved with full working shown.'),
(648, 162, 3, 'realisation', 5, 'A phone cost Tsh 150,000. It is sold at Tsh 120,000. Find the percentage loss.', 'Calculate the percentage loss on the phone sale.', 'Percentage loss correctly calculated as 20%. Full working shown.'),
(649, 163, 7, 'introduction', 5, 'Case study: A shop bought 50 kg of rice at Tsh 60,000. It sold ├óÔÇªÔÇØ at a 25% profit and the rest at a 10% loss. Find the total revenue.', 'Analyse the case study and calculate the total revenue, showing all working.', 'Students correctly apply fractions and percentages to a multi-step financial problem.'),
(650, 163, 2, 'development', 20, 'Guide groups to solve financial problems involving fractions, decimals and percentages: bank loans, tax calculations, discounts, salary deductions, business profits.', 'Solve the financial problems involving fractions, decimals and percentages in your group.', 'Financial problems combining fractions, decimals and percentages are correctly solved.'),
(651, 163, 9, 'design', 10, 'Groups create a real-life financial problem involving fractions and percentages and exchange with another group to solve.', 'Create a financial problem using fractions and percentages and solve the problem given by another group.', 'Financial problems are correctly created and solved using fractions and percentages.'),
(652, 163, 3, 'realisation', 5, 'Pose: A salary of Tsh 400,000 has 12.5% deducted for tax and ├óÔÇªÔÇ║ saved. Find take-home pay.', 'Calculate the take-home pay after tax deduction and savings.', 'Take-home pay correctly calculated as Tsh 300,000. Full working shown.'),
(653, 164, 1, 'introduction', 5, 'Demonstrate: \"I am thinking of a number. When I add 5, I get 12. What is the number?\" Show how to write this as x + 5 = 12 and solve.', 'Watch the demonstration and try to write the word problem as an equation using a letter.', 'Students can write a simple word problem as an algebraic equation.'),
(654, 164, 2, 'development', 20, 'Guide groups to translate word problems into algebraic expressions and equations using letters for unknown quantities. Work through a range of examples.', 'Translate each word problem into an algebraic expression or equation using letters for unknowns.', 'Word problems are correctly translated into algebraic expressions and equations.'),
(655, 164, 9, 'design', 10, 'Students write their own word problem involving an unknown quantity and express it algebraically, then swap with a partner to solve.', 'Write a word problem with an unknown quantity, express it algebraically, and solve a partner\'s problem.', 'Word problems are correctly expressed algebraically and solved.'),
(656, 164, 3, 'realisation', 5, 'Write as an equation: \"Three times a number decreased by 7 equals 14.\" Then state what the letter represents.', 'Write the word problem as an equation and state what the letter represents.', 'Equation 3x ├ó╦åÔÇÖ 7 = 14 (or equivalent) is correctly written and x is correctly defined.'),
(657, 165, 1, 'introduction', 5, 'Demonstrate: Simplify 3x + 2y ├ó╦åÔÇÖ x + 4y. Show the step of identifying like terms and collecting them.', 'Watch the demonstration and identify which terms are like terms.', 'Students can identify like terms in an algebraic expression.'),
(658, 165, 2, 'development', 20, 'Guide groups to simplify algebraic expressions by collecting like terms, including expressions with brackets and negative signs. Use a worksheet with increasing complexity.', 'Simplify each algebraic expression by collecting like terms. Show all steps.', 'Algebraic expressions are correctly simplified by collecting like terms.'),
(659, 165, 9, 'design', 10, 'Students simplify expressions in context: a perimeter problem where side lengths are given as algebraic expressions.', 'Find the perimeter of the shape by simplifying the algebraic expression for total perimeter.', 'The perimeter is correctly expressed as a simplified algebraic expression.'),
(660, 165, 3, 'realisation', 5, 'Simplify: 5a + 3b ├ó╦åÔÇÖ 2a + b ├ó╦åÔÇÖ 4.', 'Simplify 5a + 3b ├ó╦åÔÇÖ 2a + b ├ó╦åÔÇÖ 4.', 'Answer 3a + 4b ├ó╦åÔÇÖ 4 is correctly obtained.'),
(661, 166, 1, 'introduction', 5, 'Demonstrate expanding: 3(2x + 5) = 6x + 15. Then show the reverse ├óÔé¼ÔÇØ factorising: 6x + 15 = 3(2x + 5). Use area model visual aid.', 'Watch the demonstration and state in your words what expanding and factorising mean.', 'Students can explain the relationship between expanding and factorising.'),
(662, 166, 2, 'development', 20, 'Guide groups to expand brackets and factorise expressions using the highest common factor. Progress from simple to more complex examples.', 'Expand the given expressions and factorise the given expressions, showing all steps.', 'Expressions are correctly expanded and factorised with HCF correctly identified.'),
(663, 166, 9, 'design', 10, 'Students work on individual problems: expand and simplify, then factorise the result to verify.', 'Expand and simplify each expression, then factorise your answer to check.', 'Expressions are correctly expanded, simplified and factorised.'),
(664, 166, 3, 'realisation', 5, 'Expand: 4(3x ├ó╦åÔÇÖ 2) + 2(x + 5). Then factorise your answer.', 'Expand 4(3x ├ó╦åÔÇÖ 2) + 2(x + 5) and factorise the result.', 'Expansion gives 14x ├ó╦åÔÇÖ 2; factorised form is 2(7x ├ó╦åÔÇÖ 1). Both correctly obtained.'),
(665, 167, 1, 'introduction', 5, 'Demonstrate solving: 3x + 5 = 14. Show the balance method step by step. Verify the solution by substitution.', 'Watch the demonstration and try to explain each step in the balance method.', 'Students can use the balance method to solve a simple one-step linear equation.'),
(666, 167, 2, 'development', 20, 'Guide groups to solve linear equations of increasing complexity: one-step, two-step, equations with brackets, equations with unknowns on both sides.', 'Solve each linear equation using the balance method. Show all steps and verify your answer.', 'Linear equations are correctly solved using the balance method with verification shown.'),
(667, 167, 9, 'design', 10, 'Students solve linear equations in word-problem contexts: age problems, money problems, measurement problems.', 'Translate each word problem into a linear equation, solve it, and state the answer in context.', 'Linear equations are correctly solved in context with answers correctly interpreted.'),
(668, 167, 3, 'realisation', 5, 'Solve: 2(3x ├ó╦åÔÇÖ 4) = 5x + 1.', 'Solve 2(3x ├ó╦åÔÇÖ 4) = 5x + 1, showing all steps.', 'Answer x = 9 is correctly obtained with all steps shown.'),
(669, 168, 5, 'introduction', 5, 'Pose a real-life problem: \"Ali has some money. He spends Tsh 3,000 on food and Tsh 1,500 on transport, and has Tsh 2,500 left. How much did he start with?\" Ask how to solve using algebra.', 'Discuss how to write this problem as an equation and solve it.', 'Students can write and solve a simple real-life linear equation.'),
(670, 168, 2, 'development', 20, 'Guide groups to form and solve linear equations from real-life scenarios: age problems, consecutive number problems, perimeter problems, work and time problems.', 'Form linear equations from the given scenarios, solve them, and interpret the answers in context.', 'Linear equations are correctly formed from real-life scenarios and correctly solved.'),
(671, 168, 9, 'design', 10, 'Groups design their own real-life linear equation problem and solve a problem from another group.', 'Create a real-life problem that requires forming and solving a linear equation, then solve another group\'s problem.', 'Real-life linear equation problems are correctly created and solved.'),
(672, 168, 3, 'realisation', 5, 'Pose: The sum of two consecutive even numbers is 46. Find the numbers.', 'Form a linear equation for the problem and solve to find the two consecutive even numbers.', 'Equation 2n + 2 = 46 (or equivalent) is correctly formed and solved. Numbers 22 and 24 are found.');
INSERT INTO `element_methods` (`id`, `element_id`, `method_id`, `stage`, `time_minutes`, `teaching_activity`, `learning_activity`, `assessment_criteria`) VALUES
(673, 169, 1, 'introduction', 5, 'Demonstrate substitution: A = ├ÅÔé¼r├é┬▓. Find A when r = 7 cm (use ├ÅÔé¼ ├óÔÇ░╦å 22/7). Show each step clearly.', 'Watch the substitution and try the next example: V = lwh, find V when l=5, w=3, h=2.', 'Students can correctly substitute values into a given formula.'),
(674, 169, 2, 'development', 20, 'Guide groups to substitute values into common formulae: area and perimeter formulae, speed = distance/time, simple interest I = PRT/100.', 'Substitute the given values into each formula and calculate the result. State units.', 'Values are correctly substituted into formulae and results correctly calculated with correct units.'),
(675, 169, 9, 'design', 10, 'Students substitute values into formulae in real-life contexts: calculate simple interest on a loan, find the area of a field, calculate speed.', 'Substitute given values into the formulae and calculate the answer to each real-life problem.', 'Formula substitution is correctly applied in real-life contexts with correct results.'),
(676, 169, 3, 'realisation', 5, 'Calculate simple interest I = PRT/100 when P = Tsh 50,000, R = 8%, T = 3 years.', 'Calculate simple interest when P = 50,000, R = 8, T = 3.', 'Simple interest correctly calculated as Tsh 12,000.'),
(677, 170, 1, 'introduction', 5, 'Demonstrate: Solve x + 3 < 7. Show that x < 4, then draw the number line with an open circle at 4 and an arrow to the left.', 'Watch the demonstration and draw the number line representation for x + 3 < 7.', 'Students can solve a simple inequality and represent the solution on a number line.'),
(678, 170, 2, 'development', 20, 'Guide groups to solve inequalities with one operation, two operations, and negative coefficients (remembering to flip the inequality sign). Represent solutions on number lines.', 'Solve each inequality and represent the solution on a number line. Note when to flip the inequality sign.', 'Inequalities are correctly solved and solutions correctly represented on number lines.'),
(679, 170, 9, 'design', 10, 'Students solve inequalities in real-life contexts and represent solutions: minimum score needed to pass, maximum items fitting in a box.', 'Solve the inequality problems in context, state the solution, and represent it on a number line.', 'Inequalities in context are correctly solved and solution sets correctly represented.'),
(680, 170, 3, 'realisation', 5, 'Solve and draw a number line: 3x ├ó╦åÔÇÖ 5 ├óÔÇ░┬Ñ 7.', 'Solve 3x ├ó╦åÔÇÖ 5 ├óÔÇ░┬Ñ 7 and represent the solution on a number line.', 'Solution x ├óÔÇ░┬Ñ 4 is correctly obtained and represented with a closed circle at 4 and arrow to the right.'),
(681, 171, 5, 'introduction', 5, 'Pose: \"Kali is 3 years older than Tatu. The sum of their ages is 27. Find each person\'s age.\" Brainstorm how algebra can help solve this.', 'Discuss how to represent the unknowns with letters and set up an equation.', 'Students can set up a linear equation for the age problem.'),
(682, 171, 2, 'development', 20, 'Guide groups to solve age, money and number word problems using algebraic expressions. Work through a variety of contexts.', 'Solve the age, money and number problems by forming and solving algebraic equations. Show all working.', 'Age, money and number problems are correctly solved using algebraic equations.'),
(683, 171, 9, 'design', 10, 'Students solve individual word problems involving algebra in real-life contexts.', 'Solve the word problems independently, forming equations and showing all working.', 'Word problems are correctly solved with equations formed and full working shown.'),
(684, 171, 3, 'realisation', 5, 'Pose: A father is four times as old as his son. In 6 years, he will be twice as old. Find their current ages.', 'Form and solve equations to find the current ages of the father and son.', 'Son is 6, father is 24. Correct equations formed and solved with full working shown.'),
(685, 172, 1, 'introduction', 5, 'Demonstrate: \"Two items cost a total of Tsh 1,000. One item costs Tsh 200 more than the other. Find the cost of each.\" Show how to write two equations.', 'Watch the demonstration and write two equations for the given problem.', 'Students can write two linear equations to represent a problem with two unknowns.'),
(686, 172, 2, 'development', 20, 'Guide groups through solving simultaneous equations using the elimination method and substitution method. Work through simple examples with clear steps.', 'Solve the simultaneous equations using both elimination and substitution methods. Show all steps.', 'Simultaneous equations are correctly solved using both elimination and substitution methods.'),
(687, 172, 9, 'design', 10, 'Students solve simultaneous equations from real-life contexts: finding prices of two items, finding two unknown quantities in a mixture.', 'Solve the simultaneous equation problems in context, showing all working.', 'Simultaneous equations in context are correctly solved with full working shown.'),
(688, 172, 3, 'realisation', 5, 'Solve: x + y = 10 and x ├ó╦åÔÇÖ y = 4.', 'Solve the simultaneous equations x + y = 10 and x ├ó╦åÔÇÖ y = 4.', 'x = 7 and y = 3 correctly found using a valid method with full working shown.'),
(689, 173, 7, 'introduction', 5, 'Case study: At a school shop, 3 pens and 2 books cost Tsh 1,400. 1 pen and 3 books cost Tsh 1,100. Find the cost of each.', 'Write equations for the case study and attempt to solve them.', 'Students correctly write the two equations for the case study.'),
(690, 173, 2, 'development', 20, 'Guide groups to form and solve simultaneous equations from word problems in various contexts: prices, quantities, ages, mixture problems.', 'Form and solve simultaneous equations from the given word problems. Interpret the answers in context.', 'Word problems are correctly translated into simultaneous equations and correctly solved.'),
(691, 173, 9, 'design', 10, 'Groups create their own simultaneous equation word problem and exchange with another group to solve.', 'Create a word problem requiring simultaneous equations and solve the problem given by another group.', 'Word problems requiring simultaneous equations are correctly created and solved.'),
(692, 173, 3, 'realisation', 5, 'Pose: The sum of two numbers is 35. Their difference is 11. Find the two numbers.', 'Form and solve simultaneous equations to find the two numbers.', 'Numbers 23 and 12 correctly found. Equations correctly formed and solved.'),
(693, 174, 1, 'introduction', 5, 'Demonstrate expanding: (x + 2)(x + 3) = x├é┬▓ + 5x + 6. Show the FOIL method. Note the highest power is 2 ├óÔé¼ÔÇØ this is quadratic.', 'Watch the expansion and try to expand (x + 1)(x + 4) using the same method.', 'Students can expand a product of two binomials to obtain a quadratic expression.'),
(694, 174, 2, 'development', 20, 'Guide groups to expand products of binomials and identify quadratic expressions. Also factorize simple quadratic expressions where possible.', 'Expand the given products and factorise the given quadratic expressions. Show all working.', 'Products of binomials are correctly expanded and simple quadratic expressions correctly factorised.'),
(695, 174, 9, 'design', 10, 'Students solve simple quadratic equations by factorisation: x├é┬▓ + 5x + 6 = 0.', 'Solve the quadratic equations by factorisation. Show all steps including finding the factors.', 'Quadratic equations are correctly solved by factorisation with all steps shown.'),
(696, 174, 3, 'realisation', 5, 'Expand (x ├ó╦åÔÇÖ 3)(x + 5) and then solve x├é┬▓ + 2x ├ó╦åÔÇÖ 15 = 0 by factorisation.', 'Expand (x ├ó╦åÔÇÖ 3)(x + 5) and solve x├é┬▓ + 2x ├ó╦åÔÇÖ 15 = 0 by factorisation.', 'Expansion gives x├é┬▓ + 2x ├ó╦åÔÇÖ 15; solutions x = 3 and x = ├ó╦åÔÇÖ5 correctly found.'),
(697, 175, 1, 'introduction', 5, 'Demonstrate: Solve x├é┬▓ ├ó╦åÔÇÖ 5x + 6 = 0 by factorising. Show finding two numbers that multiply to 6 and add to ├ó╦åÔÇÖ5.', 'Watch the demonstration and try to factorise x├é┬▓ + 7x + 12.', 'Students can find two numbers that satisfy both conditions for simple factorisation.'),
(698, 175, 2, 'development', 20, 'Guide groups to solve quadratic equations by factorisation, including equations where the coefficient of x├é┬▓ is 1 and then greater than 1.', 'Solve each quadratic equation by factorisation. Show the factorised form before finding solutions.', 'Quadratic equations are correctly solved by factorisation with both solutions found.'),
(699, 175, 9, 'design', 10, 'Students solve quadratic equations in real-life contexts: an area problem (find the length of a rectangle given quadratic area expression), a projectile problem.', 'Solve the real-life quadratic problems by forming and solving quadratic equations.', 'Quadratic equations in context are correctly formed and solved by factorisation.'),
(700, 175, 3, 'realisation', 5, 'Solve: 2x├é┬▓ + 5x ├ó╦åÔÇÖ 3 = 0.', 'Solve 2x├é┬▓ + 5x ├ó╦åÔÇÖ 3 = 0 by factorisation.', 'Solutions x = ├é┬¢ and x = ├ó╦åÔÇÖ3 correctly found by factorisation with full working.'),
(701, 176, 1, 'introduction', 5, 'Demonstrate: The perimeter of a rectangle is 36 cm. The length is (2x + 1) cm and width is (x ├ó╦åÔÇÖ 1) cm. Find x. Show how to set up and solve the equation.', 'Watch the demonstration and write the equation for the perimeter problem.', 'Students can form a linear equation from a geometric perimeter problem.'),
(702, 176, 2, 'development', 20, 'Guide groups to apply algebra to geometric problems: finding missing angles using algebraic expressions, finding dimensions using area and perimeter equations.', 'Solve the geometric problems by forming algebraic equations. Show all working and state answers with units.', 'Algebra is correctly applied to geometric problems with correct equations formed and solved.'),
(703, 176, 9, 'design', 10, 'Students work on geometry problems involving algebra: angles in a triangle expressed algebraically sum to 180├é┬░; sides of a polygon expressed algebraically.', 'Solve the angle and polygon problems using algebra. Show all equations formed.', 'Angle and polygon problems are correctly solved using algebraic equations.'),
(704, 176, 3, 'realisation', 5, 'The angles of a triangle are x├é┬░, (2x + 10)├é┬░ and (3x ├ó╦åÔÇÖ 4)├é┬░. Find each angle.', 'Form and solve an equation to find each angle of the triangle.', 'x = 29; angles 29├é┬░, 68├é┬░, 83├é┬░ correctly found. Equation correctly formed using sum = 180├é┬░.'),
(705, 177, 1, 'introduction', 5, 'Demonstrate: Draw the graph of y = 2x + 1 by creating a table of values for x = ├ó╦åÔÇÖ2, ├ó╦åÔÇÖ1, 0, 1, 2. Plot points and draw the line.', 'Watch the demonstration and try to create a table of values for y = x + 3.', 'Students can create a table of values and plot points for a linear equation.'),
(706, 177, 2, 'development', 20, 'Guide groups to draw graphs of linear equations: identify gradient and y-intercept from the equation, create a table of values, plot points, and draw the line.', 'Draw graphs of the given linear equations. Create tables of values and label axes, gradient and y-intercept.', 'Linear equations are correctly graphed with axes labelled, tables of values correct, and gradient and intercept identified.'),
(707, 177, 9, 'design', 10, 'Students draw graphs of two simultaneous linear equations on the same axes and read off the solution from the graph.', 'Draw graphs of both equations on the same axes and read the solution (intersection point) from the graph.', 'Graphs are correctly drawn and the intersection point (solution) is correctly read from the graph.'),
(708, 177, 3, 'realisation', 5, 'Draw the graph of y = ├ó╦åÔÇÖx + 4 for x values from ├ó╦åÔÇÖ1 to 5. State the gradient and y-intercept.', 'Draw the graph of y = ├ó╦åÔÇÖx + 4, create a table of values, and state the gradient and y-intercept.', 'Graph correctly drawn; gradient = ├ó╦åÔÇÖ1 and y-intercept = 4 correctly stated.'),
(709, 178, 7, 'introduction', 5, 'Present a distance-time graph. Ask students to read the speed from the graph and interpret what happens during each section of the journey.', 'Read the distance-time graph and describe what is happening at each stage of the journey.', 'Students can read a distance-time graph and identify speed from its gradient.'),
(710, 178, 2, 'development', 20, 'Guide groups to interpret graphs in real-life contexts: distance-time (speed), cost-quantity (unit price), temperature-time (rate of cooling/heating). Identify gradient, intercept and what they mean.', 'Interpret the real-life graphs provided: describe what the gradient and intercept represent in context.', 'Real-life graphs are correctly interpreted with gradient and intercept correctly explained in context.'),
(711, 178, 9, 'design', 10, 'Groups draw and interpret their own real-life graph: a water tank filling over time, cost of taxi ride vs. distance, temperature change during the day.', 'Draw a real-life graph and write an interpretation of the gradient and intercept in context.', 'Real-life graph is correctly drawn and gradient and intercept correctly interpreted in context.'),
(712, 178, 3, 'realisation', 5, 'Given a cost graph showing fixed cost of Tsh 5,000 and variable cost of Tsh 500 per unit, write the equation and interpret gradient and y-intercept.', 'Write the equation for the cost graph and interpret the gradient and y-intercept in context.', 'Equation C = 500n + 5,000 correctly written; gradient (Tsh 500/unit) and y-intercept (Tsh 5,000 fixed cost) correctly interpreted.'),
(713, 1001, 3, 'introduction', 10, 'Ask students to state the tasks they would perform to achieve safety procedures and ESD precautions when handling hardware using the equipment in the laboratory.', 'State the tasks needed to achieve safety procedures and ESD precautions when handling hardware using the available equipment.', 'Tasks needed for safety procedures and ESD precautions when handling hardware are stated.'),
(714, 1001, 1, 'development', 40, 'Demonstrate safety procedures and ESD precautions when handling hardware step by step on the computer using the projector, stating the purpose of each step.', 'Observe the demonstration, note each step and repeat the steps on their own computers.', 'The steps of safety procedures and ESD precautions when handling hardware are correctly performed.'),
(715, 1001, 9, 'design', 20, 'Assign each pair a practical task on safety procedures and ESD precautions when handling hardware to be completed on the computer, and supervise the work.', 'Complete the assigned practical task on safety procedures and ESD precautions when handling hardware on the computer.', 'The practical task on safety procedures and ESD precautions when handling hardware is correctly completed.'),
(716, 1001, 3, 'realisation', 10, 'Ask each student to demonstrate one step of safety procedures and ESD precautions when handling hardware on the computer.', 'Demonstrate one step of safety procedures and ESD precautions when handling hardware on the computer.', 'One step of safety procedures and ESD precautions when handling hardware is correctly demonstrated by each student.'),
(717, 1002, 5, 'introduction', 10, 'Brainstorm with students: where and why is identification of hardware components and their functions needed? Record the ideas on the board.', 'Brainstorm and give ideas on where and why identification of hardware components and their functions is needed.', 'Ideas concerning identification of hardware components and their functions are given by students.'),
(718, 1002, 1, 'development', 40, 'Explain identification of hardware components and their functions step by step using the board and the projector, giving examples and guiding a question and answer session.', 'Follow the explanation, take notes on identification of hardware components and their functions and ask questions on unclear areas.', 'Identification of hardware components and their functions is correctly described with appropriate examples.'),
(719, 1002, 6, 'design', 20, 'Ask groups to prepare a chart or short presentation summarising identification of hardware components and their functions.', 'Prepare a chart or a short presentation summarising identification of hardware components and their functions and present it.', 'A correct summary of identification of hardware components and their functions is prepared and presented.'),
(720, 1002, 3, 'realisation', 10, 'Give a short oral or written exercise on identification of hardware components and their functions and mark it with the class.', 'Answer the short exercise on identification of hardware components and their functions and correct the answers with the class.', 'The exercise on identification of hardware components and their functions is correctly answered.'),
(721, 1003, 5, 'introduction', 10, 'Brainstorm with students on the challenges they have met concerning selection of installation tools and their proper use.', 'Share experiences and challenges met concerning selection of installation tools and their proper use.', 'Experiences concerning selection of installation tools and their proper use are shared.'),
(722, 1003, 4, 'development', 40, 'Provide guided hands-on exercises on selection of installation tools and their proper use and move around the laboratory giving individual support.', 'Perform the hands-on exercises on selection of installation tools and their proper use and ask for support where necessary.', 'The hands-on exercises on selection of installation tools and their proper use are correctly completed.'),
(723, 1003, 9, 'design', 20, 'Guide students to produce their own work sample demonstrating selection of installation tools and their proper use and to save it with a proper file name.', 'Produce and save a work sample that demonstrates selection of installation tools and their proper use.', 'A work sample demonstrating selection of installation tools and their proper use is correctly produced and saved.'),
(724, 1003, 3, 'realisation', 10, 'Ask each student to list the steps of selection of installation tools and their proper use in the correct order.', 'List the steps of selection of installation tools and their proper use in the correct order.', 'The steps of selection of installation tools and their proper use are listed in the correct order.'),
(725, 1004, 5, 'introduction', 10, 'Present a short real-life scenario connected to hardware specifications and component compatibility and ask students to suggest what should be done.', 'Discuss the scenario and suggest what should be done concerning hardware specifications and component compatibility.', 'Suggestions concerning hardware specifications and component compatibility are given from the scenario.'),
(726, 1004, 7, 'development', 40, 'Present a case study connected to hardware specifications and component compatibility and guide students to analyse it in groups.', 'Analyse the case study in groups and explain how it relates to hardware specifications and component compatibility.', 'Hardware specifications and component compatibility is correctly explained through the case study.'),
(727, 1004, 2, 'design', 20, 'Ask groups to compare two situations and identify how hardware specifications and component compatibility applies differently to each.', 'Compare the two situations and explain how hardware specifications and component compatibility applies to each.', 'The application of hardware specifications and component compatibility in different situations is correctly compared.'),
(728, 1004, 3, 'realisation', 10, 'Ask students to summarise the lesson on hardware specifications and component compatibility in three points and give them a related take-home task.', 'Summarise the lesson on hardware specifications and component compatibility in three points and note the take-home task.', 'The lesson on hardware specifications and component compatibility is correctly summarised in three points.');
